thiết trong lĩnh vực quản lý của đơn vị với Cục Thuế để xây dựng cơ sở dữ liệu
hóa đơn điện tử.$md$,$md$254-ndcp.signed_Điều40$md$,null,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
