NGƯỜI LẬP BIỂU KẾ TOÁN TRƯỞNG NGƯỜI ĐẠI DIỆN
(Ký, ghỉ rõ họ tên) (Ký, ghỉ rõ họ tên) THEO PHÁP LUẬT
(Ký, ghi rõ họ tên, đóng dấu)
b]) Doanh thu và thu nhập thuần (Mã số 01)
Chỉ tiêu này phản ánh tổng doanh thu thuần về bán hàng và cung cấp dịch
vụ và thu nhập khác sau khi đã trừ đi các khoản giảm trừ doanh thu trong kỳ báo
cáo (nếu có).
Số liệu để ghi vào chỉ tiêu này căn cứ tổng doanh thu bán hàng hóa, dịch vụ
và các khoản thu nhập khác trên Sỏ chỉ tiết doanh thu, chỉ phí hoặc Số doanh thu
bán hàng hóa, dịch vụ.
<!-- Page Break -->
# Page 31
31
b2) Các khoản chỉ phí (Mã số 02)
Chỉ tiêu này phản ánh tổng số chỉ phí phát sinh trong kỳ báo cáo gồm chỉ
phí nguyên vật liệu, chi phí nhân công, chỉ phí khấu hao tài sản có định, chỉ phí
dịch vụ mua ngoài, chỉ phí lãi vay,...
Số liệu để ghi vào chỉ tiêu này căn cứ vào tổng chỉ phí trong kỳ trên Số chỉ
tiết doanh thu, chỉ phí.
b3) Lợi nhuận kế toán trước thuế TNDN (Mã số 03)
Chỉ tiêu này phản ánh tổng số lợi nhuận thuần (hoặc lỗ) từ các hoạt động
của doanh nghiệp siêu nhỏ. Số liệu đẻ ghi vào chỉ tiêu này căn cứ vào số chênh
lệch giữa doanh thu và thu nhập thuần với các khoản chỉ phí trong kỳ.
Mã số 03 = Mã số 01 - Mã số 02.
b4) Chi phí thuế TNDN (Mã số 10)
Chỉ tiêu này phản ánh số chỉ phí thuế TNDN phải nộp trong năm báo cáo
theo quy định của pháp luật thuế. Số liệu để ghi vào chỉ tiêu này căn cứ vào tổng
số thuế TNDN phải nộp trên Số chỉ tiết doanh thu, chỉ phí.
b3) Lợi nhuận sau thuế TNDN (Mã số 20)
Chỉ tiêu này phản ánh số lợi nhuận sau thuế TNDN của doanh nghiệp siêu
nhỏ trong năm báo cáo.
Số liệu để ghi vào chỉ tiêu này căn cứ vào chênh lệch giữa lợi nhuận kế
toán trước thuế TNDN và chỉ phí thuế TNDN.
Mã số 20 = Mã số 03 - Mã số 10.
