định tại Thông tư số 132/2018/TT-BTC ngày 28/12/2018 của Bộ trưởng Bộ Tài
chính hướng dẫn chế độ kế toán cho doanh nghiệp siêu nhỏ đề thực hiện chuyển
vào các số kế toán liên quan khi áp dụng Thông tư này như sau:
sang số dư đầu kỳ của Số chỉ tiết tiền (chỉ tiết phần tiền mặt), số dư Nợ của TK
1112 “Tiền gửi ngân hàng” chuyển sang số dư đầu kỳ của Số chỉ tiết tiền (chỉ
tiết phần tiền gửi không kỳ hạn (tiền gửi để thanh toán) tại các ngân hàng và tổ
chức cung ứng dịch vụ thanh toán theo quy định của pháp luật;
<!-- Page Break -->
