dư Nợ TK 1318 “Các khoản nợ phải thu khác”, số dự Có TK 3311 “Phải trả
người lao động”, số dư Có TK 3312 “Các khoản trích theo lương”, số dư Có TK
3318 “Các khoản nợ phải trả khác”, chuyên sang số dư đầu kỳ tương ứng với
các khoản nợ phải thu hoặc các khoản nợ phải trả của Số chỉ tiết thanh toán công
nợ theo từng đối tượng công nợ;
trừ", số dự Có TK 33131 “Thuế GTGT phải nộp” chuyển sang các dòng tương
ứng với số thuế GTGT đầu vào hoặc số thuế GTGT đầu ra trên Số theo dõi
nghĩa vụ thuế GTGT;
1524 “Chi phí sản xuất kinh doanh dở dang”, TK 1526 “Thành phẩm, hàng
hóa” chuyển sang số dư đầu kỳ trên Số chỉ tiết vật liệu, dụng cụ, sản phẩm, hàng
