số dư đầu kỳ của Sổ Tài sản có định;
nghiệp”, TK 33138 “Thuế khác, phí, lệ phí và các khoản khác phải nộp Nhà
nước” chuyển sang số dư đầu kỳ của các cột tương ứng trên Sổ doanh thu bán
hàng hóa, dịch vụ hoặc Số theo dõi thuế GTGT (đối với thuế GTGT), Số chỉ tiết
doanh thu, chỉ phí (đối với thuế TNDN) và Số chỉ tiết thanh toán công nợ (đối
với thuế thu nhập cá nhân và các loại thuế khác);
hữu”, TK 4118 “Lợi nhuận sau thuế chưa phân phố" chuyển sang số dư đầu kỳ
của Số theo dõi vốn chủ sở hữu (chỉ tiết vốn góp của chủ sở hữu và lợi nhuận
