Tài chính đề nghiên cứu giải quyết/#4—
Nơi nhận:
- Ban Bí thư Trung ương Đảng;
~ Thủ tướng và các Phó Thủ tướng Chính phủ;
~ Văn phòng Trung ương và các Ban của Đảng;
~ Văn phòng Tổng Bí thư;
~ Văn phòng Quốc hội;
- Hội đồng dân tộc và các Ủy ban của Quốc Hội;
~ Văn phòng Chủ tịch nước;
~ Viện Kiểm sát Nhân dân tối cao;
~ Toà án Nhân dân tối cao;
- Kiểm toán Nhà nước;
- Ủy ban Trung ương Mặt trận Tổ quốc Việt Nam;
~ Liên đoàn Thương mại và Công nghiệp Việt Nam;
~ Các Bộ, cơ quan ngang Bộ;
~- HĐND, UBND các tỉnh, thành phố trực thuộc TW;
- Sở Tài chính các tỉnh, thành phó trực thuộc TW;
~ Thuế các tỉnh, thành phó trực thuộc TW;
- Cục Kiểm tra văn bản và Quản lý xử lý vi phạm hành chính
(Bộ Tư pháp);
- Hiệp hội Kế toán và Kiểm toán Việt Nam;
~ Hội Kiểm toán viên hành nghề Việt Nam;
- Cơ sở dữ liệu quốc gia về pháp luật;
- Công báo; Cổng thông tỉn điện tử: Chính phủ, Bộ Tài chính;
- Các đơn vị thuộc và trực thuộc Bộ Tài chính;
- Lưu: VT, Cục QLKT ( 50 bản), Jự$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611_Điều12$md$,null,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều1$md$,$md$TT111-2013$md$,$md$Điều 1. Người nộp thuế$md$,$md$Người nộp thuế
Người nộp thuê là cá nhân cư trú và cá nhân không cư trú theo quy định
tại Điều 2 Luật Thuế thu nhập cá nhân, Điều 2 Nghị định số 65/2013/NĐ-CP
1
<!-- Page Break -->
# Page 2
ngày 27/6/2013 của Chính phủ quy định chi tiết một số điều của Luật Thuế thu
nhập cá nhân và Luật sửa đổi, bỗ sung một số điều của Luật thuế thu nhập cá
nhân (sau đây gọi tất là Nghị định sô 65/2013/NĐ-CP), có thu nhập chịu thuế
theo quy định tại Điều 3 Luật Thuế thu nhập cá nhân và Điều 3 Nghị định số
65/2013/NĐ-CP.
Phạm vi xác định thu nhập chịu thuế của người nộp thuế như sau:
Đối với cá nhân cư trú, thu nhập chịu thuế là thu nhập phát sinh trong và
ngoài lãnh thô Việt Nam, không phân biệt nơi trả và nhận thu nhập.
Đối với cá nhân không cư trú, thu nhập chịu thuế là thu nhập phát sinh tại
Việt Ñam, không phân biệt nơi trả và nhận thu nhập.$md$,null,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều1_K1$md$,$md$TT111-2013$md$,$md$Khoản 1$md$,$md$Cá nhân cư trú là người đáp ứng một trong các điều kiện sau đây:
lịch hoặc trong 12 tháng liên tục kế từ ngày đầu tiên có mặt tại Việt Nam, trong,
đó ngày đến và ngày đi được tính là một (01) ngày. Ngày đến và ngày đi được
căn cứ vào chứng thực của cơ quan quản lý xuất nhập cảnh trên hộ chiếu (hoặc
giấy thông hành) của cá nhân khi đến và khi rời Việt Nam. Trường hợp nhập
cảnh và xuất cảnh trong cùng một ngày thì được tính chung là một ngày cư trú.
Cá nhân có mặt tại Việt Nam theo hướng dẫn tại điểm này là sự hiện diện
của cá nhân đó trên lãnh thổ Việt Nam.
Sau:
b.1) Có nơi ở thường xuyên theo quy định của pháp luật về cư trú:
b.1.1) Đối với công dân Việt Nam: nơi ở thường xuyên là nơi cá nhân
sinh sống thường xuyên, ôn định không có thời hạn tại một chỗ ở nhất định và
đã đăng ký thường trú theo quy định của pháp luật về cư trú.
b.1.2) Đối với người nước ngoài: nơi ở thường xuyên là nơi ở thường trú
ghi trong Thẻ thường trú hoặc nơi ở tạm trú khi đăng ký cấp Thẻ tạm trú do cơ
quan có thâm quyên thuộc Bộ Công an cấp.
b.2) Có nhà thuê để ở tại Việt Nam theo quy định của pháp luật về nhà ở,
với thời hạn của các hợp đông thuê từ 183 ngày trở lên trong năm tính thuê, cụ
thê như sau:
b.2.1) Cá nhân chưa hoặc không có nơi ở thường xuyên theo hướng dẫn
tại điểm b.1, khoản 1, Điều này nhưng có tổng số ngày thuê nhà để ở theo các
hợp đồng thuê từ 183 ngày trở lên trong năm tính thuế cũng được xác định là cá
nhân cư trú, kẻ cả trường hợp thuê nhà ở nhiều nơi.
b.2.2) Nhà thuê để ở bao gồm cả trường hợp ở khách sạn, ở nhà khách,
nhà nghỉ, nhà trọ, ở nơi làm việc, ở trụ sở cơ quan,... không phân biệt cá nhân tự
thuê hay người sử dụng lao động thuê cho người lao động.
Trường hợp cá nhân có nơi ở thường xuyên tại Việt Nam theo quy định
tại khoản này nhưng thực tế có mặt tại Việt Nam dưới 183 ngày trong năm tính
2
<!-- Page Break -->
# Page 3
thuế mà cá nhân không chứng minh được là cá nhân cư trú của nước nào thì cá
nhân đó là cá nhân cư trú tại Việt Nam.
Việc chứng minh là đối tượng cư trú của nước khác được căn cứ vào Giấy
chứng nhận cư trú. Trường, hợp cá nhân thuộc nước hoặc vùng lãnh thổ đã ký
kết Hiệp định thuế. với Việt Nam không có quy định cấp Giấy chứng nhận cư trú
thì cá nhân cung cấp bản chụp Hộ chiếu để chứng minh thời gian cư trú.
„2. Cá nhân không cư trú là người không đáp ứng, điều kiện nêu tại khoản
1, Điều này.
.3. Người nộp thuế trong một số trường hợp cụ thể được xác định như sau:
a.1) Trường hợp chỉ có một người đứng tên trong Giấy chứng nhận đăng
ký kinh doanh thì người nộp thuế là cá nhân đứng tên trong Giấy chứng nhận
đăng ký kinh doanh.
a.2) Trường hợp nhiều người cùng đứng tên trong Giấy chứng nhận đăng
ký kinh doanh (nhóm cá nhân kinh doanh), cùng tham gia kinh doanh thì người
nộp thuế là từng thành viên có tên trong Giấy chứng nhận đăng ký kinh doanh.
a.3) Trường hợp trong một hộ gia đình có nhiều người cùng tham gia kinh
doanh nhưng chỉ có một người đứng tên trong Giấy chứng nhận đăng ký kinh
doanh thì người nộp thuế là cá nhân đứng tên trong Giấy chứng nhận đăng ký
kinh doanh.
a.4) Trường hợp cá nhân, hộ gia đình thực tế có kinh doanh nhưng không
có Giấy chứng nhận đăng ký kinh doanh (hoặc Chứng chỉ, Giấy phép hành
nghề) thì người nộp thuế là cá nhân đang thực hiện hoạt động kinh doanh.
a.5) Đối với hoạt động cho thuê nhà, quyền sử dụng đất, mặt nước, tài sản
khác không có đăng ký kinh doanh, người nộp thuế là cá nhân sở hữu nhà,
quyền sử dụng đất, mặt nước, tài sản khác. Trường hợp nhiều cá nhân cùng sở
hữu nhà, quyền sử dụng đất, mặt nước, tài sản khác thì người nộp thuế là từng
cá nhân có quyên sở hữu, quyền sử dụng.
b.1) Trường hợp chuyển nhượng bất động sản là đồng sở hữu, người nộp
thuế là từng cá nhân đồng sở hữu bất động sản.
b.2) Trường hợp uỷ quyền quản lý bất động sản mà cá nhân được uỷ
quyền có quyên chuyên nhượng bất động sản hoặc có các quyền như đối với cá
nhân sở hữu. bất động sản theo quy định của pháp luật thì người nộp thuế là cá
nhân ủy quyền bất động sản.
b.3) Trường hợp, chuyển nhượng, chuyển giao quyền sở hữu, quyền sử
dụng các đối tượng được bảo hộ theo quy định của Luật Sở hữu trí tuệ, Luật
Chuyên giao công nghệ mà đối tượng chuyển giao, chuyên quyền là đồng sở
hữu, đồng tác giả của nhiều cá nhân (nhiều tác giả) thì người nộp thuế là từng cá
nhân có quyền sở hữu, quyền tác giả và hưởng thu nhập từ việc chuyên giao,
chuyển quyền nêu trên.
3
