insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều2_K1$md$,$md$TT111-2013$md$,$md$Khoản 1$md$,$md$Thu nhập từ kinh doanh
Thu nhập từ kinh doanh là thu nhập có được từ hoạt động sản xuất, kinh
doanh trong các lĩnh vực sau:
2) Thu nhập từ sản xuất, kinh doanh hàng hoá, dịch vụ thuộc tất cả các
lĩnh vực, ngành nghệ kinh doanh theo quy định của pháp luật như: sản xuất,
kinh doanh hàng hoá; xây dựng; vận tải; kinh doanh ăn uông; kinh doanh dịch
vụ, kê cả dịch vụ cho thuê nhà, quyên sử dụng đât, mặt nước, tài sản khác.
vực, ngành nghề được cấp giầy phép hoặc chứng chỉ hành nghề theo quy định
của pháp luật.
làm muôi, nuôi trông, đánh bắt thuỷ sản không đáp ứng đủ điều kiện được miễn
thuế hướng dẫn tại điểm e, khoản 1, Điều 3 Thông tư này.$md$,$md$TT111-2013_Điều2$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
