insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều2_K2$md$,$md$TT111-2013$md$,$md$Khoản 2$md$,$md$Thu nhập từ tiền lương, tiền công,
Thu nhập từ tiền lương, tiền công là thu nhập người lao động nhận được
từ người sử dụng lao động, bao gôm:
dưới các hình thức băng tiên hoặc không băng tiên.
b.1) Trợ cấp, phụ cấp ưu đãi hàng tháng và trợ cấp một lần theo quy định
của pháp luật về ưu đãi người có công.
<!-- Page Break -->
# Page 5
“
b.2) Trợ cấp hàng tháng, trợ cấp một lần đối với các đối tượng tham gia
kháng chiến, bảo vệ tổ quốc, làm nhiệm vụ quốc tế, thanh niên xung phong đã
hoàn thành nhiệm vụ.
b.3) Phụ cấp quốc phòng, an ninh; các khoản trợ cấp đối với lực lượng vũ
trang.
b. 4) Phụ cấp độc "hại, nguy hiểm đối với những ngành, nghề hoặc công
việc ở nơi làm việc có yêu tố độc hại, nguy hiểm.
b.5) Phụ cấp thu hút, phụ cấp khu vực.
.b.6) Trợ cấp khó khăn đột xuất, trợ cấp tai nạn lao động, bệnh nghề
nghiệp, trợ cấp một lần khi sinh con hoặc nhận nuôi con nuôi, mức hưởng chế
độ thai sản, mức hưởng dưỡng sức, phục hồi sức khoẻ sau thai sản, trợ cập do
suy giảm khả năng lao động, trợ cấp hưu trí một lần, tiền tuất hàng tháng, trợ
câp thôi việc, trợ cấp mất việc làm, trợ cấp thất nghiệp và các khoản trợ cấp
khác theo quy định của Bộ luật Lao động và Luật Bảo hiểm xã hội.
b.7) Trợ cấp đối với các đối tượng được bảo trợ xã hội theo quy định của
pháp luật.
b.8) Phụ cấp phục vụ đối với lãnh đạo cấp cao.
b.9) Trợ cấp một lần đối với cá nhân khi chuyên. công tác đến vùng có
điều kiện kinh tế xã hội đặc biệt khó khăn, hỗ trợ một lần đối với cán bộ công
chức làm công tác về chủ quyền biển đảo theo quy định của pháp luật. Trợ cấp
chuyển vùng một lần đối với người nước ngoài đến cư trú tại Việt Nam, người
Việt Nam đi làm việc ở nước ngoài.
b.10) Phụ cấp đối với nhân viên y tế thôn, bản.
b.]11) Phụ cấp đặc thù ngành nghề.
Các khoản phụ cấp, trợ cấp và mức phụ cấp, trợ cấp không tính vào thu
nhập chịu thuế hướng dẫn tại điểm b, khoản 2, Điều này phải được cơ quan Nhà
nước có thâm quyền quy định.
Trường hợp các văn bản hướng dẫn về các khoản phụ cấp, trợ cấp, mức
phụ cấp, trợ cấp áp dụng đối với khu vực Nhà nước thì các thành phần kinh tế
khác, các cơ sở kinh doanh khác được căn cứ vào danh mục và mức phụ cấp, trợ
cấp hướng dẫn đối với khu vực Nhà nước để tính trừ.
Trường hợp khoản phụ cấp, trợ cấp nhận được cao hơn mức phụ cấp, trợ
cấp theo hướng dẫn nêu trên thì phần vượt phải tính vào thu nhập chịu thuế.
Riêng trợ cấp chuyển vùng một lần đối với người nước ngoài đến cư trú
tại Việt Nam, người Việt Nam đi làm việc ở nước ngoài được trừ theo mức ghi
tại Hợp đồng lao động hoặc thỏa ước lao động tập thê.
bán hàng hóa, lên hoa hồng môi giới; tiền tham gia các đề tài nghiên cứu khoa
học, kỹ thuật; tiền tham gia các dự án, đề án; tiền nhuận bút theo quy định của
pháp luật về chế độ nhuận bút; tiền tham gia các hoạt động giảng dạy; tiền tham
bì
<!-- Page Break -->
# Page 6
gia biểu diễn văn hoá, nghệ thuật, thể dục, thể thao; tiền dịch vụ quảng cáo; tiên
địch vụ khác, thù lao khác.
doanh nghiệp, ban kiểm soát doanh nghiệp, ban quản lý dự án, hội đông quản
lý, các hiệp hội, hội nghề nghiệp và các tô chức khác. `
tiền công do người sử dụng lao động trả mà người nộp thuế được hưởng dưới
mọi hình thức:
đ.1) Tiền nhà ở, điện, nước và các dịch vụ kèm theo (nếu có).
Trường hợp cá nhân ở tại trụ sở làm việc thì thu nhập chịu thuế căn cứ
vào tiên thuê nhà hoặc chỉ phí khẩu hao, tiền điện, nước và các dịch vụ khác
tính theo tỷ lệ giữa diện tích cá nhân sử dụng với diện tích trụ sở làm việc.
Khoản tiền thuê nhà do đơn vị sử dụng lao động trả hộ tính vào thu nhập
chịu thuế theo số thực tế trả hộ nhưng không vượt quá 15% tổng thu nhập chịu
thuế (chưa bao gồm tiền thuê nhà) tại đơn vị.
đ.2) Khoản tiền phí mua bảo hiểm nhân thọ, bảo hiểm không bắt buộc
khác, tiền đóng góp quỹ hưu trí tự nguyện do người sử dụng lao động mua hoặc
đóng góp cho người lao động đối với những sản phẩm bảo hiểm có tích lũy về
phí bảo hiểm.
_đ.3) Phí hội viên và các khoản chỉ dịch vụ khác phục vụ cho cá nhân theo.
yêu cầu như: chăm sóc sức khoẻ, vui chơi, thể thao, giải trí, thẩm mỹ, cụ thể
như sau:
đ.3.1) Khoản phí hội viên (như thẻ hội viên sân gôn, sân quần vợt, thẻ
sinh hoạt câu lạc bộ văn hoá nghệ thuật, thể dục thể thao...) nếu thẻ có ghi đích
danh cá nhân hoặc nhóm cá nhân sử dụng. Trường hợp thẻ được sử dụng chung,
không ghỉ tên cá nhân hoặc nhóm cá nhân sử dụng thì không tính vào thu nhập
chịu thuế.
đ.3.2) Khoản chỉ dịch vụ khác phục vụ cho cá nhân trong hoạt động chăm
sóc sức khoẻ, vui chơi, giải trí thẩm mỹ... nếu nội dung chỉ trả ghi rõ tên cá
nhân được hưởng. Trường hợp nội dung chỉ trả phí dịch vụ không ghi tên cá
nhân được hưởng mà chỉ chung cho tập thể người lao động thì không tính vào
thu nhập chịu thuế.
đ.4) Phần khoán chi văn phòng phẩm, công tác phí, điện thoại, trang
phục,... cao hơn mức quy định hiện hành của Nhà nước. Mức khoán chi không
tính vào thu nhập chịu thuế đối với một số trường hợp như sau:
đ.4.1) Đối với cán bộ, công chức và người làm việc trong các cơ quan
hành chính sự nghiệp, Đảng, đoàn thể, Hội, Hiệp hội: mức khoán chỉ áp dụng
theo văn bản hướng dẫn của Bộ Tài chính.
đ.4.2) Đối với người lao động làm việc trong các tổ chức kinh doanh, các
văn phòng đại diện: mức khoán chỉ áp dụng phù hợp với mức xác định thu nhập
6
<!-- Page Break -->
# Page 7
chịu thuế thu nhập doanh nghiệp theo các văn bản hướng dẫn thi hành Luật thuế
thu nhập doanh nghiệp.
đ.4.3) Đối với người lao động làm việc trong các tô chức quốc tế, các văn
phòng đại diện của tô chức nước ngoài: mức khoán chỉ thực hiện theo quy định
của Tổ chức quốc tế, văn phòng đại diện của tổ chức nước ngoài.
đ.5) Đối với khoản chỉ về phương tiện phục vụ đưa đón tập thể người lao
động từ nơi ở đên nơi làm việc và ngược lại thì không tính vào thu nhập chịu
thuế của người lao động; trường hợp chỉ đưa đón riêng từng cá nhân thì phải
tính vào thu nhập chịu thuê của cá nhân được đưa đón.
đ.6) Đối với khoản chỉ trả hộ tiền đào tạo nâng cao trình độ, tay nghề cho
người lao động phủ hợp với công việc chuyên môn, nghiệp vụ của người lao
động hoặc theo kê hoạch của đơn vị sử dụng lao động thì không tính vào thu
nhập của người lao động.
đ.7) Các khoản lợi ích khác.
Các khoản lợi ích khác mà người sử dụng lao động chỉ cho người lao
động như: chỉ trong các ngày nghỉ, lễ; thuê các dịch vụ tư vấn, thuê khai thuế
cho đích danh một hoặc một nhóm cá nhân; chỉ cho người giúp việc gia đình
như lái xe, người nâu ăn, người làm các công việc khác trong gia đình theo hợp
đồng...
kể cả thưởng bằng chứng khoán, trừ các khoản tiền thưởng sau đây:
e1) Tiền thưởng kèm theo các danh hiệu được Nhà nước phong tặng, bao
gồm cả tiền thưởng kèm theo các danh hiệu thi đua, các hình thức khen thưởng,
theo quy định của pháp luật về thi đua, khen thưởng, cụ thể:
e.1.1) Tiền thưởng kèm theo các danh hiệu thi đua như Chiến sĩ thi đua
toàn quốc; Chiến sĩ thi đua cấp Bộ, ngành, đoàn thể Trung, ương, tỉnh, thành phố
trực thuộc Trung ương; Chiến sĩ thi đua cơ sở, Lao động tiên tiến, Chiến sỹ tiên
tiên.
e.1.2) Tiền thưởng kèm theo các hình thức khen thưởng.
e.1.3) Tiền thưởng kèm theo các danh hiệu do Nhà nước phong tặng.
e.1.4) Tiền thưởng kèm theo các giải thưởng do các Hội, tổ chức thuộc
các Tổ chức chính trị, Tổ chức chính trị - xã hội, Tổ chức xã hội, Tổ chức xã hội
- nghề nghiệp của Trung ương và địa phương trao tặng phù hợp với điều lệ của
tổ chức đó và phù hợp với quy định của Luật Thi đua, Khen thưởng.
e.1.5) Tiền thưởng kèm theo giải thưởng Hồ Chí Minh, giải thưởng Nhà
nước.
e.1.6) Tiền thưởng kèm theo Kỷ niệm chương, Huy hiệu.
e.1.7) Tiền thưởng kèm theo Bằng khen, Giấy khen.
Thắm quyền ra quyết định khen thưởng, mức tiền thưởng kèm theo các
danh hiệu thi đua, hình thức khen thướng nêu trên phải phù hợp với quy định
1
<!-- Page Break -->
# Page 8
của Luật Thi đua,khen thưởng.
e.2) Tiền thưởng kèm theo giải thưởng quốc gia, giải thưởng quốc tế
được Nhà nước Việt Nam thừa nhận.
e.3) Tiền thưởng về cải tiến kỹ thuật, sáng chế, phát minh được cơ quan
Nhà nước có thâm quyên công nhận.
e.4) Tiền thưởng về việc phát hiện, khai báo hành vi vi phạm pháp luật
` với cơ quan Nhà nước có thâm quyền.
` g.1) Khoản hỗ trợ của người sử dụng lao động cho việc khám chữa bệnh
hiểm nghèo cho bản thân người lao động và thân nhân của người lao động.
g1. D Thân nhân của người lao động trong trường hợp này bao gồm: con
đẻ, con nuôi hợp pháp, con ngoài giá thú, con riêng của vợ hoặc chồng; vợ hoặc
chỗng; cha đẻ, mẹ đẻ; cha vợ, mẹ vợ (hoặc cha chồng, mẹ chồng); cha dượng,
mẹ kê; cha nuôi, mẹ nuôi hợp pháp.
g.1.2) Mức hỗ trợ không tính vào thu nhập chịu thuế là số tiền thực tế chỉ
trả theo chứng từ trả tiền viện phí nhưng tối đa không quá số tiền trả viện phí
của người lao động và thân nhân người lao động sau khi đã trừ số tiền chỉ trả
của tô chức bảo hiêm.
ø.1.3) Người sử dụng lao động chỉ tiền hỗ trợ có trách nhiệm: lưu giữ bản
sao chứng từ trả tiền viện phí có xác nhận của người sử dụng lao động (trong
trường hợp người lao động và thân nhân người lao động trả phân còn lại sau khi
tổ chức bảo hiểm trả trực tiếp với cơ sở khám chữa bệnh) hoặc bản sao chứng từ
trả viện phí; bản sao chứng từ chỉ bảo hiểm y tế có xác nhận của người sử dụng,
lao động (trong trường hợp người lao động và thân nhân người lao động trả toàn
bộ viện phí, tô chức bảo hiểm trả tiền bảo hiểm cho người lao động và thân
nhân người lao động) cùng với chứng từ chỉ tiền hỗ trợ cho người lao động và
thân nhân người lao động mắc bệnh hiểm nghèo.
g.2) Khoản tiền nhận được theo quy định về sử dụng phương tiện đi lại
trong cơ quan Nhà nước, đơn vị sự nghiệp công lập, tổ chức Đảng, đoàn thể.
ø.3) Khoản tiền nhận được theo chế độ nhà ở công vụ theo quy định của
pháp luật.
g.4) Các khoản nhận được ngoài tiền lương, tiền công do tham gia ý kiến,
thâm định, thẩm tra các văn bản pháp luật, Nghị quyết, các báo cáo chính trị;
tham gia các đoàn kiểm tra giám sát; tiếp cử tri, tiếp công dân; trang phục và
các công việc khác có liên quan đến phục vụ trực tiếp | hoạt động của Văn phòng
Quốc hội, Hội đồng dân tộc và các Ủy ban của Quốc hội, các Đoàn đại biểu
Quốc hội; Văn phòng Trung ương và các Ban của Đảng; Văn phòng Thành ủy,
Tỉnh ủy và các Ban của Thành uỷ, Tỉnh ủy.
g.5) Khoản tiền ăn giữa ca, ăn trưa do người sử dụng lao động tô chức
bữa ăn giữa ca, ăn trưa cho người lao động dưới các hình thức như trực tiếp nâu
ăn, mua suất ăn, cấp phiếu ăn.
8
<!-- Page Break -->
# Page 9
Trường _ hợp người sử dụng lao động không tổ chức bữa ăn giữa ca, ăn
trưa mà chỉ tiền cho người lao động thì không tính vào thu nhập chịu thuế của
cá nhân nếu mức chỉ phù hợp với hướng dẫn của Bộ Lao › động - Thương binh và
Xã hội. Trường hợp mức chỉ cao hơn mức hướng dẫn của Bộ Lao động -
Thương binh và Xã hội thì phần chỉ vượt mức phải tính vào thu nhập chịu thuế
của cá nhân.
Mức chỉ cụ thể áp dụng đối với doanh nghiệp Nhà nước và các tổ chức,
đơn vị thuộc cơ quan hành chính sự nghiệp, Đảng, Đoàn thể, các Hội không quá
mức hướng dẫn của Bộ Lao động - Thương binh và Xã hội. Đối với các doanh
nghiệp ngoài Nhà nước và các tô chức khác, mức chỉ do thủ trưởng đơn vị
thống nhất với chủ tịch công đoàn quyết định nhưng tối đa không vượt quá mức
áp dụng đối với doanh nghiệp Nhà nước.
g.6) Khoản tiền mua vé máy bay khứ hồi do người sử dụng lao động trả
hộ (hoặc thanh toán) cho người lao động là người nước ngoài làm việc tại Việt
Nam, người lao động là người Việt Nam làm việc ở nước ngoài về phép mỗi
năm một lần.
Căn cứ xác định khoản tiền mua vé máy bay là hợp đồng lao động và
khoản tiền thanh toán vé máy bay từ Việt Nam đến quốc gia người nước ngoài
mang quốc tịch hoặc quốc gia nơi gia đình người nước ngoài sinh sống và
ngược lại; khoản tiền thanh toán vé máy bay từ quốc gia nơi người Việt Nam
đang làm việc về Việt Nam và ngược lại.
g7) Khoản tiền học phí cho con của người lao động nước ngoài làm việc
tại Việt Nam học tại Việt Nam, con của người lao động Việt Nam đang làm việc
ở nước ngoài học tại nước ngoài theo bậc học từ mắm non đến trung học phổ
thông do người sử dụng lao động trả hộ. -
g.8) Các khoản thu nhập cá nhân nhận được từ các Hội, tổ chức tài trợ
không phải tính vào thu nhập chịu thuế thu nhập cá nhân nếu cá nhân nhận tài
trợ là thành viên của Hội, của tổ chức; kinh phí tài trợ được sử dụng từ nguồn
kinh phí Nhà nước hoặc được quản lý theo quy định của Nhà nước; việc sáng
tác các tác phẩm văn học nghệ thuật, công trình nghiên cứu khoa học... thực
hiện nhiệm vụ chính trị của Nhà nước hay theo chương trình hoạt động phù hợp
với Điều lệ của Hội, tổ chức đó.
g.9) Các khoản thanh toán mà người sử dụng lao động trả để phục vụ việc
điều động, luân chuyển người lao động là người nước ngoài làm việc tại Việt
Nam theo quy định tại hợp đồng lao động, tuân thủ lịch lao động chuẩn theo
thông lệ quôc tế của một số ngành như dầu khí, khai khoáng.
Căn cứ xác định là hợp đồng lao động và khoản tiền thanh toán vé máy
bay từ Việt Nam đến quốc gia nơi người nước ngoài cư trú và ngược lại.
Ví dụ 1: Ông X là người nước ngoài được nhà thầu dầu khí Y điều
chuyển đến làm việc tại giàn khoan trên thêm lục địa Việt Nam. Theo quy định
tại hợp đồng lao động, chu kỷ làm việc của ông X tại giàn khoan là 28 ngày liên
tục, sau đó được nghỉ 28 ngày. Nhà thâu Y thanh toán cho ông X các khoản tiền
