insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều2_K7$md$,$md$TT111-2013$md$,$md$Khoản 7$md$,$md$Thu nhập từ bản quyền
Thu nhập từ bản quyền. là thu nhập nhận được khi chuyển nhượng,
chuyển giao quyền sở hữu, quyền sử dụng các đối tượng của quyên sở hữu trí
tuệ theo quy định của Luật Sở hữu trí tuệ; thu nhập từ chuyển giao công nghệ
theo quy định của Luật Chuyển giao công nghệ. Cụ thể như sau:
của Luật Sở hữu trí tuệ và các văn bản hướng dẫn liên quan, bao gồm:
.a.1) Đối tượng quyền tác giả bao gồm các tác phẩm văn học, tác phẩm
nghệ thuật, khoa học; đối tượng, quyền liên quan đến quyền tác giả bao gồm: ghỉ
hình, ghi âm chương trình phát sóng, tín hiệu vệ tỉnh mang chương trình được
mã hoá.
a2) Đối tượng, quyền sở hữu công nghiệp bao gồm sáng chế, kiểu dáng
công nghiệp, thiết kế bố trí mạch tích hợp bán dẫn, bí mật kinh doanh, nhãn
hiệu, tên thương mại và chỉ dẫn địa lý.
a.3) Đối tượng quyền đối với giống cây trồng là vật liệu nhân giống và
vật liệu thu hoạch.
7 của Luật Chuyên giao công nghệ, bao gồm:
b.1) Chuyển giao các bí quyết kỹ thuật.
b.2) Chuyển giao kiến thức kỹ thuật về công nghệ dưới dạng phương án
công nghệ, quy trình công nghệ, giải pháp kỹ thuật, công thức, thông sô kỹ
thuật, bản vẽ, sơ đồ kỹ thuật, chương trình máy tính, thông tin dữ liệu.
pháp hợp lý hoá sản xuất, đổi mới công nghệ.
b.3) Chuyển giao
Thu nhập từ chuyển giao, chuyển quyền các đối tượng của quyền sở hữu
trí tuệ và chuyển giao công nghệ nêu trên bao gồm cả trường hợp chuyển
nhượng lại.$md$,$md$TT111-2013_Điều2$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
