insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều2_K8$md$,$md$TT111-2013$md$,$md$Khoản 8$md$,$md$Thu nhập từ nhượng quyền thương mại
Nhượng quyền thương mại là hoạt động thương mại, theo đó bên nhượng
quyền cho phép và yêu cầu bên nhận quyên tự mình tiến hành việc mua bán
hàng hóa, cung ứng dịch vụ theo các điều kiện của bên nhượng quyền tại hợp
đồng nhượng quyền thương mại.
Thu nhập từ nhượng quyền thương mại là các khoản thu nhập mà cá nhân
nhận được từ các hợp đồng nhượng quyền thương mại nêu trên, bao gồm cả
trường hợp nhượng lại quyên thương mại theo quy định của pháp luật về
nhượng quyên thương mại.$md$,$md$TT111-2013_Điều2$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều2_K9$md$,$md$TT111-2013$md$,$md$Khoản 9$md$,$md$Thu nhập từ nhận thừa kế
Thu nhập từ nhận thừa kế là khoản thu nhập mà cá nhân nhận được theo
di chúc hoặc theo quy định của pháp luật về thừa kế, cụ thể như sau:
12
<!-- Page Break -->
# Page 13
phiếu, trái phiếu, tín phiếu, chứng chỉ quỹ và các loại chứng khoán khác theo
quy định của Luật Chứng khoán; cỏ phần của cá nhân trong công ty cổ phần
theo quy định của Luật Doanh nghiệp.
doanh bao gôm: vỗn góp trong công ty trách nhiệm hữu hạn, hợp tác xã, công ty
hợp danh, hợp đồng hợp tác kinh doanh; vốn trong doanh nghiệp tư nhân, cơ sở
kinh doanh của cá nhân; vốn trong các hiệp hội, quỹ được phép thành lập theo
quy định của pháp luật hoặc toàn bộ cơ sở kinh doanh nếu là doanh nghiệp tư
nhân, cơ sở kinh doanh của cá nhân.
quyền sử dụng đất có tài sản gắn liên với đất; quyền sở hữu nhà, kể cả nhà ở
hình thành trong tương lai; kết câu hạ tầng và các công trình xây dựng gắn liền
với đất, kể cả công trình xây dựng hình thành trong tương lai; quyền thuê đất;
quyển thuê mặt nước; các khoản thu nhập khác nhận được từ thừa kế là bất
động sản dưới mọi hình thức; trừ thu nhập từ thừa kế là bất động sản theo
hướng dẫn tại điểm d, khoản 1, Điều 3 Thông tư này.
