insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều2_K10$md$,$md$TT111-2013$md$,$md$Khoản 10$md$,$md$Thu nhập từ nhận quà tặng.
Thu nhập từ nhận quà tặng là khoản thu nhập của cá nhân nhận được từ
các tổ chức, cá nhân trong và ngoài nước, cụ thể như sau:
3) Đối với nhận quà tặng là chứng khoán bao gồm: cổ phiếu, quyền mua
cỗ phiếu, trái phiếu, tín phiếu, chứng, chỉ quỹ và các loại chứng khoán khác theo
quy định của Luật Chứng khoán; cỗ phần của các cá nhân trong công ty cổ phần
theo quy định của Luật Doanh nghiệp.
kinh doanh bao gồm: vốn trong công ty trách nhiệm hữu hạn, hợp tác xã, công
ty hợp danh, hợp đồng hợp tác kinh doanh, vốn trong doanh nghiệp tư nhân, cơ
sở kinh doanh của cá nhân, vốn trong các hiệp hội, quỹ được phép thành lập
theo quy định của pháp luật hoặc toàn bộ cơ sở kinh doanh nếu là doanh nghiệp
tư nhân, cơ sở kinh doanh của cá nhân.
quyền sử dụng đất có tài sản săn liền với đất; quyền sở hữu nhà, kể cả nhà ở
hình thành trong tương lai; kết cấu hạ tầng và các công trình xây dựng gắn liền
với đất, kể cả công trình xây dựng hình thành trong tương lai; quyền thuê đất;
quyền thuê mặt nước; các khoản thu nhập khác nhận được từ thừa kế là bất
động sản dưới mọi hình thức; trừ thu nhập từ quà tặng là bất động sản hướng
dẫn tại điểm d, khoản 1, Điều 3 Thông tư này.
