insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều3_K1$md$,$md$TT111-2013$md$,$md$Khoản 1$md$,$md$Căn cứ quy định tại Điều 4 của Luật Thuế thu nhập cá nhân, Điều 4
của Nghị định số 65/2013/NĐ-CP, các khoản thu nhập được miễn thuế bao
gồm:
.a) Thu nhập từ chuyển nhượng bất động sản (bao gồm cả nhà ở hình
thành trong tương lai, công trình xây dựng hình thành trong tương lai theo quy
định pháp luật về kinh doanh bất động sản) giữa: vợ với chồng; cha đẻ, mẹ đẻ
với con đẻ; cha nuôi, mẹ nuôi với con nuôi; cha chồng, mẹ chông với con dâu;
bố vợ, mẹ vợ với con rễ; ông nội, bà nội với cháu nội; ông ngoại, bà ngoại với
cháu ngoại; anh chị em ruột với nhau.
Trường hợp bất động sản (bao gồm cả nhà ở hình thành trong tương lai,
công trình xây dựng hình thành trong tương lai theo quy định pháp luật về kinh
doanh bất động sản) do vợ hoặc chồng tạo lập trong thời kỳ hôn nhân được xác
định là tài sản chung của vợ chồng, khi ly hôn được phân chia theo thỏa thuận
hoặc do tòa án phán quyết thì việc phân chia tải sản này thuộc diện được miễn
thuế.
liền với đất ở của cá nhân trong trường hợp người chuyển nhượng chỉ có duy
nhất một nhà ở, quyền sử dụng đất ở tại Việt Nam.
b.1) Cá nhân chuyển nhượng nhà ở, quyền sử dụng đất ở được miễn thuế
theo hướng dẫn tại điểm b, khoản 1, Điều này phải đồng thời đáp ứng các điều
kiện sau:
b.1.1) Chỉ có duy nhất quyền sở hữu một nhà ở hoặc quyền sử dụng một
thửa đất ở (bao gồm cả trường hợp có nhà ở hoặc công trình xây dựng gắn liền
với thửa đất đó) tại thời điểm chuyên nhượng, cụ thể như sau:
b.1.1.1) Việc xác định quyền sở hữu nhà ở, quyền sử dụng đất ở căn cứ
vào Giây chứng nhận quyền sử dụng đất, quyền sở hữu nhà ở và tài sản khác
gắn liền với đất.
b.1.1.2) Trường hợp chuyển nhượng nhà ở có chung quyền sở hữu, đất ở
có chung quyên sử dụng thì chỉ cá nhân chưa có quyền sở hữu nhà ở, quyền sử
dụng đất ở nơi khác được miễn thuế, cá nhân có chung quyền sở hữu nhà ở,
quyên sử dụng ‹ đất ở còn có quyền sở hữu nhà ở, quyên sử dụng đất ở khác
không được miễn thuế.
b.1.1.3) Trường hợp vợ chồng có chung quyền sở hữu nhà ở, quyền sử
dụng đất ở và cũng là duy nhất của chung vợ chồng nhưng vợ hoặc chồng còn
có nhà ở, đất ở riêng, khi chuyển. nhượng nhà ở, đất ở của chung vợ chồng thì
vợ hoặc chồng chưa có nhà ở, đất ở riêng được miễn thuế; chồng hoặc vợ có
nhà ở, đất ở riêng không được miễn thuế.
14
<!-- Page Break -->
# Page 15
b.1.2) Có quyền sở hữu nhà ở, quyền sử dụng đất ở tính đến thời điểm
chuyển nhượng tối thiểu là 183 ngày.
Thời điểm xác định quyền sở hữu nhà ở, quyền sử dụng đất ở là ngày cấp
Giấy chứng nhận quyền sử dụng đất, quyền sở hữu nhà ở và tài sản khác găn
liền với đất.
b.1.3) Chuyển nhượng toàn bộ nhà ở, đất ở.
Trường hợp cá nhân có quyền hoặc chung, quyền sở hữu nhà, quyền sử
dụng đất ở duy nhất nhưng chuyển nhượng một phân thì không được miễn thuế
cho phần chuyển nhượng đó.
b.2) Nhà ở, đất ở duy nhất được miễn thuế do cá nhân chuyền nhượng bất
động sản tự khai và chịu trách nhiệm. Nếu phát hiện không đúng sẽ bị xử lý truy
thu thuế và phạt về hành vì vi phạm pháp luật thuế theo quy định của pháp luật
về quản lý thuế.
b.3) Trường hợp chuyển nhượng nhà ở ở, công trình Xây dựng hình thành
trong tương lai không, thuộc diện được miễn thuế thu nhập cá nhân theo hướng
dẫn tại điểm b, khoản 1, Điều này.
đất không phải trả tiền hoặc được giảm tiền sử dụng đất theo quy định của pháp
luật.
Trường hợp cá nhân được miễn, giảm tiền sử dụng đất khi giao đất, nếu
chuyển nhượng diện tích đất được miễn, giảm tiền sử dụng đất thì khai, nộp
thuê đối với thu nhập từ chuyển nhượng bất động sản hướng dẫn tại Điều 12
Thông tư này.
công trình xây dựng hình thành trong tương lai theo quy định của pháp luật về
kinh doanh bất động sản) giữa: vợ với chồng, cha đẻ, mẹ đẻ với con đẻ; cha
nuôi, mẹ nuôi với con nuôi; cha chồng, mẹ chồng với con dâu; cha vợ, mẹ vợ
với con rể, ông nội, bà nội với cháu nội, ông ngoại, bà ngoại với cháu ngoại;
anh chị em ruột với nhau.
nghiệp nhưng không, làm thay đổi mục đích sử dụng đất của hộ gia đình, cá
nhân trực tiếp sản xuất nông nghiệp, được Nhà nước giao để sản xuất.
l ©) Thu nhập của hộ gia đình, cá nhân trực tiếp tham gia vào hoạt động sản
xuất nông nghiệp, lâm nghiệp, làm muối, nuôi trồng, đánh bắt thuỷ sản chưa
qua chế biến hoặc chỉ qua sơ chế thông thường chưa chế biến thành sản phẩm
khác.
Hộ gia đình, cá nhân trực tiếp tham gia vào hoạt động sản xuất theo
hướng dẫn tại điểm này phải thoả mãn đồng thời các điều kiện sau:
e.1) Có quyền sử dụng đất, quyền thuê đất, quyền sử dụng mặt nước,
quyền thuê mặt nước hợp pháp để sản xuất và trực tiếp tham gia lao động sản
xuất nông nghiệp, lâm nghiệp, làm muối, nuôi trồng thuỷ sản.
t§
<!-- Page Break -->
# Page 16
Trường hợp đi thuê lại đất, mặt nước của tổ chức, cá nhân khác thì phải
có văn bản thuê đất, mặt nước theo quy định của pháp luật (trừ trường hợp hộ
gia đình, cá nhân nhận khoán trồng rừng, chăm sóc, quản lý và bảo vệ rừng với
các công ty Lâm nghiệp). Đối với hoạt động đánh bắt thuỷ sản phải có giấy
chứng nhận quyền : sở hữu hoặc hợp đồng thuê tàu, thuyền sử dụng vào mục đích
đánh bắt và trực tiếp tham gia hoạt động đánh bắt thuỷ sản (trừ trường hợp đánh
bắt thuỷ sản trên sông bằng hình thức đáy sông (đáy cá) và không thuộc những,
hoạt động khai thác thuỷ sản bị cấm theo quy định của pháp luật).
e.2) Thực tế cư trú tại địa phương nơi diễn ra hoạt động sản xuất nông
nghiệp, lâm nghiệp, làm muối, nuôi trồng, đánh bắt thuỷ sản.
Địa phương nơi diễn ra hoạt động sản xuất nông nghiệp, lâm nghiệp, làm
muối, nuôi trồng thuỷ sản theo hướng dẫn này là à quận, huyện, thị xã, thành phố
thuộc tỉnh (gọi chung là đơn vị hành chính cập huyện) hoặc huyện giáp ranh với
nơi diễn ra hoạt động sản xuất.
Riêng đối với hoạt động đánh bắt thuỷ sản thì không phụ thuộc nơi cư trú.
e.3) Các sản phẩm nông nghiệp, lâm nghiệp, làm muối, nuôi trồng đánh
bắt thuỷ sản chưa chế biến thành các sản phẩm Ì khác hoặc mới chỉ sơ chê thông
thường là sản phẩm mới được làm sạch, phơi, sấy khô, bóc vỏ, tách hạt, cắt, ướp
muối, bảo quản lạnh và các hình thức bảo quản thông thường khác.
ngoài, lãi từ hợp đồng bảo hiểm nhân thọ; thu nhập từ lãi trái phiếu Chính phủ.
g.1) Lãi tiền gửi được miễn thuế theo quy định tại điểm này là thu nhập
cá nhân nhận được từ lãi gửi Đồng Việt Nam, vàng, ngoại tệ tại các tổ chức tín
dụng, chỉ nhánh ngân hàng nước ngoài được thành lập và hoạt động theo quy
định của Luật các tổ chức tín dụng dưới các hình thức gửi không kỳ hạn, có kỳ
hạn, gửi tiết kiệm, chứng chỉ tiền gửi, kỳ phiếu, tín phiêu và các hình thức nhận
tiền gửi khác theo nguyên tắc có hoản trả đầy đủ tiền gốc, lãi cho người gửi theo
thỏa thuận.
Căn cứ để xác định thu nhập miễn thuế đối với thu nhập từ lãi tiền gửi là
số tiết kiệm (hoặc thẻ tiết kiệm), chứng chỉ tiền gửi, kỳ phiếu, tín phiếu và các
giấy tờ khác theo nguyên tắc có hoàn trả đầy đủ tiền gốc, lãi cho người gửi theo
thỏa thuận.
g.2) Lãi từ hợp đồng bảo hiểm nhân thọ là khoản lãi mà cá nhân nhận
được theo hợp đồng mua bảo hiểm nhân thọ của các doanh nghiệp bảo hiểm.
Căn cứ để xác định thu nhập : miễn thuế đối với thu nhập từ lãi hợp đồng
bảo hiểm nhân thọ là chứng từ trả tiền lãi từ hợp đồng bảo hiểm nhân thọ.
g3) Lãi trái phiếu Chính phủ là khoản lãi mà cá nhân nhận được từ việc
mua trái phiêu Chính phủ do Bộ Tài chính phát hành.
Căn cứ để xác định thu nhập miễn thuế đối với thu nhập từ lãi trái phiếu
Chính phủ là mệnh giá, lãi suất và kỳ hạn trên trái phiêu Chính Phủ.
16
<!-- Page Break -->
# Page 17
từ nước ngoài do thân nhân là người Việt Nam định cư ở nước ngoài, người
Việt Nam đi lao động, công tác, học tập tại nước ngoài gửi tiền về cho thân
nhân ở trong nước.
Căn cứ xác định thu nhập từ kiều hối được miễn thuế là các giấy tờ chứng,
minh nguồn tiền nhận từ nước ngoài và chứng từ chỉ tiền của tổ chức trả hộ (nếu
có).
1) Thu nhập từ phần. tiền lương, | tiền công làm việc ban đêm, làm thêm giờ
được trả cao hơn so với tiền lương, tiền công làm việc ban ngày, làm việc trong,
giờ theo quy định của Bộ luật Lao động. Cụ thể như sau:
¡.1) Phần tiền lương, tiền công trả cao hơn do phải làm việc ban đêm, làm
thêm giờ được miễn thuế căn cứ vào tiên lương, tiền công thực trả do phải làm
đêm, thêm giờ trừ (-) đi mức tiền lương, tiền công tính theo ngày làm việc bình
thường.
Ví dụ 2: Ông A có mức lương trả theo ngày làm việc bình thường theo
quy định của Bộ luật Lao động là 40.000 đồng/giờ.
