¡.2) Tổ chức, cá nhân trả thu nhập phải lập bảng kê phản ánh rõ thời gian
làm đêm, làm thêm giờ, khoản tiên lương trả thêm do làm đêm, làm thêm giờ đã
trả cho người lao động. Bảng kê này được lưu tại đơn vị trả thu nhập và xuât
trình khi có yêu câu của cơ quan thuê.
Bảo hiểm xã hội; tiên lương hưu nhận được hàng tháng từ Quỹ hưu trí tự
nguyện.
Cá nhân sinh sống, làm việc tại Việt Nam được miễn thuế đối với tiền
lương hưu được trả từ nước ngoài.
m.1) Học bổng nhận được từ ngân sách Nhà nước bao gồm: học bỗng của
Bộ Giáo dục và Đào tạo, Sở Giáo dục và Đào tạo, các trường công lập hoặc các
loại học bổng khác có nguồn từ ngân sách Nhà nước.
m.2) Học bồng nhận được từ tổ chức trong nước và ngoài nước (bao gồm
cả khoản tiền sinh hoạt phí) theo chương trình hỗ trợ khuyến học của tổ chức
đó.
<!-- Page Break -->
# Page 18
Tổ chức trả học bồng cho cá nhân nêu tại điểm này phải lưu giữ các quyết
định cấp học bổng và các chứng từ trả học bồng. Trường hợp cá nhân nhận học
bồng trực tiếp từ các tổ chức nước ngoài thì cá nhân nhận thu nhập phải lưu giữ
tài liệu, chứng từ chứng minh thu nhập nhận được là học bổng do các tổ chức
ngoài nước cập.
hiểm sức khỏe; tiền bồi thường tai nạn lao động; tiền bồi thường, hỗ trợ theo
quy định của pháp luật vê bồi thường, hỗ trợ, tái định cư; các khoản bồi thường
Nhà nước và các khoản bồi thường khác theo quy định của pháp luật về bồi
thường Nhà nước. Cụ thể như sau:
n.1) Thu nhập từ bồi thường hợp đồng bảo hiểm nhân thọ, phi nhân thọ,
bảo hiểm sức khỏe là khoản tiền mà cá nhân nhận được do tổ chức bảo hiểm
nhân thọ, phi nhân thọ, bảo hiểm sức khỏe trả cho người được bảo hiểm theo
thoả thuận tại hợp đồng, bảo hiểm đã ký kết. Căn cứ xác định khoản bồi thường
này là văn bản hoặc quyết định bồi thường của tổ chức bảo hiểm hoặc toà án và
chứng từ trả tiền bồi thường.
n.2) Thu nhập từ tiền bồi thường tai nạn lao động là khoản tiền người lao
động nhận được từ người sử dụng lao động hoặc quỹ bảo hiểm xã hội do bị tai
nạn trong quá trình tham gia lao động. Căn cứ xác định khoản bồi thường này là
văn bản hoặc quyết định bồi thường của người sử dụng lao động hoặc toà án và
chứng từ chỉ bồi thường tai nạn lao động.
n.3) Thu nhập từ bồi thường, hỗ trợ theo quy định của pháp luật về bồi
thường, hỗ trợ, tái định cư là tiền bỗi thường, hỗ trợ do Nhà nước thu hồi đất, kể
cả các khoản thu nhập do các tổ chức kinh tế bồi thường, hỗ trợ khi thực hiện
thu hồi đất theo quy định.
Căn cứ để xác định thu nhập từ bồi thường, hỗ trợ theo quy định của pháp
luật về bồi thường, hỗ trợ, tái định cư là quyết định của cơ quan Nhà nước có
thâm quyền về việc thu hỏi đắt, bồi thường tái định cư và chứng từ chỉ tiền bồi
thường.
n.4) Thu nhập từ bồi thường Nhà nước và các khoản bồi thường khác
theo quy định của pháp luật về bồi thường Nhà nước là khoản tiền cá nhân được
bởi thường do các quyết định xử phạt vi phạm hành chính không đúng của
người có thấm quyền, của cơ quan Nhà nước có thấm quyền gây thiệt hại đến
quyên lợi của cá nhân; thu nhập từ bồi thường cho người bị oan do cơ quan có
thâm quyên trong hoạt động tố tụng hình sự quyết định. Căn cứ xác định khoản
bồi thường này là quyết định của cơ quan Nhà nước có thấm quyền buộc cơ
quan hoặc cá nhân có quyết định sai phải bồi thường và chứng từ chi bồi
thường.
thâm quyền cho phép thành lập hoặc công nhận, hoạt động vì mục đích từ thiện,
nhân đạo, khuyến học không nhằm mục đích thu lợi nhuận.
Quỹ từ thiện nêu tại điểm này là quỹ từ thiện được thành lập và hoạt động
I8
