theo quy định tại Nghị định số 30/2012/NĐ-CP ngày 12/4/2012 của Chính phủ
về tô chức, hoạt : động của quỹ xã hội, quỹ từ thiện.
Căn cứ xác định thu nhập nhận được từ các quỹ từ thiện được miễn thuế
