chứng từ chỉ tiền, hiện vật từ quỹ từ thiện.
từ thiện, nhân đạo dưới hình thức Chính phủ và phi Chính phủ được cơ quan
Nhà nước có thâm quyên phê duyệt.
Căn cứ xác định thu nhập được miễn thuế tại điểm này là văn bản của cơ
quan Nhà nước có thâm quyên phê duyệt việc nhận viện trợ.
