insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều4_K1$md$,$md$TT111-2013$md$,$md$Khoản 1$md$,$md$Xác định số thuế được giảm
gặp khó khăn do thiên tai, hoả hoạn, tai nạn, bệnh hiểm nghèo trong năm tính
thuế nào thì được xét giảm số thuế phải nộp của năm tính thuế đó.
nhân mà người nộp thuế phải nộp trong năm tính thuế, bao gồm:
b. 1) Thuế thu nhập cá nhân đã nộp hoặc đã khấu trừ đối với thu nhập từ
đầu tư vốn, thu nhập từ chuyển nhượng, vốn, thu nhập từ chuyển nhượng bất
động sản, thu nhập từ trúng thưởng, thu nhập từ bản quyền, thu nhập từ nhượng,
quyền thương mại, thu nhập từ thừa kế; thu nhập từ quả tặng.
b.2) Thuế thu nhập cá nhân phải nộp đối với thu nhập từ kinh doanh và
thu nhập từ tiền lương, tiền công.
thực tế để khắc phục thiệt hại trừ (-) đi các khoản bồi thường nhận được từ tổ
chức bảo hiểm (nếu có) hoặc từ tổ chức, cá nhân gây ra tai nạn (nếu có).
d.1) Trường hợp số thuế phải nộp trong năm tính thuế lớn hơn mức độ
thiệt hại thì sô thuê giảm băng mức độ thiệt hại.
d.2) Trường hợp số thuế phải nộp trong năm tính thuế nhỏ hơn mức độ
thiệt hại thì số thuế giảm bằng số thuế phải nộp.
