Ví dụ 4: Bà C có thu nhập từ tiền lương, tiền công trong tháng là 40 triệu
đồng và nộp các khoản bảo hiểm là: 7% bảo hiểm xã hội, 1,5% bảo hiểm y tế
trên tiền lương. Bà C nuôi 2 con dưới 18 tuổi, trong tháng Bà C không đóng góp
từ thiện, nhân đạo, khuyến học. Thuế thu nhập cá nhân tạm nộp trong tháng của
Bà C được tính như sau:
~ Thu nhập chịu thuế của Bà C là 40 triệu đồng.
- Bà C được giảm trừ các khoản sau:
+ Giảm trừ gia cảnh cho bản thân: 9 triệu đồng
-+ Giảm trừ gia cảnh cho 02 người phụ thuộc (2 con):
3,6 triệu đồng x 2 = 7,2 triệu đồng
+ Bảo hiểm xã hội, bảo hiểm y tế:
40 triệu đồng x (7% + 1,5%) = 3,4 triệu đồng
Tổng cộng các khoản được giảm trừ:
9 triệu đồng + 7,2 triệu đồng + 3,4 triệu đồng = 19,6 triệu đồng,
- Thu nhập tính thuế của Bà C là:
40 triệu đồng - 19,6 triệu đồng = 20,4 triệu đồng
- Số thuế phải nộp:
._ Cáchl; Số thuế phải nộp tính theo từng bậc của Biểu thuế lũy tiến từng
phân:
+ Bậc I: thu nhập tính thuế đến 5 triệu đồng, thuế suất 5%:
5 triệu đồng x 5% = 0,25 triệu đồng
+ Bậc 2: thu nhập tính thuế trên 5 triệu đồng đến 10 triệu đồng, thuế suất
10%:
(10 triệu đồng - 5 triệu đồng) x 10% = 0,5 triệu đồng
+ Bậc 3: thu nhập tính thuế trên 10 triệu đồng đến 18 triệu đồng, thuế suất
15%:
(18 triệu đồng - 10 triệu đồng) x 15% = 1,2 triệu đồn:
8
+ Bậc 4: thu nhập tính thuế trên 18 triệu đồng đến 32 triệu đồng, thuế suất
20%:
(20,4 triệu đồng - 18 triệu đồng) x 20% = 0,48 triệu đồng,
- Tổng số thuế Bà C phải tạm nộp trong tháng là:
0,25 triệu đồng + 0,5 triệu đồng + 1,2 triệu đồng + 0,48 triệu đồng
= 2,43 triệu đồng
Cách 2: Số thuế phải nộp tính theo phương pháp rút gọn:
Thu nhập tính thuế trong tháng 20,4 triệu đồng là thu nhập tính thuế thuộc
bậc 4. Sô thuê thu nhập cá nhân phải nộp như sau:
