insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều7_K4$md$,$md$TT111-2013$md$,$md$Khoản 4$md$,$md$Quy đổi thu nhập không bao gồm thuế thành thu nhập tính thuế
Trường hợp tổ chức, cá nhân trả thu nhập từ tiền lương, tiền công cho
người lao động theo hướng dẫn tại khoản 2, Điều 2 Thông tư này không bao
gôm thuế thì phải quy đổi thu nhập không bao gồm thuế thành thu nhập tính
thuế theo Phụ lục số 02/PL-TNCN ban hành kèm theo Thông tư này để xác định
thu nhập chịu thuế. Cụ thể như sau:
nhận cộng (+) các khoản lợi ích do người sử dụng lao động trả thay cho người
lao động, (nếu có) trừ (-) các khoản giảm trừ. Trường hợp trong các khoản trả
thay có tiên thuê nhà thì tiền thuê nhà tính vào thu nhập làm căn cứ quy đổi
bằng số thực trả nhưng không vượt quá 15% tổng thu nhập chịu thuế tại đơn vị
(chưa bao gồm tiền thuê nhà).
Công thức xác định thu nhập làm căn cứ quy đổi:
Thunhậplàm _ Thunhập „ Cáckhoản _ Các khoản
căn cứ quy đôi thực nhận trả thay giảm trừ
Trong đó:
- Thu nhập thực nhận là tiền lương, tiền công không bao gồm thuế mà
người lao động nhận được hàng tháng.
- Các khoản trả thay là các khoản lợi ích bằng tiền hoặc không bằng tiền
do người sử dụng lao động trả cho người lao động theo hướng dẫn tại điểm đ,
khoản 2, Điều 2 Thông tư này.
- Các khoản giảm trừ bao gồm: giảm trừ gia cảnh; giảm trừ đóng bảo
hiểm, quỹ hưu trí tự nguyện; giảm trừ đóng góp từ thiện, nhân đạo, khuyến học
theo hướng dẫn tại Điều 9 Thông tư này.
Ví dụ 5: Năm 2014, theo hợp đồng lao động ký giữa Ông D và Công ty X
thì Ông D được trả lương hàng tháng là 31,5 triệu đồng, ngoài tiền lương Ông D
được công ty X trả thay phí hội viên câu lạc bộ thể thao 1 triệu đồng/tháng. Ông
D phải đóng bảo hiểm bắt buộc là 1,5 triệu đồng/tháng. Công ty X chịu trách
nhiệm nộp thuế thu nhập cá nhân theo quy định thay cho ông D. Trong năm
Ông D chỉ tính giảm trừ gia cảnh cho bản thân, không có người phụ thuộc và
không phát sinh đóng góp từ thiện, nhân đạo, khuyến học.
Thuế thu nhập cá nhân phải nộp hàng tháng của Ông D như sau:
~ Thu nhập làm căn cứ quy đổi là:
31,5 triệu đồng + 1 triệu đồng — (9 triệu đồng + I,5 triệu đồng) = 22 triệu đồng
-__ Thu nhập tính thuế (xác định theo Phụ lục số 02/PL-TNCN) là:
(22 triệu đồng — 1,65 triệu đồng)/0,8 = 25,4375 triệu đồng
- Thuế thu nhập cá nhân Ông D phải nộp (áp dụng cách tính thuế rút gọn
theo Phụ lục số 01/PL-TNCN) là:
