của Ông D như sau:
Bước l: Xác định tiền thuê nhà trả thay được tính vào thu nhập làm căn
cứ quy đôi
~ Thu nhập làm căn cứ quy đổi (không gồm tiền thuê nhà):
_ 31,5 triệu đồng + l triệu đồng - (9 triệu đồng + 1,5 triệu đồng) = 22 triệu
