Ví dụ 7: Giả sử Ông D tại ví dụ 6 nêu trên, ngoài thu nhập tại công ty X,
từ tháng 01/2014 đến tháng 5/2014 ông còn có hợp đồng nhận thu nhập tại công,
ty Y là 12 triệu đồng/tháng. Công ty Y cũng trả thay thuế thu nhập cá nhân cho
Ông D.
Quyết toán thuế thu nhập cá nhân của ông D năm 2014 như sau:
~ Tại công ty X, thu nhập chịu thuế năm của ông D là:
42,687 triệu đồng x 12 tháng = 512,244 triệu đồng
~ Tại công ty Y:
+ Thu nhập tính thuế hàng tháng (quy đổi theo Phụ lục số 02/PL-
TNCN):
(12 triệu đồng — 0,75 triệu đồng)/0,85 = 13,235 triệu đồng
+ Thu nhập chịu thuế năm tại công ty Y:
13,235 triệu đồng x 5 tháng = 66,175 triệu đồng
~ Tổng thu nhập chịu thuế của ông D năm 2014:
512,244 triệu đồng + 66, 175 triệu đồng = 578,419 triệu đồng
- Thu nhập tính thuê tháng:
(ð78,419 triệu đồng : 12 tháng) - (9 triệu đồng + 1,5 triệu đồng) = 37,702
triệu đông
- Thuế Thu nhập cá nhân phải nộp trong năm:
(37,702 triệu đồng x 25% - 3,25 triệu đồng) x 12 tháng = 74,105 triệu đồng.$md$,$md$TT111-2013_Điều7$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
