insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều7_K6$md$,$md$TT111-2013$md$,$md$Khoản 6$md$,$md$Căn cứ tính thuế đối với tiền tích lñy mua bảo hiểm không buộc,
tiền tích lũy đóng quỹ hưu trí tự nguyện là khoản tiền phí tích luỹ mua bảo hiểm
nhân thọ, bảo hiểm không bắt buộc khác, tiền tích luỹ đóng góp quỹ hưu trí tự
nguyện, do người sử dụng lao động mua hoặc đóng góp cho người lao động và
tỷ lệ khâu trừ 10%.
Trước khi trả tiền bảo hiểm, tiền lương hưu cho cá nhân, doanh nghiệp
bảo hiểm, công ty quản lý quỹ hưu trí tự nguyện có trách nhiệm khấu trừ thuế
theo tỷ lệ 10% trên khoản tiên phí tích luỹ, tiên tích lũy đóng góp quỹ hưu trí tự
nguyện tương ứng với phần người sử dụng lao động mua hoặc đóng góp cho
người lao động từ ngày 01 tháng 7 năm 2013.
Doanh nghiệp bảo hiểm, công ty quản lý quỹ hưu trí tự nguyện có trách
nhiệm theo dõi riêng phần phí bảo hiểm nhân thọ, bảo hiểm không bắt buộc
khác, tiền tích luỹ đóng góp quỹ hưu trí tự nguyện do người sử dụng lao động
mua hoặc đóng góp cho người lao động để làm căn cứ tính thuế thu nhập cá
nhân.$md$,$md$TT111-2013_Điều7$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
