insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều8_K1$md$,$md$TT111-2013$md$,$md$Khoản 1$md$,$md$Xác định thu nhập chịu thuế từ kinh doanh
Thu nhập chịu thuế từ kinh doanh được xác định bằng doanh thu trừ các
khoản chỉ phí hợp lý liên quan trực tiếp đến việc tạo ra thu nhập chịu thuế trong
kỳ tính thuế.
Thu nhập chịu thuế từ kinh doanh đối với từng trường hợp cụ thể được
xác định như sau:
26
<!-- Page Break -->
# Page 27
hoá đơn chứng từ.
a.l) Đối với cá nhân kinh doanh không thực hiện chế độ kế toán hoá đơn,
chứng từ không xác định được doanh thu, chỉ phí và thu nhập chịu thuế (sau đây
gọi tắt là cá nhân kinh doanh nộp thuế theo phương pháp khoán).
a.1.1) Đối với cá nhân kinh doanh nộp thuế theo phương pháp khoán thì
thu nhập chịu thuế xác định như sau:
Thu nhập chịu thuế =_ Doanh thu khoán x Tỷ lệ thư nhập
trong kỳ tính thuê trong kỳ tính thuê chịu thuế ân định
Trong đó:
- Doanh thu khoán được xác định theo tài liệu kê khai của cá nhân kinh
doanh, cơ sở dữ liệu của cơ quan thuế, kết quả điêu tra doanh thu thực tế của cơ
quan thuế và ý kiến tham vấn của Hội đồng tư vấn thuế xã, phường.
- Tỷ lệ thu nhập chịu thuế Ấn định được xác định theo hướng dẫn điểm
a.4, khoản 1, Điều này.
a.1.2) Đối với cá nhân kinh doanh nộp thuế theo phương pháp khoán có
sử dụng hóa đơn.
a.1.2.1) Trường hợp cá nhân kinh doanh nộp thuế theo phương pháp khoán
có sử dụng hóa đơn quyền, nếu trong quý doanh thu trên hoá đơn cao hơn doanh
thu khoán thì ngoài việc nộp thuế theo doanh thu khoán còn phải nộp bổ sung
thuế thu nhập cá nhân đối với phần doanh thu trên hoá đơn cao hơn doanh thu
khoán.
a.1.2.2) Trường hợp cá nhân kinh doanh nộp thuế theo phương pháp khoán
sử dụng hóa đơn do cơ quan thuế bán lẻ theo từng số thì khai và nộp thuế thu
nhập cá nhân theo tỷ lệ 10% tính trên thu nhập chịu thuế của từng lần phát sinh.
Thu nhập chịu thuế của từng lần phát sinh được xác định như sau:
Thu nhập chịu Doanh thu tính thu
thuế từng lần  = nhập chịu thuế từng ch ly
phát sinh lân phát sinh l l
Trong đó:
~ Doanh thu tính thu nhập chịu thuế từng lần phát sinh được xác định theo
hợp đông và các chứng từ mua bán.
- Tỷ lệ thu nhập chịu thuế ấn định được xác định theo hướng dẫn tại điểm
a.4, khoản 1, Điêu này.
a.1.2.3) Trường hợp cá nhân kinh doanh nộp thuế theo phương pháp khoán
sử dụng hóa đơn quyên có yêu cầu hoàn thuế thu nhập cá nhân thì doanh thu
tính thuế của năm được xác định như sau:
- Nếu doanh thu trên hóa đơn của cả năm thấp hơn doanh thu khoán thì
doanh thu tính thuế của năm là doanh thu khoán.
- Nếu doanh thu trên hóa đơn của cả năm cao hơn doanh thu khoán thì
doanh thu tính thuế của năm là doanh thu trên hóa đơn.
27
<!-- Page Break -->
# Page 28
a.2) Đối với cá nhân kinh doanh chỉ hạch toán được doanh thu không
hạch toán được chỉ phí thì thu nhập chịu thuế được xác định như sau:
Thu nhập chịu Doanh thu tính thu Tỷ lệ thu Thu nhập chịu
thuê trongkỳ = nhập chịu thuế x nhậpchịu + thuê khác trong
tính thuê trong kỳ tính thuế thuê ân định kỳ tính thuê
Trong đó:
~ Doanh thu tính thu nhập chịu thuế trong kỳ tính thuế được xác định theo
hướng dẫn tại điểm b.1, khoản 1, Điều này.
- Tỷ lệ thụ nhập chịu thuế ấn định được xác định theo hướng dẫn tại điểm
a.4, khoản 1, Điều này.
- Thu nhập chịu thuế khác là các khoản thu nhập phát sinh trong quá trình
kinh doanh gồm: tiền phạt vi phạm hợp đồng; tiền phạt do chậm thanh toán; tiền
lãi ngân hàng trong quá trình thanh toán; tiên lãi do bán hàng trả chậm, trả gÓP;
tiền lãi do bán tài sản cố định; tiền bán ph liệu, phế phẩm và thu nhập chịu thuế
khác.
a.3) Đối với cá nhân kinh doanh lưu động (buôn chuyến) và cá nhân
không kinh doanh có phát sinh hoạt động bán hàng hóa, cung ứng dịch vụ cần
có hóa đơn để giao cho khách hàng.
Cá nhân kinh doanh lưu động (buôn chuyến) và cá nhân không kinh
doanh có phát sinh hoạt động bán hàng hóa, cung ứng dịch vụ cần có hóa đơn
để giao cho-khách hàng khai và nộp thuế thu nhập cá nhân theo tỷ lệ: 10% tính
trên thu nhập chịu thuế của từng lần phát sinh.
Thu nhập chịu thuế của từng, lần phát sinh được xác định tương tự như
đối với cá nhân kinh doanh nộp thuế theo phương pháp khoán sử dụng hóa đơn
do cơ quan ‹ thuế bán lẻ theo từng số theo hướng dẫn tại tiết a.1.2.2, điểm a,
khoản 1, Điều này.
a.4) Tỷ lệ thu nhập chịu thuế ấn định
Tỷ lệ thu nhập chịu thuế ấn định tính trên doanh thu áp dụng đối với cá
nhân kinh doanh chưa thực hiện đúng pháp luật về kế toán, hoá đơn, chứng từ;
cá nhân kinh doanh lưu động và cá nhân không kinh doanh như sau:
Tỷ lệ thu nhập chịu
Hoạt động thuế Ấn định (%)
Phân phối, cung cấp hàng hoá 7
Dịch vụ, xây dựng không bao thầu nguyên vật liệu 30
Sản xuất, vận tải, dịch vụ có gắn với hàng hoá, xây
dựng có bao thâu nguyên vật liệu lŠ
Hoạt động kinh doanh khác 12
<!-- Page Break -->
# Page 29
Đối với cá nhân kinh doanh nhiều ngành nghề thì áp dụng theo tỷ lệ của
hoạt động kinh doanh chính. Trường hợp cá nhân thực tế kinh doanh nhiều
ngành nghề và không xác định được ngành nghề kinh doanh chính thì áp dụng
theo tỷ lệ của “Hoạt động kinh doanh khác”.
chứng từ thì thu nhập chịu thuê được xác định như sau:
Thu nhập chịu Doanh thu tính thu Chỉ phí hợp lý Thu nhập chịu
thuê trong kỳ = nhập chịu thuê  - được trừ trong + thuế khác trong
tính thuê trong kỳ tính thuê kỳ tính thuê kỳ tính thuế
b.1) Doanh thu tính thu nhập chịu thuế trong kỳ tính thuế
Doanh thu để tính thu nhập chịu thuế từ kinh doanh là toàn bộ tiền bán
hàng hoá, tiền gia công, tiền hoa hồng, tiền cung ứng hàng hoá, dịch vụ phát
sinh trong kỳ tính thuế bao gồm cả khoản trợ giá, phụ thu, phụ trội mà cá nhân
kinh doanh được hưởng không phân biệt đã thu được tiền hay chưa thu được
tiền và được xác định theo số sách kế toán.
b.1.1) Thời điểm xác định doanh thu để tính thu nhập chịu thuế như sau:
b.1.1.1) Đối với hoạt động bán hàng hoá là thời điểm chuyển giao quyền
sở hữu, quyên sử dụng hàng hoá hoặc thời điểm lập hoá đơn bán hàng.
b.1.1.2) Đối với hoạt động cung ứng dịch vụ là thời điểm hoàn thành việc
cung ứng dịch vụ cho người mua hoặc thời điểm lập hoá đơn cung ứng dịch vụ.
Đối với hoạt động cho thuê nhà, quyền sử dụng đất, mặt nước, tài sản khác là
thời điểm hợp đồng cho thuê có hiệu lực.
Trường hợp thời điểm lập hoá đơn trước thời điểm chuyển giao quyền sở
hữu hàng hoá (hoặc dịch vụ hoàn thành) thì thời điểm xác định doanh thu được
tính theo thời điểm lập hoá đơn hoặc ngược lại.
b.1.2) Doanh thu để tính thu nhập chịu thuế đối với một số trường hợp
được xác định như sau:
b.1.2.1) Đối với hàng hoá bán theo phương thức trả góp được xác định
theo giá bán hàng hoá trả tiền một lần, không bao gồm tiền lãi trả góp.
b.1.2.2) Đối với hàng hoá, dịch vụ bán theo phương thức trả chậm là tiền
bán hàng hoá, dịch vụ trả một lân, không bao gôm tiên lãi trả chậm.
Trường hợp việc thanh toán theo hợp đồng mua bán theo phương thức trả
góp, trả chậm kéo dài nhiêu kỷ tính thuê theo doanh thu là sô tiên phải thu của
người mua trong kỳ tính thuê không bao gồm lãi trả góp, trả chậm theo thời hạn
quy định trong hợp đông.
Việc xác định chỉ phí khi xác định thu nhập chịu thuế đối với hàng hoá
bán trả góp, trả chậm thực hiện theo nguyên tắc chỉ phí phải phù hợp với doanh
thu.
b.1.2.3) Đối với hàng hoá, dịch vụ do cá nhân kinh doanh làm ra dùng để
trao đổi, biếu, tặng, trang bị, thưởng cho người lao động, doanh thu được xác
29
<!-- Page Break -->
# Page 30
định theo giá bán hàng hoá, dịch vụ cùng, loại hoặc tương, đương trên thị trường,
tại thời điểm trao đổi, biếu, tặng, trang bị, thưởng cho người lao động.
b.1.2.4) Đối với hàng hoá, dịch vụ do cá nhân kinh doanh làm ra tự dùng
để phục vụ cho quá trình sản xuất, kinh doanh của cá nhân thì doanh thu là chỉ
phí sản xuất ra sản phẩm hàng hoá, địch vụ đó.
Vb.1/2.5) Đối với hoạt động gia công hàng hoá thì doanh thu là tổng số tiền
thu về từ hoạt động gia công bao gồm cả tiên công, nhiên liệu, động lực, vật liệu
phụ và chi phí khác phục vụ cho việc gia công hàng hoá.
b.1.2.6) Đối với nhận đại lý, ký gửi bán hàng đúng giá quy định của cá
nhân kinh doanh giao đại lý, ký gửi hưởng hoa hồng thì doanh thu là tiền hoa
hồng được hưởng theo hợp đồng đại lý, ký gửi hàng hoá.
b.1.2.7) Đối với hoạt động cho. thuê tài sản, doanh thu được xác định theo
hợp đồng không phân biệt đã nhận tiền hay chưa nhận tiền.
Trường hợp bên thuê trả tiền thuê trước cho nhiều năm thì doanh thu để
tính thu nhập chịu thuế được phân bổ cho số năm trả tiền trước hoặc xác định
theo doanh thu trả tiền một lần.
b.1.2.8) Đối với hoạt động, xây dựng, lắp đặt là giá trị công trình, giá trị
hạng mục công trình hoặc giá trị khối lượng công trình nghiệm thu bàn giao.
Trường hợp xây dựng, lắp đặt không bao thâu nguyên vật liệu, máy móc, thiết
bị thì doanh thu tính thuế là số tiền từ hoạt động xây dựng, lắp đặt không bao
gôm giá trị nguyên vật liệu, máy móc, thiết bị.
Trường hợp xây dựng, lắp đặt có bao thầu nguyên vật liệu, máy móc, thiết
bị thì doanh thu tính thuế là số tiền từ hoạt động xây dựng, lắp đặt bao. gồm cả
giá trị nguyên vật liệu, máy móc, thiết bị.
b.1.2.9) Đối với hoạt động vận tải là toàn bộ doanh thu vận chuyển hành
khách, hành lý, hàng hóa phát sinh trong kỳ tính thuê.
b.2) Các khoản chỉ phí hợp lý được trừ
Chỉ phí hợp lý được trừ là các khoản chỉ phí thực tế phát sinh, có liên
quan trực tiêp đên hoạt động sản xuât, kinh doanh của cá nhân và có đủ hoá
đơn, chứng từ theo quy định của pháp luật. Cụ thê như sau:
b.2.1) Chỉ phí tiền lương, tiền công, phụ cấp, trợ cấp, các khoản thù lao
và các chỉ phí khác trả cho người lao động theo hợp đồng lao động, hợp đồng
dịch vụ hoặc thỏa ước lao động tập thể theo quy định của Bộ luật Lao động.
___ Đối với chỉ phí tiền lương, tiền công không bao gồm khoản tiền lương,
tiên công của cá nhân là chủ hộ kinh doanh hoặc các thành viên đứng tên trong
Giấy chứng nhận đăng ký kinh doanh của nhóm kinh doanh.
Đối với tiền trang phục trả cho người lao động không vượt quá 5.000.000
đồng/người/năm. Trường hợp chỉ trang phục cả bằng tiền và hiện vật cho người
lao động thì mức chỉ tối đa để tính vào chỉ phí được trừ khi xác định thu nhập
chịu thuế không vượt quá 5.000.000 đồng/người/năm. Đối với những ngành
kinh doanh có tính chất đặc thù thì chỉ phí này được thực hiện theo quy định của
30
<!-- Page Break -->
# Page 31
Bộ Tài chính.
„ b.2.2) Chỉ phí nguyên liệu, vật liệu, nhiên liệu, năng lượng, hàng hoá thực
tÊ sử dụng vào sản xuất, kinh doanh hàng hoá, dịch vụ liên quan đên việc tạo ra
doanh thu, thu nhập chịu thuê trong kỳ được tính theo mức tiêu hao hợp lý, giá
thực tê xuât kho do hộ gia đình, cá nhân kinh doanh tự xác định và chịu trách
nhiệm trước pháp luật.
Trường hợp một số nguyên liệu, vật liệu, nhiên liệu, hàng hoá đã được
Nhà nước ban hành định mức tiêu hao thì thực hiện theo định mức của Nhà
nước đã ban hành.
Mọi trường hợp tổn thất vật tư, tài sản, tiền vốn, hàng hoá đều không
được tính giá trị tốn thất đó vào chỉ phí hợp lý trừ trường hợp tốn thất do thiên
tai, hoả hoạn, địch bệnh và các trường hợp bất khả kháng khác không được bồi
thường.
Đối với vật tư hàng hoá vừa dùng cho tiêu dùng cá nhân, vừa dùng cho
kinh doanh thì chỉ được tính vào chỉ phí phần sử dụng vào kinh doanh.
b.2.3) Chi phí khấu hao, duy tu, bảo dưỡng tài sản cố định sử dụng cho
hoạt động sản xuất, kinh doanh hàng hoá, dịch vụ. Cụ thể như sau:
b.2.3.1) Tài sản cỗ định được trích khấu hao tính vào chỉ phí hợp lý phải
đáp ứng các điêu kiện sau:
- Tài sản cố định sử dụng vào sản xuất, kinh doanh.
- Tài sản cố định phải có đầy đủ hóa đơn, chứng từ và các giấy tờ hợp
pháp khác chứng minh tài sản cỗ định thuộc quyên sở hữu của cá nhân kinh
doanh.
~ Tài sản cố định phải được quản lý, theo dõi, hạch toán trong, số sách kế
toán của cá nhân kinh doanh theo chế độ quản lý và hạch toán kế toán hiện
hành.
.__ Riêng trích khấu hao đối với tài sản cố định là ô tô chở người từ 09 chỗ
ngồi trở xuống không được tính vào chỉ phí hợp lý.
b.2.3.2) Mức trích khấu hao tài sản cố định được tính vào chỉ phí hợp lý
theo quy định về chế độ quản lý, sử dụng và trích khấu hao tài sản cố định.
b.2.3.3) Tài sản cố định đã khấu hao hết giá trị nhưng vẫn tiếp tục được
sử dụng cho sản xuất, kinh doanh thì không được trích khấu hao.
Đối với tài sản cô định vừa sử dụng cho mục đích kinh doanh, vừa sử
dụng cho mục đích khác thì chỉ phí khẩu hao được tính vào chỉ phí hợp lý tương
ứng mức độ sử dụng tài sản cho kinh doanh.
b.2.4) Chỉ phí trả lãi các khoản tiền vay vốn sản xuất, kinh doanh hàng
hoá dịch vụ liên quan trực tiếp đến việc tạo ra doanh thu, thu nhập chịu thuế.
Mức lãi suất tiền vay được tính theo lãi suất thực tế căn cứ vào hợp đồng
vay vốn của các tô chức tín dụng, chỉ nhánh ngân hàng nước ngoài hoặc tô chức
31
<!-- Page Break -->
# Page 32
kinh tế. Trường hợp vay của các đối tượng không phải là tổ chức tín dụng, chỉ
nhánh ngân hàng nước ngoài hoặc tổ chức kinh tế thì chỉ phí trả lãi tiền vay
được căn cứ vào hợp đồng vay nhưng mức tối đa không quá 1,5 lần mức lãi suất
cơ bản do Ngân hàng Nhà nước Việt Nam công, bố tại thời điểm vay.
Chỉ phí trả lãi tiền vay nêu trên không bao gồm trả lãi tiền vay để góp vốn
thành lập cơ sở của cá nhân kinh doanh.
b.2.5) Chi phí quản lý, bao gồm:
b.2.5.1) Chỉ phí trả tiền điện, tiền nước, tiền điện thoại, tiền mua văn
phòng phẩm, tiền thuê kiểm toán, tiên thuê dịch vụ pháp lý, tiền thuê thiết kế,
tiền mua bảo hiểm tài sản, tiền dịch vụ kỹ thuật và dịch vụ mua ngoài khác. ,
b.2.5.2) Các khoản chỉ phí để có các tài sản không thuộc tài sản cố định
như chỉ mua và sử dụng các tài liệu kỹ thuật, bằng SE chế, giấy phép chuyển
giao công nghệ, nhãn hiệu thương mại được phân bỗ dần vào chỉ phí kinh
doanh.
b.2.5.3) Tiền thuê tài sản cố định hoạt động theo hợp đồng thuê. Trường,
hợp trả tiền thuê tài sản có định một lần cho nhiều năm thì tiền thuê được phân
bỗ dần vào chỉ phí sản xuất, kinh doanh theo số năm sử dụng tài sản cố định.
b.2.5.4) Chi phí dịch vụ mua ngoài, thuê ngoài khác phục vụ trực tiếp cho
hoạt động sản xuất, kinh doanh hàng hoá, dịch vụ có chứng từ, hoá đơn theo chế
độ quy định.
b.2.5:5) Chỉ về tiêu thụ hàng hoá, dịch vụ bao gồm: chỉ phí bảo quản,
đóng gói, vận chuyền, bốc xếp, thuê kho bãi, bảo hành sản phẩm, hàng hoá.
b.2.6) Các khoản thuế, phí và lệ phí, tiền thuê đất phải nộp có liên quan
đến hoạt động sản xuất, kinh doanh hàng hoá, dịch vụ theo quy định của pháp
luật (trừ thuế thu nhập cá nhân, thuế giá trị gia tăng, đầu vào đã được khấu trừ và
các khoản thuế, phí, lệ phí và thu khác không được tính vào chỉ phí theo quy
định của pháp luật liên quan), bao gồm:
b.2.6.1) Thuế môn bài, thuế xuất khẩu, thuế nhập khẩu, thuế tiêu thụ đặc
biệt, thuế tài nguyên, thuế sử dụng đất nông nghiệp, thuế sử dụng đất phi nông
nghiệp, thuế bảo vệ môi trường, tiền thuê đất, tiền thuê mặt nước.
b.2.6.2) Thuế giá trị gia tăng mà pháp luật quy định được tính vào chỉ phí.
b.2.6.3) Các khoản phí, lệ phí mà cơ SỞ kinh doanh thực nộp vào ngân
sách Nhà nước theo quy định của pháp luật về phí, lệ phí.
. b¿2.7) Phần chỉ phụ cấp cho người lao động đi công tác (không bao gồm
tiên đi lại và tiền ở) tôi đa là hai lần mức quy định theo hướng dẫn của Bộ Tài
chính đôi với cán bộ công chức, viên chức Nhà nước.
._— Chi phí đi lại và tiền thuê chỗ ở cho người lao động đi công tác nếu có
đây đủ hóa đơn chứng từ hợp pháp theo quy định được tính vào chỉ phí được trừ
khi xác định thu nhập chịu thuế. Trường hợp cá nhân kinh doanh có khoán tiên
đi lại và tiên ở cho người lao động thì được tính vào chi phí được trừ khoản chỉ
32
<!-- Page Break -->
# Page 33
khoán tiền đi lại và tiền ở theo quy định của Bộ Tài chính đối với cán bộ công
chức, viên chức Nhà nước.
b.2.8) Các khoản chỉ phí khác liên quan trực diếp đến việc tạo ra doanh
thu, thu nhập chịu thuế có chứng từ, hoá đơn theo chế độ quy định.
b.3) Thu nhập chịu thuế khác
Thu nhập chịu thuế khác là các khoản thu nhập phát sinh trong quá trình
kinh doanh gồm: tiền phạt vi phạm hợp đồng; tiền phạt do chậm thanh toán; tiền
lãi ngân hàng trong quá trình thanh toán; tiền lãi do bán hàng trả chậm, trả Ốp;
tiễn lãi do bán tài sản cô định; tiền bán phế liệu, phế phẩm và thu nhập chịu thuế
khác.
Trường hợp nhiều người cùng đứng tên trong một Giấy chứng nhận đăng
ký kinh doanh kế cả trường hợp cho thuê nhà, thuê mặt bằng - có nhiều người
cùng đứng tên trong Giấy chứng nhận quyền sử dụng đất, quyền sở hữu nhà ở
và tài sản khác gắn liền với đất (gọi chung là nhóm cá nhân kinh doanh), sau khi
đã xác định được thu nhập chịu thuế từ kinh doanh theo hướng dẫn tại điểm a và
b, khoản 1, Điêu này, thu nhập chịu thuê của mỗi cá nhân được phân chia theo
một trong các cách sau đây:
c.1) Theo tỷ lệ vốn góp của từng cá nhân ghi trong Giấy chứng nhận đăng
ký kinh doanh.
c.2) Theo thoả thuận giữa các cá nhân.
c.3) Theo số bình quân thu nhập đầu người trong trường hợp Giấy chứng
nhận đăng ký kinh doanh không xác định tỷ lệ vỗn góp hoặc không có thoả
thuận về phân chia thu nhập giữa các cá nhân.
Trên cơ sở thu nhập chịu thuế của mỗi cá nhân cùng tham gia kinh doanh
đã xác định theo nguyên tắc phân chia nêu trên, từng, cá nhân được tính các
khoản giảm trừ theo hướng dẫn tại Điều 9, Thông tư này để xác định thu nhập
tính thuế và số thuế thu nhập cá nhân phải nộp riêng cho từng cá nhân.$md$,$md$TT111-2013_Điều8$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
