insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều8_K3$md$,$md$TT111-2013$md$,$md$Khoản 3$md$,$md$Thu nhập chịu thuế đối với cá nhân vừa có thu nhập từ kinh doanh,
vừa có thu nhập từ tiên lương, tiền công là tổng thu nhập chịu thuế từ kinh
doanh và thu nhập chịu thuế từ tiền lương, tiền công.$md$,$md$TT111-2013_Điều8$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều9$md$,$md$TT111-2013$md$,$md$Điều 9. Các khoản giảm trừ$md$,$md$Các khoản giảm trừ
Các khoản giảm trừ theo hướng dẫn tại Điều này là các khoản được trừ
vào thu nhập chịu thuế của cá nhân trước khi xác định thu nhập tính thuế từ tiền
lương, tiền công, từ kinh doanh. Cụ thể như sau:$md$,null,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều9_K1$md$,$md$TT111-2013$md$,$md$Khoản 1$md$,$md$Giảm trừ gia cảnh
- Theo quy định tại Điều 19 Luật Thuế thu nhập cá nhân; khoản 4, Điều 1
Luật sửa đôi, bổ sung một số điều của Luật thuế thu nhập cá nhân; Điều 12
Nghị định số 65/2013/NĐ-CP, việc giảm trừ gia cảnh được thực hiện như sau:
tính thuế đối với thu nhập từ kinh doanh, thu nhập từ tiền lương, tiền công của
người nộp thuế là cá nhân cư trú.
Trường hợp cá nhân cư trú vừa có thu nhập từ kinh doanh, vừa có thu
nhập từ tiên lương, tiền công thì tính ,piảm trừ gia cảnh một lần vào tổng thu
nhập từ kinh doanh và từ tiền lương, tiền công.
b.1) Đối với người nộp thuế là 9 triệu đồng/tháng, 108 triệu đồng/năm.
b.2) Đối với mỗi người phụ thuộc là 3,6 triệu đồng/tháng.
c.1) Giảm trừ gia cảnh cho bản thân người nộp thuế:
c.1.1) Người nộp thuế có nhiều nguồn thu nhập từ tiền lương, tiền công,
từ kinh doanh thì tại một thời điểm (tính đủ theo tháng) người nộp thuế lựa chọn
tính giảm trừ gia cảnh cho bản thân tại một nơi.
c.1.2) Đối với người nước ngoài là cá nhân cư trú tại Việt Nam được tính
giảm trừ gia cảnh cho bản thân từ tháng 01 hoặc từ thán đến Việt Nam trong
trường hợp cá nhân lần đầu tiên có mặt tại Việt Nam đến tháng kết thúc hợp
đồng lao động và rời Việt Nam trong năm tính thuế (được tính đủ theo tháng).
Ví dụ 8: Ông E là người nước ngoài đến Việt Nam làm việc liên tục từ
ngày 01/3/2014. Đến ngày 15/1 1/2014, ông E kết thúc Hợp đồng lao động và về
nước. Từ ngày 01/3/2014 đến khi về nước ông E có mặt tại Việt Nam trên 183
ngày. Như vậy, năm 2014, ông E là cá nhân cư trú và được giảm trừ gia cảnh
cho bản thân từ tháng 01 đến hết tháng 11 năm 2014.
Ví dụ 9: Bà G là người nước ngoài đến Việt Nam lần đầu tiên vào ngày
21/9/2013. Ngày 15/6/2014, Bà G kết thúc hợp đồng lao động và rời Việt Nam.
Trong khoảng thời gian từ ngày 21/9/2013 đến ngày 15/6/2014 Bà G có mặt tại
Việt Nam 187 ngày. Như vậy trong năm tính thuế đầu tiên (từ ngày 21/9/2013
đến ngày 20/9/2014), Bà G được xác định là cá nhân cư trú của Việt Nam và
được giảm trừ gia cảnh cho bản thân từ tháng 9/2013 đến hết tháng 6/2014.
34
<!-- Page Break -->
# Page 35
c.1.3) Trường hợp trong năm tính thuế cá nhân chưa giảm trừ cho bản
thân hoặc giảm trừ cho bản thân chưa đủ 12 tháng thì được giảm trừ đủ 12 tháng
khi thực hiện quyết toán thuế theo quy định.
c.2) Giảm trừ gia cảnh cho người phụ thuộc
€.2.1) Người nộp thuế được tính giảm trừ gia cảnh cho người phụ thuộc
nếu người nộp thuế đã đăng ký thuế và được cấp mã số thuế.
c.2.2) Khi người nộp thuế đăng ký giảm trừ gia cảnh cho người phụ thuộc
sẽ được cơ quan thuế cấp mã số thuế cho người phụ thuộc và được tạm tính
giảm trừ gia cảnh trong năm kể từ khi đăng ký. Đối với người phụ thuộc đã
được đăng ký giảm trừ gia cảnh trước ngày Thông tư này có hiệu lực thi hành
thì tiếp tục được giảm trừ gia cảnh cho đến khi được cấp mã số thuế.
c.2.3) Trường hợp người nộp thuế chưa tính giảm trừ gia cảnh cho người
phụ thuộc trong năm tính thuế thì được tính giảm trừ cho người phụ thuộc kể từ
tháng phát sinh nghĩa vụ nuôi dưỡng khi người nộp thuế thực hiện quyết toán
thuế và có đăng ký giảm trừ gia cảnh cho người phụ thuộc. Riêng đối với người
phụ thuộc khác theo hướng dẫn tại tiết d.4, điểm d, khoản 1, Điều này thời hạn
đăng ký giảm trừ gia cảnh chậm nhất là ngày 31 tháng 12 của năm tính thuế,
quá thời hạn nêu trên thì không được tính giảm trừ gia cảnh cho năm tính thuế
đó.
c.2.4) Mỗi người phụ thuộc chỉ được tính giảm trừ một lần vào một người
nộp thuế trong năm tính thuế. Trường hợp nhiều người nộp thuế có chung người
phụ thuộc phải nuôi dưỡng thì người nộp thuế tự thoả thuận để đăng ký giảm trừ
gia cảnh vào một người nộp thuê.
d.1) Con: con đẻ, con nuôi hợp pháp, con ngoài giá thú, con riêng của vợ,
con riêng của chồng, cụ thê gôm:
d.1.1) Con dưới 18 tuổi (tính đủ theo tháng).
Ví dụ 10: Con ông H sinh ngày 25 tháng 7 năm 2014 thì được tính là
người phụ thuộc từ tháng 7 năm 2014.
d.1.2) Con từ 18 tuổi trở lên bị khuyết tật, không có khả năng lao động.
d.1.3) Con đang theo học tại Việt Nam hoặc nước ngoài tại bậc học đại
học, cao đẳng, trung học chuyên nghiệp, dạy nghẻ, kế cả con từ 18 tuổi trở lên
đang học bậc học phổ thông (tính cả trong thời gian chờ kết quả thi đại học từ
tháng 6 đến tháng 9 năm lớp 12) không có thu nhập hoặc có thu nhập bình quân
tháng trong năm từ tât cả các nguôn thu nhập không vượt quá 1.000.000 đông.
d.2) Vợ hoặc chồng của người nộp thuế đáp ứng điệu kiện tại điểm đ,
khoản 1, Điều này.
d.3) Cha đẻ, mẹ đẻ; cha vợ, mẹ vợ (hoặc cha chồng, mẹ chồng); cha
dượng, mẹ kế; cha nuôi, mẹ nuôi hợp pháp của người nộp thuế đáp ứng điều
kiện tại điểm đ, khoản 1, Điều này.
