d.4) Các cá nhân khác không nơi nương tựa mà người nộp thuế đang phải
trực tiếp nuôi dưỡng và đáp ứng điều kiện tại điểm đ, khoản 1, Điều này bao
gồm:
đ.4.1) Anh ruột, chị ruột, em ruột của người nộp thuế.
d.4.2) Ông nội, bà nội; ông ngoại, bà ngoại; cô ruột, dì ruột, cậu ruột, chú
ruột, bác ruột của người nộp thuê.
d.4.3) Cháu ruột của người nộp thuế bao gồm: con của anh ruột, chị ruột,
em ruột.
d.4.4) Người phải trực tiếp nuôi dưỡng khác theo quy định của pháp luật.
d.3, d.4, điểm d, khoản 1, Điều này phải đáp ứng các điều kiện sau:
._đ Đối với người trong độ tuổi lao động phải đáp ứng đồng thời các
điêu kiện sau:
đ.1.1) Bị khuyết tật, không có khả năng lao động.
đ.1.2) Không có thu nhập hoặc có thu nhập bình quân tháng trong năm từ
tất cả các nguồn thu nhập không vượt quá 1.000.000 đồng.
đ.2) Đối với người ngoài độ tuổi lao động phải không có thu nhập hoặc
có thu nhập bình quân tháng trong năm từ tất cả các nguồn thu nhập không vượt
quá 1.000.000 đồng.
đ.1.1, điểm đ, khoản 1, Điều này là những người thuộc đối tượng điều chỉnh của
pháp luật về người khuyết tật, người mắc bệnh không có khả năng lao động
(như bệnh AIDS, ung thư, suy thận mãn,...). -
g.1) Đối với con:
ø.1.1) Con dưới 18 tuổi: Hồ sơ chứng minh là bản chụp Giấy khai sinh và
