insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều9_K8$md$,$md$TT111-2013$md$,$md$Khoản 8$md$,$md$2) Đối với vợ hoặc chồng, hỗ sơ chứng minh gồm:
- Bản chụp Chứng minh nhân dân.
- Bản chụp số hộ khẩu (chứng minh được mối quan hệ vợ chồng) hoặc
Bản chụp Giấy chứng nhận kết hôn.
Trường hợp vợ hoặc chồng trong độ tuổi lao động thì ngoài các giấy tờ
nêu trên hồ sơ chứng minh cần có thêm giấy tờ khác chứng minh người phụ
thuộc không có khả năng lao động như bản chụp Giấy xác nhận khuyết tật theo
quy định của pháp luật về người khuyết tật đối với người khuyết tật không có
khả năng lao động, bản chụp hồ sơ bệnh án đối với người mắc bệnh không có
khả năng lao động (như bệnh AIDS, ung thư, suy thận mãn,..).
