# Page 38
Các giấy tờ hợp pháp tại tiết g. 4.2, điểm g, khoản 1, Điều này là bất kỳ
giấy tờ pháp lý nào xác định được mối quan hệ của người nộp thuế với người
phụ thuộc như:
- Bản chụp giấy tờ xác định nghĩa vụ nuôi dưỡng theo quy định của pháp
luật (nêu có).
- Bản chụp số hộ khẩu (nếu có cùng số hộ khẩu).
- Bản chụp đăng ký tạm trú của người phụ thuộc (nếu không cùng số hộ
khâu).
-~ Bản tự khai của người nộp thuế theo mẫu ban hành kèm theo văn bản
hướng dẫn về quản lý thuê có xác nhận của Uỷ ban nhân dân cấp xã nơi người
nộp thuế cư trú về việc người phụ thuộc đang sống cùng.
- Bản tự khai của người nộp thuế theo mẫu ban hành kèm theo văn bản
hướng dẫn về quản lý thuế có xác nhận của Uỷ ban nhân dân cấp xã nơi người
phụ thuộc đang cư trú về việc người phụ thuộc hiện đang cư trú tại địa phương,
và không có ai nuôi dưỡng (trường hợp không, sống cùng).
gø.5) Cá nhân cư trú là người nước ngoài, nếu không có hỗ sơ theo hướng
dẫn đối với từng trường hợp cụ thể nêu trên thì phải có các tài liệu pháp lý
tương tự để làm căn cứ chứng minh người phụ thuộc.
g.6) Đối với người nộp thuế làm việc trong các tổ chức kinh tế, các cơ
quan hành chính, sự nghiệp có bố, mẹ, vợ (hoặc chồng), con và những người
khác thuộc diện được tính là người phụ thuộc đã khai rõ trong lý lịch của người
nộp thuế thì hồ sơ chứng mình người phụ thuộc thực hiện theo hướng dẫn tại
các tiết g.l, g.2, g.3, g.4, g- 5, điểm ø, khoản I, Điều này hoặc chỉ cần Tờ khai
đăng ký người phụ thuộc theo mẫu ban hành kèm theo văn bản hướng dẫn về
quản lý thuế có xác nhận của Thủ trưởng đơn vị vào bên trái tờ khai.
Thủ trưởng đơn vị chỉ chịu trách nhiệm đối với các nội dung sau: họ tên
người phụ thuộc, năm sinh và quan hệ với người nộp thuế; các nội dung khác,
người nộp thuế tự khai và chịu trách nhiệm.
h.1) Người nộp thuế có thu nhập từ kinh doanh, từ tiền lương, tiền công
từ 09 triệu đồng/tháng trở xuống, không phải khai người phụ thuộc.
h.2) Người nộp thuế có thu nhập từ kinh doanh, từ tiền lương, tiền công
trên 09 triệu đồng/tháng để được giảm trừ gia cảnh đối với người phụ thuộc khai
như sau:
h.2.1) Đối với người nộp thuế có thu nhập từ tiền lương, tiền công
h.2.1.1) Đăng ký người phụ thuộc
h.2.1.1.1) Đăng ký người phụ thuộc lần đầu:
Người nộp thuế có thu nhập từ tiền lương, tiền công đăng ký người phụ
thuộc theo mẫu ban hành kèm theo văn bản hướng dẫn về quản lý thuế và nộp
