# Page 39
— “me xe
hai (02) bản cho tổ chức, cá nhân trả thu nhập để làm căn cứ tính giảm trừ cho
người phụ thuộc.
Tổ chức, cá nhân trả thu nhập lưu giữ một (01) bản đăng, ký và nộp một
(01) bản đăng ký cho cơ quan thuế trực tiếp quản lý cùng thời điểm nộp tờ khai
thuế thu nhập cá nhân của kỳ khai thuế đó theo quy định của luật quản lý thuế.
Riêng đối với cá nhân trực tiếp khai thuế với cơ quan thuế thì cá nhân
nộp một (01) bản đăng ký người phụ thuộc theo mẫu ban hành kèm theo văn
bản hướng dẫn về quản lý thuế cho cơ quan thuế trực tiếp quản lý tổ chức trả
thu nhập cùng thời điểm nộp tờ khai thuế thu nhập cá nhân của kỳ khai thuế đó
theo quy định của Luật Quản lý thuế.
h.2.1.1.2) Đăng ký khi có thay đổi về người phụ thuộc:
Khi có thay đổi (tăng, giảm). về người phụ thuộc, người nộp thuế thực
hiện khai bổ sung thông tin thay đổi của người phụ thuộc theo mẫu ban hành
kèm theo văn bản hướng dẫn về quản lý thuê và nộp cho tổ chức, cá nhân trả thu
nhập hoặc cơ quan thuế đối với người nộp thuế thuộc diện khai thuế trực tiếp
với cơ quan thuế.
h.2.1.2) Địa điểm, thời hạn nộp hồ sơ chứng minh người phụ thuộc:
- Địa điểm nộp hồ sơ chứng minh người phụ thuộc là nơi người nộp thuế
nộp bản đăng ký người phụ thuộc.
Tổ chức trả thu nhập có trách nhiệm lưu giữ hỗ sơ chứng mỉnh người phụ
thuộc và xuất trình khi cơ quan thuế thanh tra, kiểm tra thuế.
- Thời hạn nộp hồ sơ chứng minh người phụ thuộc: trong vòng ba (03)
tháng kế từ ngày nộp tờ khai đăng ký người phụ thuộc (bao gồm cả trường hợp
đăng ký thay đổi người phụ thuộc).
Quá thời hạn nộp hồ sơ nêu trên, nếu người nộp thuế không nộp hồ sơ
chứng minh người phụ thuộc sẽ không được giảm trừ cho người phụ thuộc và
phải điều chỉnh lại số thuê phải nộp.
h.2.2) Đối với người nộp thuế có thu nhập từ kinh doanh
h.2.2.1) Đăng ký người phụ thuộc
h.2.2.1.1) Cá nhân kinh doanh nộp thuế theo phương pháp kê khai đăng
ký người phụ thuộc theo mẫu ban hành kèm theo văn bản hướng dẫn về quản lý
thuế và nộp cho cơ quan thuế trực tiếp quản lý cùng với tờ khai tạm nộp thuê.
Khi có thay đổi (tăng, giảm) về người phụ thuộc, người nộp thuế thực hiện khai
bổ sung thông tin thay đổi của người phụ thuộc theo mẫu ban hành kèm theo
văn bản hướng dẫn về quản lý thuế và nộp cơ quan thuế trực tiếp quản lý.
h.2.2.1.2) Cá nhân kinh doanh nộp thuế theo phương pháp khoán khai
giảm trừ gia cảnh cho người phụ thuộc theo tờ khai thuê khoán.
h.2.2.2) Thời hạn nộp hồ sơ chứng minh người phụ thuộc: trong vòng ba
(03) tháng kế từ ngày khai giảm trừ gia cảnh (bao gồm cả trường hợp phát sinh
tăng, giảm người phụ thuộc hoặc mới ra kinh doanh).
