insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều9_K3$md$,$md$TT111-2013$md$,$md$Khoản 3$md$,$md$Giảm trừ đối với các khoản đóng góp từ thiện, nhân đạo, khuyến học
nhập chịu thuế đối với thu nhập từ kinh doanh, từ tiên lương, tiền công trước
khi tính thuế của người nộp thuế là cá nhân cư trú, bao gồm:
a.1) Khoản chỉ đóng góp vào các tổ chức, cơ sở chăm sóc, nuôi dưỡng trẻ
em có hoàn cảnh đặc biệt khó khăn, người khuyết tật, người già không nơi
nương tựa.
Các tổ chức cơ sở chăm sóc nuôi đưỡng trẻ em có hoàn cảnh khó khăn,
người khuyết tật, phải được thành lập và hoạt động theo quy định tại Nghị định
sô 68/2008/NĐ-CP ngày 30/5/2008 của Chính phủ quy định điều kiện, thủ tục
thành lập, tô chức, hoạt động và giải thê cơ sở bảo trợ xã hội; Nghị định số
81/2012/NĐ-CP ngày 08/10/2012 của Chính phủ sửa đổi, bổ sung Nghị định
68/2008/NĐ-CP ngày 30/5/2008 của Chính phủ quy định điều kiện, thủ tục
thành lập, tổ chức, hoạt động và giải thể cơ sở bảo trợ xã hội và Nghị định số
109/2002/NĐ-CP ngày 27/12/2002 của Chính phủ sửa đổi, bổ sung một số điều
của Nghị định số 195/CP ngày 31/12/1994 của Chính phủ quy định chỉ tiết và
hướng dẫn thi hành một số điều của Bộ luật lao động về thời giờ làm việc, thời
giờ nghỉ ngơi.
Tài liệu để chứng minh đóng góp vào các tổ chức, cơ sở chăm sóc, nuôi
dưỡng trẻ em có hoàn cảnh đặc biệt khó khăn, người khuyết tật, người già
không nơi nương tựa là chứng từ thu hợp pháp của tô chức, cơ sở.
a.2) Khoản chỉ đóng góp vào các quỹ từ thiện, quỹ nhân đạo, quỹ khuyến
học được thành lập và hoạt động theo quy định tại Nghị định số 30/2012/NĐ-
CP ngày 12/4/2012 của Chính phủ về tô chức, hoạt động của quỹ xã hội, quỹ từ
thiện, hoạt động vì mục đích từ thiện, nhân đạo, khuyên học, không nhằm mục
đích lợi nhuận và quy định tại các văn bản khác có liên quan đến việc quản lý,
sử dụng các nguồn tài trợ.
Tài liệu chứng minh đóng góp từ thiện, nhân đạo, khuyến học là chứng từ
thu hợp pháp do các tổ chức, các quỹ của Trung ương hoặc của tỉnh cấp.
