được xác định bằng giá chuyển nhượng trừ giá mua của phân vốn chuyển
nhượng và các 'chỉ phí hợp lý liên quan đến việc tạo ra thu nhập từ chuyên
nhượng vốn.
Trường hợp doanh nghiệp hạch toán kế toán bằng đồng ngoại tệ, cá nhân
chuyển. nhượng vôn góp băng ngoại tệ thì giá chuyển nhượng và giá mua của
phần vốn chuyên nhượng được xác định bằng đồng ngoại tệ. “Trường hợp ‹ doanh
nghiệp hạch toán kế toán bằng đồng Việt Nam, cá nhân chuyển nhượng vốn góp
bằng ngoại tệ thì giá chuyển nhượng phải được xác định bằng đồng Việt Nam
theo tỷ giá giao dịch bình quân trên thị trường ngoại tệ liên ngân hàng do Ngân
hàng Nhà nước Việt Nam công bồ tại thời điểm chuyên nhượng.
a.1) Giá chuyển nhượng
_Giá chuyển nhượng là số tiền mà cá nhân nhận được theo hợp đồng
chuyên nhượng vồn.
Trường hợp hợp đồng chuyển nhượng không quy định giá thanh toán
hoặc giá thanh toán trên hợp đồng không phù hợp với giá thị trường thì cơ quan
thuế có quyền Ấn định giá chuyển nhượng theo quy định của pháp luật về quản
lý thuế.
a.2) Giá mua
Giá mua của phần vốn chuyển nhượng là trị giá phần vốn góp tại thời
điểm chuyển nhượng vốn.
Trị giá phần vốn góp tại thời điểm chuyển nhượng, bao gồm: trị giá phần
vốn góp thành lập doanh nghiệp, trị giá phần vốn của các lần góp bộ sung, trị
giá phần vốn do mua lại, trị giá phần vốn từ lợi tức ghi tăng vốn. Cụ thể như
Sau:
a.2.1) Đối với phần vốn \ góp thành lập doanh nghiệp là trị giá phần vốn tại
thời điểm góp vốn. Trị giá vốn góp được xác định trên cơ sở số sách kế toán,
hoá đơn, chứng từ.
a.2.2) Đối với phần vốn góp bổ sung là trị giá phần vốn góp bổ sung tại
thời điểm góp vốn bỗ sung. Trị giá vốn góp bổ sung được xác định trên cơ sở số
sách kế toán, hoá đơn, chứng từ.
a.2.3) Đối với phần vốn do mua lại là giá trị phần vốn đó tại thời điểm
mua. Giá mua được xác định căn cứ vào hợp đồng mua lại phần vốn góp.
Trường hợp hợp đồng mua lại phần vốn góp không có giá thanh toán hoặc giá
thanh toán trên hợp đồng không phù hợp với giá thị trường thì cơ quan thuế có
quyền ấn định giá mua theo pháp luật về quản lý thuế .
__ 8.2.4) Đối với phần vốn từ lợi tức ghi tăng vốn là giá trị lợi tức ghi tăng
vôn.
a.3) Các chỉ phí liên quan được trừ khi xác định thu nhập chịu thuế của
hoạt động chuyển nhượng vốn là những chỉ phí hợp lý thực tê phát sinh liên
quan đến việc tạo ra thu nhập từ chuyển nhượng vốn, có hoá đơn, chứng từ hợp
