insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều11_K2$md$,$md$TT111-2013$md$,$md$Khoản 2$md$,$md$Đối với thu nhập từ chuyển nhượng chứng khoán
Căn cứ tính thuế đối với hoạt động chuyển nhượng chứng khoán là thu
nhập tính thuê và thuê suât.
Thu nhập tính thuế từ chuyển nhượng chứng khoán được xác định bằng
giá bán chứng khoán trừ giá mua và các chi phí hợp lý liên quan đến việc
chuyển nhượng.
a.1) Giá bán chứng khoán được xác định như sau:
a.1.1) Đối với chứng khoán của công ty đại chúng giao dịch trên Sở Giao
dịch chứng khoán, giá bán chứng khoán là giá thực hiện tại Sở Giao dịch chứng,
khoán. Giá thực hiện là giá chứng khoán được xác định từ kêt quả khớp lệnh
hoặc giá hình thành từ các giao dịch thỏa thuận tại Sở Giao dịch chứng khoán.
a.1.2) Đối với chứng khoán của công ty đại chúng không thực hiện giao
dịch trên Sở Giao dịch chứng khoán mà chỉ thực hiện chuyển quyền sở hữu qua
hệ thống chuyển quyền của Trung tâm lưu ký chứng khoán, giá bán là giá ghi
trên hợp đồng chuyên nhượng chứng khoán.
a.1.3) Đối với chứng khoán không thuộc các trường hợp nêu trên, giá bán
là giá thực tê chuyên nhượng ghi trên hợp đông chuyên nhượng hoặc giá theo sô
sách kế toán của đơn vị có chứng khoán chuyên nhượng tại thời điểm gần nhất
trước thời điêm chuyên nhượng.
44
<!-- Page Break -->
# Page 45
Trường hợp hợp đồng chuyển nhượng không quy định giá bán hoặc giá
bán trên hợp đồng không phù hợp với giá thị trường thì cơ quan thuế có quyền
ấn định giá bán theo pháp luật về quản lý thuế.
a.2) Giá mua chứng khoán được xác định như sau:
a.2.1) Đối với chứng khoán của công ty đại chúng giao dịch trên Sở Giao
dịch chứng khoán, giá mua chứng khoán là giá thực hiện tại Sở Giao dịch chứng
khoán. Giá thực hiện là giá chứng khoán được xác định từ kết quả khớp lệnh
hoặc giá hình thành từ các giao dịch thỏa thuận tại Sở Giao dịch chứng khoán.
,a.2.2) Đối với chứng khoán của công ty đại chúng không thực hiện giao
dịch trên Sở Giao dịch chứng khoán mà chỉ thực hiện chuyển quyền sở hữu qua
hệ thống chuyển quyền của Trung tâm lưu ký chứng khoán, giá mua là giá ghỉ
trên hợp đông nhận chuyên nhượng chứng khoán.
a.2.3) Đối với chứng khoán mua thông qua đấu giá thì giá mua chứng
khoán là mức giá ghi trên thông báo kết quả trúng đấu giá cổ phần của tổ chức
thực hiện đấu giá cô phần và giấy nộp tiền.
a.2.4) Đối với chứng khoán không thuộc các trường hợp nêu trên, giá mua
là giá thực tế mua ghỉ trên hợp đồng nhận chuyển nhượng hoặc giá theo sô sách
kế toán của đơn vị có chứng khoán chuyển nhượng tại thời điểm gần nhất trước
thời điểm mua.
Trường hợp hợp đồng chuyển nhượng không quy định giá mua hoặc giá
mua trên hợp đồng không phù hợp với giá thị trường thì cơ quan thuế có quyền
ấn định giá mua theo pháp luật về quản lý thuế.
a.3) Các chỉ phí hợp lý được trừ khi xác định thu nhập chịu thuế đối với
chuyển nhượng chứng khoán là các khoản chỉ phí thực tế phát sinh của hoạt
động chuyển nhượng chứng khoán có hoá đơn, chứng từ theo chế độ quy định
bao gôm:
a.3.1) Chi phí để làm các thủ tục pháp lý cần thiết cho việc chuyến
nhượng.
a.3.2) Các khoản phí và lệ phí người chuyển nhượng phải nộp khi làm thủ
tục chuyên nhượng.
a.3.3) Phí dịch vụ lưu ký chứng khoán theo quy định của Bộ Tài chính và
chứng từ thu của công ty chứng khoán.
a.3.4) Phí uỷ thác đầu tư, phí quản lý danh mục đầu tư chứng khoán căn
cứ vào chứng từ thu của đơn vị nhận uỷ thác.
a.3.5) Phí môi giới chứng khoán khi chuyển nhượng.
a.3.6) Phí dịch vụ tư vấn đầu tư và cung cấp thông tin.
a.3.7) Phí chuyển khoản, phí chuyển quyền sở hữu qua Trung tâm lưu ký
chứng khoán (nêu có).
a.3.8) Các khoản chỉ phí khác có chứng từ chứng minh.
