Trường hợp nhận cỗ tức bằng cổ phiếu, cá nhân chưa phải nộp thuế thu
nhập cá nhân khi nhận cô phiếu. Khi chuyển nhượng số cổ phiếu này, cá nhân
phải nộp thuế thu nhập cá nhân đối với thu nhập từ đầu tư vốn và thu nhập từ
