d.1) Căn cứ để xác định. số thuế thu nhập cá nhân phải nộp đối với thu
nhập từ đầu tư vốn là giá trị cỗ tức ghỉ trên số sách kế toán hoặc số lượng cổ
phiêu thực nhận nhân (<) với mệnh giá của cỗ phiếu đó và thuế suất thuế thu
