Trường hợp giá chuyển nhượng cỗ phiếu nhận thay cỗ tức thấp hơn mệnh
giá thì tính thuê thu nhập cá nhân đôi với hoạt động đâu tư vôn theo giá thị
trường tại thời điểm chuyên nhượng.
Sau khi nhận cổ tức bằng cỗ phiếu, nếu cá nhân có chuyên nhượng, cổ
phiếu cùng loại thì khai và nộp thuế thu nhập cá nhân đối với cỗ tức nhận bằng
cỗ phiếu cho tới khi hết số cỗ phiếu nhận thay cỗ tức.
d.2) Căn cứ để xác định số thuế thu nhập cá nhân phải nộp đối với thu
nhập từ chuyển nhượng chứng khoán được xác định theo hướng dẫn tại điểm b,
khoản 2, Điêu này.
