công trình xây dựng trên đất được xác định bằng giá chuyển nhượng trừ (-) giá
vôn và các chỉ phí hợp lý liên quan.
a.1) Giá chuyển nhượng,
Giá chuyển nhượng quyền sử dụng đất là giá thực tế ghi trên hợp đồng
chuyển nhượng tại thời điểm chuyển nhượng.
Trường hợp không xác định được giá thực tế chuyên nhượng, hoặc giá ghỉ
trên hợp đồng chuyển nhượng thấp hơn giá đất do Uỷ ban nhân dân cấp tỉnh quy
định tại thời điểm chuyển nhượng thì giá chuyển nhượng sẽ được xác định theo
bảng giá đất do Uỷ ban nhân dân cấp tỉnh quy định.
a.2) Giá vốn:
,_ Giá vốn chuyển nhượng quyền sử dụng đất trong một số trường hợp cụ
thê được xác định như sau:
a.2.1) Đối với đất có nguồn gốc Nhà nước giao có thu tiền sử dụng đất thì
giá vốn căn cứ vào chứng từ thu tiền sử dụng, đất của Nhà nước.
a.2.2) Đối với đất có nguồn gốc do Nhà nước giao không phải trả tiền
hoặc được giảm tiền sử dụng đất theo quy định của pháp luật thì giá vôn của đất
chuyển nhượng được xác định theo giá do Uỷ ban nhân dân cấp tỉnh quy định
tại thời điểm giao đất.
a.2.3) Đối với đất nhận chuyển nhượng, quyền sử dụng từ các tổ chức, cá
nhân thì giá vốn căn cứ vào giá ghi trên hợp đồng chuyển nhượng tại thời điểm
nhận chuyển nhượng quyền sử dụng đất.
a.2.4) Đối với trường, hợp đấu giá chuyển quyền sử dụng đất thì giá vốn là
số tiền phải thanh toán theo giá trúng đấu giá.
.a.2.5) Đối với đất có nguồn gốc không thuộc các trường hợp nêu trên thì
giá vốn căn cứ vào chứng từ chứng minh thực hiện nghĩa vụ tài chính với Nhà
nước khi được cấp Giấy chứng nhận quyền sử dụng đất, quyền sở hữu nhà ở và
tài sản khác gắn liền với đất để xác định giá vốn.
a.3) Chỉ phí hợp lý liên quan
Chỉ phí hợp lý liên quan được trừ khi xác định thu nhập từ chuyên quyền
sử dụng đất là các chỉ phí thực tế phát sinh liên quan đến hoạt động chuyên
nhượng có chứng từ, hoá đơn theo chế độ quy định, bao gồm:
48
<!-- Page Break -->
# Page 49
a.3.1) Các loại phí, lệ phí theo quy định của pháp luật liên quan đến cấp
quyền sử dụng đất mà người chuyền nhượng đã nộp ngân sách Nhà nước.
a.3.2) Chỉ phí cải tạo đất, san lắp mặt bằng (nếu có).
a.3.3) Các chỉ phí khác liên quan trực tiếp đến việc chuyển nhượng quyền
sử dụng đất như chỉ phí để làm các thủ tục pháp lý cho việc chuyển nhượng, chỉ
phí thuê đo đạc.
trình Xây dựng trên đất, kể cả công trình xây dựng hình thành trong tương lai
được xác định bằng giá chuyển nhượng trừ (-) giá vốn và các chỉ phí hợp lý liên
quan."
b.1) Giá chuyển nhượng
Giá chuyển nhượng là giá thực tế ghi trên hợp đồng chuyển nhượng tại
thời điểm chuyên nhượng.
Trường hợp hợp đồng: không ghỉ giá chuyển nhượng hoặc giá chuyển
nhượng ghỉ trên hợp đồng thấp hơn giá do Uỷ ban nhân dân cập tỉnh quy định
thì giá chuyên nhượng, được xác định theo bảng giá đất, giá tính lệ phí trước bạ
nhà do Uỷ ban nhân dân cấp tỉnh quy định tại thời điểm chuyển nhượng.
Trường hợp Uỷ ban nhân dân cấp tỉnh không có quy định giá tính lệ phí
trước bạ nhà thì giá chuyển nhượng căn cứ vào quy định của Bộ Xây dựng về
phân loại nhà, về tiêu chuẩn, định mức xây dựng cơ bản, về giá trị còn lại thực
tế của công trình trên đất.
Đối với công trình xây dựng hình thành trong tương lai thì được xác định
căn cứ vào tỷ lệ góp vốn trên tổng giá trị hợp đồng nhân () với giá tính lệ phí
trước bạ công trình xây dựng do Uỷ ban nhân dân cấp tỉnh quy định. Trường
hợp Uỷ ban nhân dân cấp tỉnh chưa có quy định vê đơn giá thì áp dụng theo
suất vốn đầu tư xây dựng công trình do Bộ Xây dựng công bó, đang áp dụng tại
thời điểm chuyên nhượng.
b.2) Giá vốn
Giá vốn được xác định căn cứ vào giá ghi trên hợp đồng chuyển nhượng
tại thời điểm mua. Đối với các trường hợp bắt động sản không có nguồn gốc từ
nhận chuyển nhượng thì giá vốn căn cứ vào chứng từ chứng minh thực hiện
nghĩa vụ tài chính với Nhà nước tại thời điểm được câp Giấy chứng nhận quyên
sử dụng đất, quyền sở hữu nhà ở và tải sản khác gắn liên với đất.
b.3) Chỉ phí hợp lý liên quan
Chi phí hợp lý liên quan được trừ khi xác định thu nhập từ chuyển quyền
sử dụng đất là các khoản chỉ phí thực tế phát sinh có liên quan đến hoạt động
chuyên nhượng, có hoá đơn, chứng từ hợp pháp, bao gồm:
b.3.1) Các loại phí, lệ phí theo quy định của pháp luật liên quan đến cấp
quyền sử dụng đất người chuyển nhượng đã nộp ngân sách Nhà nước.
b.3.2) Chỉ phí cải tạo đất, san lắp mặt bằng,
b.3.3) Chỉ phí xây dựng, cải tạo, nâng cấp, sửa chữa kết cấu hạ tầng và
49
<!-- Page Break -->
# Page 50
công trình kiến trúc trên đất.
b.3.4) Các chỉ phí khác liên quan trực tiếp đến việc chuyển nhượng bất
động sản như: chỉ phí để làm các thủ tục pháp lý cho việc chuyển nhượng, chỉ
phí thuê đo đạc.
thành trong tương lai.
Thu nhập tính thuế từ chuyển quyền sở hữu nhà ở được xác định bằng giá
bán trừ (-) giá mua và các chỉ phí hợp lý liên quan.
,e.1) Giá bán
Giá bán là giá thực tế chuyển nhượng được xác định theo giá thị trường
và được ghi trên hợp đông chuyên nhượng.
._ Trường hợp giá chuyển nhượng nhà ghi trên hợp đồng chuyển nhượng
thấp hơn giá tính lệ phí trước bạ nhà do Uỷ ban nhân dân cập tỉnh quy định tại
thời điểm chuyên nhượng hoặc trên hợp đông chuyên nhượng không ghỉ giá
chuyền nhượng thì giá chuyên nhượng được xác định theo giá tính lệ phí trước
bạ do Uỷ ban nhân dân cấp tỉnh quy định.
c.2) Giá mua
Giá mua được xác định căn cứ vào giá ghi trên hợp đồng mua. Đối với
nhà ở không có nguồn gốc từ nhận chuyển nhượng, mua lại thì căn cứ vào
chứng từ chứng minh thực hiện nghĩa vụ tài chính với Nhà nước tại thời điểm
được cổ Giấy chứng nhận quyển sử dụng đất, quyền sở hữu nhà ở và tài sản
khác gắn liền với đất.
c.3) Chi phí hợp lý liên quan
Chỉ phí hợp lý liên quan được trừ là các khoản chỉ phí thực tế phát sinh
của hoạt động chuyên nhượng có hoá đơn, chứng từ hợp pháp, bao gồm:
c.3.1) Các loại phí, lệ phí theo quy định của pháp luật liên quan đến cấp
quyền sử dụng nhà người chuyển nhượng đã nộp ngân sách.
c.3.2) Chi phí sửa chữa, cải tạo, nâng, cấp nhà.
c.3.3) Các chỉ phí khác liên quan trực tiếp đến việc chuyển nhượng.
Thu nhập tính thuế từ chuyển nhượng quyển thuê đất, thuê mặt nước
được xác định băng giá cho thuê lại trừ (-) giá thuê và các chỉ phí liên quan.
d.1) Giá cho thuê lại
Giá cho thuê lại được xác định bằng giá thực tế ghi trên hợp đồng tại thời
điểm chuyền nhượng quyền thuê mặt đất, thuê mặt nước.
Trường hợp đơn giá cho thuê lại trên hợp đồng thấp hơn giá do Uỷ ban
nhân dân tỉnh, thành phố quy định tại thời điểm cho thuê lại thì giá cho thuê lại
được xác định căn cứ theo bảng giá thuê do Uỷ ban nhân dân tỉnh, thành phố
quy định.
$0
<!-- Page Break -->
# Page 51
đ.2) Giá thuê
Giá thuê được xác định căn cứ vào hợp đồng thuê.
d.3) Chỉ phí hợp lý liên quan
Chỉ phí hợp lý liên quan , được trừ là các khoản chỉ phí thực tế phát sinh từ
hoạt động chuyên nhượng quyền có hoá đơn, chứng từ hợp pháp, bao gồm:
d.3.1) Các loại phí, lệ phí theo quy định của pháp luật có liên quan đến
quyền thuê đất, thuê mặt nước mà người chuyển quyền đã nộp ngân sách Nhà
nước;
d.3.2) Các chỉ phí cải tạo đất, mặt nước;
d.3.3) Các chỉ phí khác liên quan trực tiếp đến việc chuyển quyền thuê
đất, thuê mặt nước.
2) Thuế suất
__ Thuế suất đối với chuyên nhượng bất động sản là 25% trên thu nhập tính
thuê.
Trường hợp người nộp thuế không xác định hoặc không có hồ sơ để xác
định giá vôn hoặc giá mua hoặc giá thuê và chứng, từ hợp pháp xác định các chỉ
phí liên quan làm cơ sở xác định thu nhập tính thuê thì áp dụng thuê suât 2%
trên giá chuyên nhượng hoặc giá bán hoặc giá cho thuê lại.$md$,$md$TT111-2013_Điều12$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
