quan của hoạt động chuyển nhượng bất động sản làm cơ sở xác định thu nhập
tính thuế thì thuế thu nhập cá nhân được xác định như sau:
Thuế thu nhập cá nhân - Giá chuyển x Thuế suất
phải nộp nhượng 2%
được xác định riêng cho từng người nộp thuế theo tỷ lệ sở hữu bất động sản.
Căn cứ xác định tỷ lệ sở hữu là tài liệu hợp pháp như: thoả thuận góp vôn ban
đầu, di chúc hoặc quyết định phân chia của toà án,... Trường hợp không có tài
liệu hợp pháp thì nghĩa vụ thuế của từng người nộp thuế được xác định theo tỷ
