insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều15_K1$md$,$md$TT111-2013$md$,$md$Khoản 1$md$,$md$Thu nhập tính thuế
“Thu nhập tính thuế từ trúng thưởng là phần giá trị giải thưởng vượt trên
10 triệu đồng mà người nộp thuế nhận được theo từng lần trúng thưởng không
phụ thuộc vào số lần nhận tiền thưởng.
Trường hợp một giải thưởng nhưng có nhiều người trúng giải thì thu nhập
tính thuê được phân chia cho từng người nhận giải thưởng. Người được trúng,
giải phải xuất trình các căn cứ pháp lý chứng minh. Trường hợp không có căn
cứ pháp lý chứng minh thì thu nhập trúng thưởng tính cho một cá nhân. Trường
hợp cá nhân trúng nhiều giải thưởng trong một cuộc chơi thì thu nhập tính thuê
được tính trên tông giá trị của các giải thưởng.
Thu nhập tính thuế đối với một số trò chơi có thưởng, cụ thể như sau:
2) Đối với trúng thưởng, xổ số là toàn bộ giá trị tiền thưởng vượt trên 10
triệu đông trên một (01) vé xô sô nhận được trong một đợt quay thưởng chưa
trừ bât cứ một khoản chi phí nào.
khuyến mại vượt trên 10 triệu đông được quy đôi thành tiên theo giá thị trường
tại thời điểm nhận thưởng chưa trừ bất cứ một khoản chỉ phí nào.
€) Đối với trúng thưởng trong các hình thức cá cược, đặt cược, casino,
trúng thưởng trong các hình thức trò chơi tại Điêm vui chơi giải trí có thưởng:
e.1) Đối với trúng thưởng trong các hình thức cá cược, đặt cược là toàn
bộ giá trị giải thưởng vượt trên 10 triệu đông mà người tham gia nhận được
chưa trừ bât cứ một khoản chi phí nào.
c.2) Đối với trúng thưởng trong các casino, trúng, thường trong các hình
thức trò chơi tại Điểm vui chơi giải trí có thưởng là phần giá trị vượt trên 10
triệu đồng mà cá nhân nhận được từ trúng thưởng trong một cuộc chơi, cụ thể
như sau:
c.2.1) Thu nhập từ trúng thưởng trong một cuộc chơi là chênh lệch giữa
số tiền mặt người chơi nhận lại (cash out) trừ đi số tiền mặt đã chỉ ra (cash in)
trong một cuộc chơi.
5
<!-- Page Break -->
# Page 54
Trường hợp thu nhập từ trúng thưởng là ngoại tệ thì phải quy đôi ra đồng
Việt Nam theo tỷ giá ngoại tệ do Ngân hàng Nhà nước công. bố có hiệu lực tại
thời điểm phát sinh thu nhập.
c.2.2) Cách xác định số tiền mặt nhận lại và số tiền mặt đã chỉ ra trong,
một cuộc chơi như sau:
c.2.2.1) Đối với hình thức chơi bằng, đồng tiền quy ước (đồng chíp, đồng
chíp trung gian và đồng xèng theo Quy chế quản lý tài chính đối với hoạt động
kinh doanh trò chơi có thưởng của Bộ Tài chính):
c.2.2.1.1) Số tiền mặt người chơi nhận lại (cash out) trong một cuộc chơi
là tổng giá trị các lần người chơi đổi đồng chíp/xèng lấy tiền mặt trong suốt một
cuộc chơi.
c.2.2.1.2) Số tiền mặt đã chỉ ra (cash in) trong một cuộc chơi là tống giá
trị các lần người chơi đổi tiền mặt lấy đồng chíp/xèng trong suốt một cuộc chơi.
Căn cứ xác định số tiền mặt nhận lại và số tiền mặt đã chỉ ra trong một
cuộc chơi là hoá đơn đổi tiền cho khách (theo mẫu kèm theo Quy chế quản lý tài
chính đối với hoạt động kinh doanh trò chơi có thưởng của Bộ Tài chính) và các
hoá đơn, chứng từ theo quy định của pháp luật kế toán hiện hành.
Ví dụ 13: Ông M từ lúc vào cho đến lúc ra khỏi Điểm vui chơi giải trí có
thưởng đã thực hiện 3 lần n mặt lấy đồng chíp, tổng giá trị của cả 3 lần là
500 USD và thực hiện 2 lần đổi đông chíp lấy tiền mặt, tổng giá trị cả 2 lần đối
là 700 USD. Căn cứ các lần đổi tiền thì thu nhập từ trúng thưởng và thu nhập
tính thuế của Ông A được xác định như sau :
~ Thu nhập từ trúng thưởng = 700 USD - 500 USD = 200 USD.
- Thu nhập tính thuế = 200 USD x tỷ giá USD/VND - 10 triệu đồng
c.2.2.2) Đối với hình thức chơi với máy chơi tự động bằng tiền mặt:
c.2.2.2.1) Số tiền mặt người chơi nhận lại trong một cuộc chơi là tổng giá
trị số tiền rút khỏi máy chơi (Cash out) khi kết thúc một cuộc chơi trừ đi phần
giải thưởng tích luỹ (nếu có).
©.2.2.2.2) Số tiền mặt đã chỉ ra trong một cuộc chơi là tổng giá trị các lần
nạp tiền mặt vào máy chơi (Key in/Cash in) trong, suốt một cuộc chơi.
Riêng đối với hình thức trúng thưởng từ giải thưởng tích luỹ (jackpot),
các giải thưởng định kỳ cho khách may mắn và các hình thức tương tự khác thì
thu nhập từ trúng thưởng là toàn bộ giá trị giải thưởng chưa trừ bất cứ một
khoản chỉ phí nào khác.
Ví dụ 14: Ông N chơi trực tiếp với máy chơi tự động dùng. tiền mặt.
Trong một cuộc chơi Ông N đã thực hiện 2 lần nạp tiền (Key in), tông giá trị
các lân nạp tiền (Key in) là 300 USD. Khi kết thúc cuộc chơi Ông N rút toàn bộ
số tiền còn lại khỏi máy chơi (Cash out), tổng, số tiền mặt còn lại (Cash out) là
thưởng tích luỳy (jackpot) là 1.000 USD (Giá trị giải thưởng jackpot đã được
cộng dồn trong số tiền Cash out). Căn cứ số tiền nạp vào và số tiền rút ra thì thu
