thừa kế, quà tặng vượt trên 10 triệ đồng mỗi lần nhận. Giá trị tài sản nhận thừa
kế, quà tặng được xác định đối với từng trường hợp, cụ thể như sau:
là giá trị chứng khoán tại thời điểm đăng ký chuyển quyền sở hữu, cụ thể như
Sau:
a.1) Đối với chứng khoán giao dịch trên Sở Giao dịch chứng khoán: giá
trị của chứng khoán được căn cứ vào giá tham chiêu trên Sở giao dịch chứng
khoán tại thời điểm đăng ký quyên sở hữu chứng khoán.
a.2) Đối với chứng khoán không thuộc trường hợp trên: giá trị của chứng
khoán được căn cứ vào giá trị số sách kế toán của công ty phát hành loại chứng,
khoán đó tại thời điểm gần nhất trước thời điểm đăng ký quyền sở hữu chứng
khoán.
kinh doanh: thu nhập để tính thuế là giá trị của phần. vốn góp được xác định căn
cứ vào giá trị số sách kế toán của công ty tại thời điểm gần nhất trước thời điểm
đăng ký quyền sở hữu phần vốn góp.
€) Đối với tài sản thừa kế, quà tặng là:bất động sản: giá trị bất động sản
được xác định như sau:
c.1) Đối với bất động sản lả giá trị quyền sử dụng đất thì phần giá trị
quyền sử dụng đất được xác định căn cứ vào Bảng giá đất do Uỷ ban nhân dân
cấp tỉnh quy định tại thời điểm cá nhân làm thủ tục đăng ký quyền sử dụng bất
động sản.
c.2) Đối với bất động sản là nhà và công trình kiến trúc trên đất thì giá trị
bất động sản được xác định căn cứ vào quy định của cơ quan quản lý Nhà nước
có thâm quyền về phân loại giá trị nhà; quy định tiêu chuân, định mức xây dựng
cơ bản do cơ quan quản lý Nhà nước có thâm quyển ban hành; giá trị còn lại của
nhà, công trình kiến trúc tại thời điểm làm thủ tục đăng ký quyền sở hữu.
Trường hợp không xác định được theo quy định trên thì căn cứ vào giá
tính lệ phí trước bạ do Uỷ ban nhân dân cập tỉnh quy định.
hữu hoặc quyên sứ dụng với cơ quan quản lý Nhà nước: giá trị tài sản được xác
định trên cơ sở bảng giá tính lệ phí trước bạ do Uỷ ban nhân dân cấp tỉnh quy
