quản lý thuê.
b.1) Cá nhân có thu nhập chịu thuế từ tiền lương, tiền công nộp hồ sơ
đăng ký thuế cho tổ chức, cá nhân trả thu nhập hoặc cơ quan thuế trực tiếp quản
lý tô chức, cá nhân trả thu nhập. Tổ chức, cá nhân trả thu nhập có trách nhiệm
tổng hợp tờ khai đăng ký thuế của cá nhân và nộp cho cơ quan thuế trực tiếp
quản lý.
b.2) Cá nhân có nhiều nguồn thu nhập: từ kinh doanh, từ tiền lương, tiền
công, từ các khoản thu nhập chịu thuế khác được lựa chọn địa điểm nộp hồ sơ
đăng ký thuế tại cơ quan, đơn vị trả thu nhập hoặc tại Chỉ cục Thuế nơi kinh
doanh.
_. b.3) Cá nhân có thu nhập chịu thuế khác có thể nộp hồ sơ đăng ký thuế tại
bất kỳ cơ quan thuê nào.$md$,$md$TT111-2013_Điều24$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
