insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều25_K1$md$,$md$TT111-2013$md$,$md$Khoản 1$md$,$md$Khấu trừ thuế
__ Khấu trừ thuế là việc tổ chức, cá nhân trả thu nhập thực hiện tính trừ số
thuế phải nộp vào thu nhập của người nộp thuế trước khi trả thu nhập, cụ thể
như sau:
62
<!-- Page Break -->
# Page 63
Tổ chức, cá nhân trả các khoản thu nhập chịu thuế cho cá nhân không cư
trú có trách nhiệm khâu trừ thuê thu nhập cá nhân trước khi trả thu nhập. Số
thuê phải khâu trừ được xác định theo hướng dân tại Chương III (từ Điêu 17 đến
Điêu 23) Thông tư này.
b.1) Đối với cá nhân cư trú ký hợp đồng lao động từ ba (03) tháng trở lên
thì tổ chức, cá nhân trả thu nhập thực hiện khấu trừ thuế theo Biểu thuế luỹ tiến
từng phần, kể cả trường hợp cá nhân ký hợp đồng từ ba (03) tháng trở lên tại
nhiêu nơi.
b.2) Đối với cá nhân cư trú ký hợp đồng lao động từ ba (03) tháng trở lên
nhưng nghỉ làm trước khi kết thúc hợp đồng lao động thì tổ chức, cá nhân trả
thu nhập vẫn thực hiện khâu trừ thuế theo Biểu thuế luỹ tiến từng phân.
b.3) Đối với cá nhân là người nước ngoài vào làm việc tại Việt Nam thì tổ
chức, cá nhân trả thu nhập căn cứ vào thời gian làm việc tại Việt Nam của người
nộp thuế ghi trên Hợp đông hoặc văn bản cử sang làm việc tại Việt Nam để tạm
khấu trừ thuế theo Biểu lũy tiến từng phần (đối với cá nhân có thời gian làm
việc tại Việt Nam từ 183 ngày trong năm tính thuế) hoặc theo Biểu thuế toàn
phân (đối với cá nhân có thời gian làm việc tại Việt Nam dưới 183 ngày trong,
năm tính thuế).
b.4) Doanh nghiệp bảo hiểm, công ty quản lý Quỹ hưu trí tự nguyện có
trách nhiệm khấu trừ thuế thu nhập cá nhân đối với tiền tích lũy mua bảo. hiểm
không bắt buộc, tiền tích lũy đóng quỹ hưu trí tự nguyện theo hướng dẫn tại
khoản 6, Điều 7 Thông tư này.
b.5) Số thuế phải khấu trừ đối với thu nhập từ tiền lương, tiền công của cá
nhân cư trú được xác định theo hướng dẫn tại Điều 7 Thông tư này; của cá nhân
không cư trú được xác định theo Điều 18 Thông tư này.
Công ty xổ số, doanh nghiệp bảo hiểm, doanh nghiệp bán hàng đa cấp trả
thu nhập cho cá nhân làm đại lý xô số, đại lý bảo hiểm, tham gia mạng lưới bán
hàng đa cấp có trách nhiệm khấu trừ thuế thu nhập cá nhân trước khi trả thu
nhập cho cá nhân. Số thuế khấu trừ được xác định theo hướng dẫn tại khoản 5,
Điều 7 Thông tư này.
l Tổ chức, cá nhân trả thu nhập từ đầu tư vốn theo hướng dẫn tại khoản 3,
Điều 2 Thông tư này có trách nhiệm khâu trừ thuê thu nhập cá nhân trước khi
trả thu nhập cho cá nhân trừ trường hợp cá nhân tự khai thuê theo hướng dẫn tại
khoản 9, Điều 26 Thông tư này. Số thuế khấu trừ được xác định theo hướng dẫn
tại Điều 10 Thông tư này.
63
<!-- Page Break -->
# Page 64
Mọi trường hợp chuyển nhượng chứng khoán đều phải khấu trừ thuế theo
thuế suất 0,1% trên giá. chuyển nhượng trước khi thanh toán cho người chuyển
nhượng. Cụ thể việc khấu trừ thuế được thực hiện như sau:
đ.1) Đối với chứng khoán giao dịch trên Sở Giao dịch chứng khoán:
đ.1.1) Công ty chứng khoán, ngân hàng thương mại nơi cá nhân mở tài
khoản lưu ký chứng khoán có trách nhiệm khâu trừ thuê thu nhập cá nhân theo
thuế suất 0,1% trên giá chuyển nhượng trước khi thanh toán tiền cho cá nhân.
Số thuế khẩu trừ được xác định như hướng dẫn tại điểm b.2, khoản 2, Điều I1
Thông tư này.
"41. 2) Công ty quản lý quỹ nơi cá nhân ủy thác quản lý danh mục. đầu tư
chứng khoán có trách nhiệm khấu trừ thuế thu nhập cá nhân theo thuế suất 0,1%
trên giá chuyển nhượng chứng khoán của cá nhân ủy thác danh mục đầu tư
chứng khoán theo bảng phân bô của công ty gửi ngân hàng lưu ký mà công ty
mở tài khoản lưu ký.
đ.2) Đối với chứng khoán chuyển nhượng không qua hệ thống giao dịch
trên Sở Giao dịch chứng khoán:
đ.2.1) Đối với chứng khoán của công ty đại chúng đã đăng ký chứng
khoán tập trung tại Trung tâm lưu ký chứng khoán:
Công ty chứng khoán, ngân hàng thương mại nơi cá nhân mở tài khoản
lưu ký chứng khoán khấu trừ thuế thu nhập cá nhân theo thuế suất 0,1% trên giá
chuyên nhượng trước khi làm thủ tục chuyển quyền sở hữu chứng khoán tại
Trung tâm Lưu ký chứng khoán.
đ.2.2) Đối với chứng khoán của công ty cỗ phần chưa là công ty đại chúng
nhưng tổ chức phát hành chứng khoán ủy quyền cho công ty chứng khoán quản
lý danh sách cổ đông:
Công ty chứng khoán được uỷ ‹ quyền quản lý danh sách cỗ đông khấu trừ
thuế thu nhập cá nhân (heo thuế suất 0,1% trên giá chuyển nhượng trước khi
làm thủ tục chuyển quyền sở hữu chứng khoán.
Cá nhân chuyển nhượng chứng khoán phải xuất trình hợp đồng chuyển
nhượng với Công ty chứng khoán khi làm thủ tục chuyền quyền sở hữu chứng
khoán.
e.Thu nhập từ chuyển nhượng vốn góp của cá nhân không cư trú
Tổ chức, cá nhân nhận chuyển nhượng, vốn góp của cá nhân không cư trú
có trách nhiệm khấu trừ thuế thu nhập cá nhân theo thuế suất 0,1% trên giá
chuyển nhượng vốn ĐÓP.
Tổ chức trả tiền thưởng có trách nhiệm khấu trừ thuế thu nhập cá nhân
trước khi trả thưởng cho cá nhân trúng thưởng. Sô thuê khâu trừ được xác định
theo hướng dẫn tại Điêu 15 Thông tư này.
64
<!-- Page Break -->
# Page 65
Tổ chức, cá nhân trả thu nhập từ bản quyền, nhượng quyền thương mại có
trách nhiệm khấu trừ thuế thu nhập cá nhân trước khi trả thu nhập cho cá nhân.
Số thuế khấu trừ được xác định bằng phần thu nhập vượt trên 10 triệu đồng theo
từng hợp đồng chuyển nhượng nhân (x) với thuế suất 5%. Trường hợp hợp
đồng có giá trị lớn thanh toán làm nhiều lần thì lần đầu thanh toán, tổ chức, cá
nhân trả thu nhập trừ 10 triệu đồng khỏi giá trị thanh toán, số còn lại phải nhân
với thuế suất 5% để khấu trừ thuế. Các lần thanh toán sau sẽ khẩu trừ thuế thu
nhập tính trên tổng số tiền thanh toán của từng lần.
?) Khấu trừ thuế đối với một số trường hợp khác
Các tổ chức, cá nhân trả tiền công, tiền thù lao, tiền chỉ khác cho cá nhân
cư trú không ký hợp đồng lao động (theo hướng dẫn tại điểm c, d, khoản 2, Điều
2 Thông tư này) hoặc ký hợp đồng lao động dưới ba (03) tháng có tổng mức trả
thu nhập từ hai triệu (2.000.000) đông/lần trở lên thì phải khấu trừ thuế theo mức
10% trên thu nhập trước khi trả cho cá nhân.
Trường hợp cá nhân chỉ có duy nhất thu nhập thuộc đối tượng phải khấu
trừ thuế theo tỷ lệ nêu trên nhưng ước tính tổng mức thu nhập chịu thuế của cá
nhân sau khi trừ gia cảnh chưa đến mức phải nộp thuế thì cá nhân có thu nhập
làm cam kết (theo mẫu ban hành kèm theo văn bản hướng dẫn về quản lý thuê)
gửi tổ chức trả thu nhập để tổ chức trả thu nhập làm căn cứ tạm thời chưa khấu
trừ thuế thu nhập cá nhân.
Căn cứ vào cam kết của người nhận thu nhập, tô chức trả thu nhập không
khấu trừ thuế. Kết thúc năm tính thuế, tổ chức trả thu nhập vẫn phải tổng hợp
danh sách và thu nhập của những cá nhân chưa đến mức khấu trừ thuế (vào mẫu
ban hành kèm theo văn bản hướng dẫn về quản lý thuế) và nộp cho cơ quan
thuế. Cá nhân làm cam kết phải chịu trách nhiệm về bản cam kết của mình,
trường hợp phát hiện có sự gian lận sẽ bị xử lý theo quy định của Luật quản lý
thuê.
Cá nhân làm cam kết theo hướng dẫn tại điểm này phải đăng ký thuế và
có mã số thuế tại thời điểm cam kết.$md$,$md$TT111-2013_Điều25$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
