insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều25_K2$md$,$md$TT111-2013$md$,$md$Khoản 2$md$,$md$Chứng từ khấu trừ
dẫn tại khoản 1, Điều này phải cấp chứng từ khẩu trừ thuế theo yêu cầu của cá
nhân bị khấu trừ. Trường hợp cá nhân ủy quyền quyết toán thuế thì không cấp
chứng từ khấu trừ.
b.1) Đối với cá nhân không ký hợp đồng lao động hoặc ký hợp đồng lao
động dưới ba (03) tháng: cá nhân có quyên yêu câu tô chức, cá nhân trả thu
nhậi cấp chứng từ khấu trừ cho mỗi lần khấu trừ thuế hoặc cấp một chứng từ
khâu trừ cho nhiều lần khấu trừ thuế trong một kỳ tính thuế.
Ví dụ 15: Ông Q ký hợp đồng dịch vụ với công tyX để chăm sóc cây
cảnh tại khuôn viên của Công ty theo lịch một tháng một lần trong thời gian từ
tháng 9/2013 đến tháng 4/2014. Thu nhập của ông Q được Công ty thanh toán
65
<!-- Page Break -->
# Page 66
theo từng tháng với số tiền là 03 triệu đồng. Như vậy, trường hợp này ông Q có
thể yêu cầu Công ty cấp chứng từ khấu trừ theo từng tháng hoặc cấp một chứng
từ phản ánh số thuế đã khấu trừ từ tháng 9 đến tháng 12/2013 và một chứng từ
cho thời gian từ tháng 01 đến tháng 04/2014. ~
b.2) Đối với cá nhân ký hợp đồng lao động từ ba (03) tháng trở lên: tổ
chức, cá nhân trả thu nhập chỉ câp cho cá nhân một chứng từ khấu trừ trong một
kỳ tính thuế.
Ví dụ 16: Ông R ký hợp đồng lao động dài hạn (từ tháng 9/2013 đến
tháng hết tháng 8/2014) với công ty Y. Trong trường hợp này, nêu ông R thuộc
đối tượng phải quyết toán thuế trực tiếp VỚI CƠ quan thuê và có yêu câu Công ty
cấp chứng từ khẩu trừ thì Công ty sẽ thực hiện cấp 01 chứng từ phản ánh số
thuế đã khẩu trừ từ tháng 9 đến hết tháng 12/2013 và 01 chứng từ cho thời gian
từ tháng 01 đên hết tháng 8/2014.$md$,$md$TT111-2013_Điều25$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
