insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều26$md$,$md$TT111-2013$md$,$md$Điều 26. Khai thuế, quyết toán thuế$md$,$md$Khai thuế, quyết toán thuế
Tổ chức, cá nhân trả thu nhập thuộc diện chịu thuế thu nhập cá nhân và cá
nhân có thu nhập thuộc diện chịu thuế thu nhập cá nhân thực hiện khai thuế và
quyết t toán thuế theo hướng dẫn về thủ tục, hồ Sơ tại văn bản hướng, dẫn về quản
lý thuế. Nguyên tắc khai thuế đối với một số trường hợp cụ thể:$md$,null,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều26_K1$md$,$md$TT111-2013$md$,$md$Khoản 1$md$,$md$Khai thuế đối với tổ chức, cá nhân trả thu nhập chịu thuế thu nhập cá
nhân.
theo tháng hoặc quý. Trường hợp trong tháng hoặc quý, tô chức, cá nhân trả thu
nhập không phát sinh khâu trừ thuê thu nhập cá nhân thì không phải khai thuê.
đầu tiên có phát sinh khấu trừ thuế và áp dụng cho cả năm tính thuế, cụ thể như
sau:
b.1) Tổ chức, cá nhân trả thu nhập phát sinh số thuế khẩu trừ trong tháng
của ít nhất một loại tờ khai thuế thu nhập cá nhân từ 50 triệu đồng trở lên thì
thực hiện khai thuế theo tháng, trừ trường hợp tổ chức, cá nhân trả thu nhập
thuộc điện khai thuế giá trị gia tăng theo quý.
b.2) Tổ chức, cá nhân trả thu nhập không thuộc diện khai thuế theo tháng
theo hướng dẫn nêu trên thì thực hiện khai thuê theo quý.
không phân biệt có phát sinh khấu trừ thuế hay không phát sinh khẩu trừ thuế có
trách nhiệm khai quyết toán thuế thu nhập cá nhân và quyết toán thuế thu nhập
cá nhân thay cho các cá nhân có uỷ quyên.$md$,$md$TT111-2013_Điều26$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
