insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều26_K2$md$,$md$TT111-2013$md$,$md$Khoản 2$md$,$md$Khai thuế đối với cá nhân cư trú có thu nhập từ tiền lương, tiền công,
từ kinh doanh
với cơ quan thuế bao gồm:
66
<!-- Page Break -->
# Page 67
__a.1) Cá nhân cư trú có thu nhập từ tiền lương, tiền công do các tổ chức
quốc tê, Đại sứ quán, Lãnh sự quán tại Việt Nam trả nhưng chưa thực hiện khâu
trừ thuê thực hiện khai thuê trực tiếp với cơ quan thuê theo quý.
a.2) Cá nhân cư trú có thu nhập từ tiền lương, tiền công do các tổ chức, cá
nhân trả từ nước ngoài thực hiện khai thuê trực tiệp với cơ quan thuê theo quý.
tiếp với cơ quan thuế bao gồm:
b.1) Cá nhân, nhóm cá nhân kinh doanh nộp thuế theo phương pháp kê
khai là cá nhân, nhóm cá nhân kinh doanh thực hiện đầy đủ chế độ kế toán, hóa
đơn, chứng từ và cá nhân, nhóm cá nhân kinh doanh chỉ hạch toán được doanh
thu, không hạch toán được chỉ phí thực hiện khai thuế theo quý.
b.2) Cá nhân, nhóm cá nhân kinh doanh nộp thuế theo phương pháp
khoán là cá nhân kinh doanh, nhóm cá nhân kinh doanh không thực hiện đúng
quy định của pháp luật về kế toán, hoá đơn, chứng từ, không xác định được
doanh thu, chi phí và thu nhập chịu thuế thực hiện khai thuế theo năm.
b.3) Cá nhân kinh doanh lưu động (buôn chuyến) khai thuế thu nhập cá
nhân theo từng lân phát sinh.
b.4) Cá nhân kinh doanh sử dụng hóa đơn do cơ quan thuế bán lẻ theo
từng số khai thuế thu nhập cá nhân theo từng lần phát sinh đối với doanh thu
trên hóa đơn.
b.5) Cá nhân không kinh doanh nhưng có phát sinh hoạt động bán hàng,
hóa, cung ứng dịch vụ cân có hóa đơn để giao cho khách hàng khai thuế thu
nhập cá nhân theo từng lần phát sinh.
b.6) Cá nhân, nhóm cá nhân có thu nhập từ cho thuê nhà, quyền sử dụng,
đất, mặt nước, tài sản khác khai thuế theo quý hoặc từng lần phát sinh.
trách nhiệm khai quyết toán thuế nếu có số thuế phải nộp thêm hoặc có số thuế
nộp thừa đề nghị hoàn thuế hoặc bù trừ thuế vào kỳ khai thuế tiếp theo, trừ các
trường hợp sau:
c.1) Cá nhân có số thuế phải nộp nhỏ hơn số thuế đã tạm nộp mà không
có yêu câu hoàn thuế hoặc bù trừ thuế vào kỳ sau.
c.2) Cá nhân, hộ kinh doanh chỉ có một nguồn thu nhập từ kinh doanh đã
thực hiện nộp thuê theo phương pháp khoán.
c.3) Cá nhân, hộ gia đình chỉ có thu nhập từ việc cho thuê nhà, cho thuê
quyền sử dụng đất đã thực hiện nộp thuế theo kê khai tại nơi có nhà, quyền sử
dụng đất cho thuê.
e.4) Cá nhân có thu nhập từ tiền lương, tiền công ký hợp đồng lao động
từ ba (03) tháng trở lên tại một đơn vị mà có thêm thu nhập vãng lai ở các nơi
khác bình quân tháng trong năm không quá 10 triệu đồng đã được đơn vị trả thu
nhập khấu trừ thuế tại nguồn theo tỷ lệ 10% nếu không có yêu cầu thì không
quyết toán thuế đối với phần thu nhập này.
67
<!-- Page Break -->
# Page 68
e.5) Cá nhân có thu nhập từ tiền lương, tiền công ký hợp đồng lao động
từ ba (03) tháng trở lên tại một đơn vị mà có thêm thu nhập từ cho thuê nhà, cho
thuê quyên sử dụng, đất có doanh thu bình quân tháng trong năm không quá 20
triệu đồng đã nộp thuế tại nơi có nhà cho thuê, có quyên sử dụng, đất cho thuê
nếu không có yêu cầu thì không quyết toán thuế đối với phần thu nhập này.
nhân trả thu nhập quyết toán thuế thay trong các trường hợp sau:
d.1) Cá nhân chỉ có thu nhập từ tiền lương, tiền công ký hợp đồng lao
động từ ba (03) tháng trở lên tại một đơn vị và thực tế đang làm việc ở đơn vị
tại thời điểm uỷ quyền quyết toán, kể cả trường hợp không làm việc đủ 12 tháng
trong năm.
d.2) Cá nhân có thu nhập từ tiền lương, tiền công ký hợp đồng lao động
từ ba (03) tháng trở lên và có thêm thu nhập khác theo hướng dẫn tại tiết c.4 và
c.5, điểm c, khoản 2, Điều này.
nhân đối với phần thu nhập từ tiền lương, tiền công mà cá nhân nhận được từ tổ
chức, cá nhân trả thu nhập.
Sau:
e.1) Trường hợp cá nhân cư trú có thu nhập phát sinh tại nước ngoài đã
tính và nộp thuế thu nhập cá nhân theo quy định của nước ngoài thì được trừ số
thuế đã nộp ở nước ngoài. Số thuế được trừ không vượt quá sô thuế phải nộp
tính theo biểu thuế của Việt Nam tính phân. bổ cho phần thu nhập phát sinh tại
nước ngoài. Tỷ lệ phân bổ được xác định bằng tỷ lệ giữa số thu nhập phát sinh
tại nước ngoài và tông thu nhập chịu thuế.
