Ví dụ 17: Ông S là người nước ngoài lần đầu tiên tới Việt Nam làm việc
theo hợp đông có thời hạn từ ngày 01/6/2014 đến 31/5/2016. Năm 2014, ông S
có mặt tại Việt Nam 80 ngày và phát sinh thu nhập từ tiên lương, tiên công là
134 triệu đồng. Năm 2015, ông S có mặt tại Việt Nam trong thời gian từ
01/01/2015 đến hết ngày 31/5/2015 là 110 ngày và phát sinh thu nhập từ tiền
lương, tiền công là 106 triệu đồng; từ ngày 01/6/2015 đến 31/12/2015, ông S có
mặt tại Việt Nam là 105 ngày và phát sinh thu nhập từ tiên lương, tiên công là
122 triệu đông. Ông S không đăng ký giảm trừ gia cảnh cho người phụ thuộc và
không phát sinh các khoản đóng góp bảo hiêm, từ thiện, nhân đạo, khuyên học.
Số thuế thu nhập cá nhân của Ông S phải nộp được xác định như sau:
+ Nếu tính theo năm 2014, Ông S là cá nhân không cư trú, nhưng tính
theo 12 tháng liên tục kế từ ngày 01/6/2014 đên hết ngày 31/5/2015, tông thời
gian ông S có mặt tại Việt Nam là 190 ngày (80 ngày + 110 ngày). Vì vậy, ông,
S là cá nhân cư trú tại Việt Nam.
+ Năm tính thuế thứ nhất (từ ngày 01/6/2014 đến ngày 31/5/2015):
- Tổng thu nhập chịu thuế trong năm tính thuế thứ nhất:
134 triệu đồng + 106 triệu đồng = 240 triệu đồng,
- Giảm trừ gia cảnh: 9 triệu đồng x 12 = 108 triệu đồng
- Thu nhập tính thuế: 240 triệu đồng - 108 triệu đồng = 132 triệu đồng
_- Thuế thu nhập cá nhân phải nộp năm tính thuế thứ nhất: 60 triệu
đồng x 5% + (120 triệu đồng - 60triệu đồng) x 10% + (132 triệu đồng -
120 triệu đông) x 15% = 10,8 triệu đông
+ Năm tính thuế thứ hai (từ 01/01/2015 đến hết ngày 31/12/2015): Ông S
có mặt tại Việt Nam 215 ngày (110 ngày + 105 ngày) là cá nhân cư trú tại Việt
Nam.
- Thu nhập chịu thuế phát sinh trong năm 2015:
106 triệu đồng + 122 triệu đồng = 228 triệu đồng
- Giảm trừ gia cảnh : 9 triệu đồng x 12 = 108 triệu đồng
- Thu nhập tính thuế năm 2015:
228 triệu đồng — 108 triệu đồng = 120 triệu đồng,
- Thuế thu nhập cá nhân phải nộp năm 2015:
