'e.3) Cá nhân cư trú là người nước ngoài kết thúc hợp đồng làm việc tại
Việt Nam thực hiện quyết toán thuế với cơ quan thuế trước khi xuất cảnh.
e.4) Đối với cá nhân cho thuê nhà, quyền sử dụng đất, mặt nước, tài sản
khác thực hiện quyết toán thuế thu nhập cá nhân trừ các trường hợp không phải
quyết toán thuế theo hướng dẫn tại điểm c.3 và c.5, khoản 2, Điều này, cụ thể
như sau:
e.4.1) Trường, hợp cá nhân khai thuế theo quý hoặc khai thuế theo từng
lần phát sinh đối với hợp đồng có kỳ hạn thanh toán từ một năm trở xuống thì
thực hiện quyết toán thuế như đối với cá nhân kinh doanh nộp thuế theo phương
pháp kê khai.
e.4.2) Trường hợp cá nhân khai thuế theo từng lần phát sinh đối với hợp
đồng có kỳ hạn thanh toán trên một năm và nhận tiền trước cho một thời hạn
thuê thì cá nhân lựa chọn một trong hai hình thức hình thức quyết toán thuế như
sau: nếu quyết toán thuế hết vào năm đầu thì doanh thu được xác định theo
doanh thu trả tiền một lần và tính giảm trừ gia cảnh của một năm, các năm sau
không tính lại; nếu quyết toán theo từng năm thì tạm kê khai doanh thu trả tiền
một lần và tính giảm trừ gia cảnh của năm đầu, các năm sau phân bổ lại doanh
thu cho thuê tài sản và tính giảm trừ gia cảnh theo thực tế phát sinh.
e.5) Cá nhân có thu nhập từ đại lý bảo hiểm, đại lý xổ số, bán hàng đa cấp
trực tiếp quyết toán thuế với cơ quan thuế nếu thuộc diện phải quyết toán thuế.
e.6) Cá nhân có thu nhập từ tiền lương, tiền công, từ kinh doanh nhưng
thuộc diện xét giảm thuế do thiên tai, hoá hoạn, tại nạn, bệnh hiểm nghèo trực
tiếp quyết toán thuế với cơ quan thuế.
e.7) Cá nhân, nhóm cá nhân kinh doanh là đối tượng không cư trú nhưng
có địa điểm kinh doanh cố định trên lãnh thổ Việt Nam thực hiện khai thuế,
quyết toán thuế như đối với cá nhân, nhóm cá nhân kinh doanh là đối tượng cư
