insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều26_K3$md$,$md$TT111-2013$md$,$md$Khoản 3$md$,$md$Khai thuế đối với thu nhập từ chuyển nhượng bắt động sản
thuế theo. từng lần phát sinh, kế cả trường, “hợp thuộc đối tượng được miễn thuế.
Khai thuế đối với một số trường hợp cụ thê như sau:
a.1) Trường hợp cá nhân có quyền sử dụng đất, quyền sở hữu nhà nhưng
đem thế chấp, bảo lãnh vay vốn hoặc thanh toán tại tô chức tín dụng, chỉ nhánh
70
<!-- Page Break -->
# Page 71
ngân hàng nước ngoài; đến hết thời hạn trả nợ, cá nhân không có khả năng trả
nợ thì tô chức tín dụng, chỉ nhánh ngân hàng nước ngoài làm thủ tục phát mại,
bán bất động sản đó đồng thời thực hiện khai thuế, nộp thuế thu nhập cá nhân
thay cho cá nhân trước khi thực hiện thanh quyết toán các khoản nợ của cá
nhân.
a.2) Trường hợp cá nhân có quyền sử dụng đất, quyền sở hữu nhà nhưng
đem thế chấp để vay vốn hoặc thanh toán với tô chức cá nhân khác, nay thực
hiện chuyển nhượng toàn bộ (hoặc một phần) bất động sản đó để thanh toán nợ
thì cá nhân có quyên sử dụng, đất, quyền sở hữu nhà phải khai thuế, nộp thuế thu
nhập cá nhân hoặc tổ chức, cá nhân làm thủ tục chuyên nhượng thay phải khai
thuế, nộp thuế thu nhập cá nhân thay cho cá nhân trước khi thanh quyết toán các
khoản nợ.
a.3) Trường hợp bất động sản do cá nhân chuyển nhượng cho tổ chức, cá
nhân khác theo quyết định thi hành án của Toà án thì cá nhân chuyển nhượng
phải khai, nộp thuế hoặc tổ chức, cá nhân tổ chức bán đấu giá phải khai thuê
nộp thuế thu nhập cá nhân thay cho cá nhân chuyển nhượng. Riêng đối với bất
động sản của cá nhân bị cơ quan Nhà nước có thâm quyên thực hiện tịch thu,
bán đấu giá nộp vào Ngân sách Nhà nước theo quy định của pháp luật thì không
phải khai, nộp thuế thu nhập cá nhân.
a.4) Trường hợp chuyển é đổi nhà, đất cho nhau giữa các cá nhân không
thuộc các trường hợp chuyên đổi đất nông nghiệp để sản xuất thuộc đối tượng
được miễn thuế thu nhập cá nhân theo hướng dẫn tại điểm đ, khoản 1, Điều 3
Thông tư này thì từng cá nhân chuyên đổi nhà, đất phải khai thuế, nộp thuế thu
nhập cá nhân.
a.5) Trường hợp khai thay hồ sơ khai thuế thu nhập cá nhân đối với hoạt
động chuyển nhượng bất động sản, thì tổ chức, cá nhân khai thay ghi thêm
“Khai thay” vào phần ( trước cụm từ “Người nộp thuế hoặc Đại diện hợp pháp
của người nộp thuế” đồng thời người khai ký, ghỉ rõ họ tên, nếu là tổ chức khai
thay thì sau khi ký tên phải đóng dấu của tô chức. Trên hồ sơ tính thuế, chứng
từ thu thuế vẫn phải thê hiện đúng người nộp thuế là cá nhân chuyển nhượng
bất động sản.
quyền sử dụng bất động, sản khi đã có chứng từ nộp thuế thu nhập cá nhân hoặc
xác nhận của cơ quan thuế về khoản thu nhập từ việc chuyển nhượng bất động
sản thuộc đối tượng được miễn thuế hoặc tạm thời chưa thu thuế.$md$,$md$TT111-2013_Điều26$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
