tại Sở giao dịch chứng khoán không phải khai trực tiếp với cơ quan thuế mà
Công ty chứng khoán, Ngân hàng thương mại nơi cá nhân mở tài khoản lưu ký,
Công ty quản lý quỹ nơi cá nhân uỷ thác quản lý danh mục đầu tư khai thuế
theo hướng dẫn tại khoản l, Điều 26 Thông tư này.
dịch trên Sở giao dịch chứng khoán:
