trường hợp ‹ chuyển nhượng chứng khoán mà không có chứng từ chứng minh cá
nhân chuyển nhượng chứng khoán đã hoàn thành nghĩa vụ thuế thì doanh
nghiệp nơi cá nhân chuyển nhượng chứng khoán có trách nhiệm khai thuế, nộp
