Trường hợp doanh nghiệp nơi cá nhân chuyển nhượng, chứng khoán khai
thuế thay cho cá nhân thì doanh nghiệp thực hiện khai thay hồ sơ khai thuế thu
nhập cá nhân. Doanh nghiệp khai thay ghi thêm “Khai thay” vào phần trước
cụm từ “Người nộp thuế hoặc Đại diện hợp pháp của người nộp thuế” đồng thời
người khai ký, ghi rõ họ tên và đóng dấu của đoanh nghiệp. Trên hồ sơ tính
