insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều30_K5$md$,$md$TT111-2013$md$,$md$Khoản 5$md$,$md$Đối với trường hợp người sử dụng đất do nhận chuyển nhượng trước
ngày 01 tháng 01 năm 2009 nay nộp hồ sơ hợp lệ xin cấp Giấy chứng nhận
quyền sử dụng đất, quyền sở hữu nhà và tài sản khác gắn liền với đất được cơ
quan Nhà nước có thâm quyền chấp thuận thì chỉ thu một (01) lần thuế thu nhập
cá nhân của lần chuyển nhượng cuối cùng, các lần chuyển nhượng trước đó
không thực hiện truy thu thuế.
Từ ngày 01 tháng 01 năm 2009 thực hiện Luật thuế thu nhập cá nhân, cá
nhân chuyển nhượng bất động sản có hợp đồng công chứng. hoặc không có hợp
đồng chỉ có giấy tờ viết tay đều phải nộp thuế thu nhập cá nhân cho từng, lần
chuyển nhượng.
6: Cá nhân đang được hưởng ưu đãi về thuế thu nhập cá nhân trước ngày
Luật sửa đổi, bổ sung một số điều của Luật Thuế thu nhập cá nhân có hiệu lực
thi hành thì tiếp tục được hướng ưu đãi về thuế thu nhập cá nhân cho thời gian
ưu đãi còn lại.$md$,$md$TT111-2013_Điều30$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
