insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu1$md$,$md$TNCN_109-2025$md$,$md$Điều 1. Phạm vi điều chỉnh$md$,$md$Phạm vi điều chỉnh
Luật này quy định về người nộp thuế, thu nhập chịu thuế, thu nhập được
miễn thuế, giảm thuế và căn cứ tính thuế thu nhập cá nhân.$md$,$md$TNCN_109-2025_ChươngI$md$,1,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu2$md$,$md$TNCN_109-2025$md$,$md$Điều 2. Người nộp thuế$md$,$md$Người nộp thuế
1. Người nộp thuế thu nhập cá nhân là cá nhân cư trú có thu nhập chịu thuế
quy định tại Điều 3 của Luật này phát sinh trong và ngoài lãnh thổ Việt Nam và
cá nhân không cư trú có thu nhập chịu thuế quy định tại Điều 3 của Luật này phát
sinh trong lãnh thổ Việt Nam.
2. Cá nhân cư trú là người đáp ứng một trong các điều kiện sau đây:
a) Có mặt tại Việt Nam từ 183 ngày trở lên tính trong 01 năm dương lịch
hoặc tính theo 12 tháng liên tục kể từ ngày đầu tiên có mặt tại Việt Nam;
b) Có nơi ở thường xuyên tại Việt Nam, bao gồm có nơi ở đăng ký thường
trú hoặc có nhà thuê để ở tại Việt Nam theo hợp đồng thuê có thời hạn.
3. Cá nhân không cư trú là người không đáp ứng điều kiện quy định tại
khoản 2 Điều này.
4. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngI$md$,2,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu3$md$,$md$TNCN_109-2025$md$,$md$Điều 3. Thu nhập chịu thuế$md$,$md$Thu nhập chịu thuế
Thu nhập chịu thuế thu nhập cá nhân gồm các loại thu nhập sau đây, trừ thu
nhập được miễn thuế quy định tại Điều 4 của Luật này:
1. Thu nhập từ kinh doanh, bao gồm:
a) Thu nhập từ hoạt động sản xuất, kinh doanh hàng hoá, dịch vụ;
b) Thu nhập từ hoạt động hành nghề độc lập của cá nhân có giấy phép hoặc
chứng chỉ hành nghề theo quy định của pháp luật;
c) Thu nhập từ hoạt động đại lý, môi giới, hợp tác kinh doanh với tổ chức;
d) Thu nhập từ hoạt động kinh doanh thương mại điện tử, kinh doanh dựa
trên nền tảng số.
2. Thu nhập từ tiền lương, tiền công, bao gồm:
a) Tiền lương, tiền công và các khoản có tính chất tiền lương, tiền công;
b) Tiền thù lao, các khoản lợi ích bằng tiền hoặc không bằng tiền dưới mọi
hình thức;
c) Các khoản phụ cấp, trợ cấp, thu nhập khác trừ các khoản: phụ cấp, trợ
cấp theo quy định của pháp luật về ưu đãi người có công; phụ cấp quốc phòng, an
ninh; phụ cấp độc hại, nguy hiểm đối với ngành, nghề hoặc công việc ở nơi làm
việc có yếu tố độc hại, nguy hiểm; phụ cấp thu hút, phụ cấp khu vực theo quy định
của pháp luật; phụ cấp, trợ cấp, sinh hoạt phí do cơ quan Việt Nam ở nước ngoài
chi trả; trợ cấp khó khăn đột xuất, trợ cấp tai nạn lao động, bệnh nghề nghiệp, trợ
cấp một lần khi sinh con hoặc nhận nuôi con nuôi, trợ cấp do suy giảm khả năng
lao động, trợ cấp hưu trí một lần, trợ cấp tuất hàng tháng và các khoản trợ cấp
khác theo quy định của pháp luật về bảo hiểm xã hội; trợ cấp thôi việc, trợ cấp
mất việc làm; trợ cấp mang tính chất bảo trợ xã hội và các khoản phụ cấp, trợ cấp,
thu nhập khác không mang tính chất tiền lương, tiền công do Chính phủ quy định.
3. Thu nhập từ đầu tư vốn, bao gồm:
a) Tiền lãi cho vay;
b) Lợi tức cổ phần;
c) Thu nhập từ đầu tư vốn dưới các hình thức khác.
4. Thu nhập từ chuyển nhượng vốn, bao gồm:
a) Thu nhập từ chuyển nhượng phần vốn trong các tổ chức kinh tế;
b) Thu nhập từ chuyển nhượng chứng khoán;
c) Thu nhập từ chuyển nhượng vốn dưới các hình thức khác.
5. Thu nhập từ chuyển nhượng bất động sản, bao gồm:
a) Thu nhập từ chuyển nhượng quyền sử dụng đất và tài sản gắn liền với đất;
b) Thu nhập từ chuyển nhượng quyền sở hữu hoặc sử dụng nhà ở;
c) Thu nhập từ chuyển nhượng quyền thuê đất, quyền thuê mặt nước;
d) Các khoản thu nhập khác nhận được từ chuyển nhượng bất động sản
dưới mọi hình thức.
6. Thu nhập từ trúng thưởng, bao gồm:
a) Trúng thưởng xổ số;
b) Trúng thưởng trong các hình thức khuyến mại;
c) Trúng thưởng trong các hình thức đặt cược;
d) Trúng thưởng trong các trò chơi, cuộc thi có thưởng và các hình thức
trúng thưởng khác, trừ trúng thưởng trong ca-si-no.
7. Thu nhập từ tiền bản quyền, bao gồm:
a) Thu nhập từ chuyển giao, chuyển quyền sử dụng các đối tượng của quyền
sở hữu trí tuệ;
b) Thu nhập từ chuyển giao công nghệ.
8. Thu nhập từ nhượng quyền thương mại.
9. Thu nhập từ nhận thừa kế, quà tặng là chứng khoán, phần vốn trong các
tổ chức kinh tế, cơ sở kinh doanh, bất động sản và các tài sản phải đăng ký sở hữu
hoặc đăng ký sử dụng.
10. Thu nhập khác, bao gồm:
a) Thu nhập từ chuyển nhượng tên miền quốc gia Việt Nam “.vn”;
b) Thu nhập từ chuyển nhượng kết quả giảm phát thải khí nhà kính, tín chỉ
các-bon;
c) Thu nhập từ chuyển nhượng biển số xe trúng đấu giá theo quy định của
pháp luật;
d) Thu nhập từ chuyển nhượng tài sản số;
đ) Thu nhập từ chuyển nhượng vàng miếng.
Chính phủ quy định ngưỡng giá trị vàng miếng chịu thuế, thời điểm áp dụng
thu và điều chỉnh thuế suất thuế thu nhập cá nhân đối với chuyển nhượng vàng
miếng phù hợp với lộ trình quản lý thị trường vàng.
11. Chính phủ quy định chi tiết Điều này và việc quy đổi thu nhập chịu thuế
nhận được không bằng tiền, không bằng Đồng Việt Nam.$md$,$md$TNCN_109-2025_ChươngI$md$,3,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu4$md$,$md$TNCN_109-2025$md$,$md$Điều 4. Thu nhập được miễn thuế$md$,$md$Thu nhập được miễn thuế
1. Thu nhập từ chuyển nhượng, nhận thừa kế, quà tặng là bất động sản giữa
vợ với chồng; cha đẻ, mẹ đẻ với con đẻ; cha nuôi, mẹ nuôi với con nuôi; cha
chồng, mẹ chồng với con dâu; cha vợ, mẹ vợ với con rể; ông nội, bà nội với cháu
nội; ông ngoại, bà ngoại với cháu ngoại; anh, chị, em ruột với nhau.
2. Thu nhập từ chuyển nhượng nhà ở, quyền sử dụng đất ở và tài sản gắn
liền với đất ở của cá nhân trong trường hợp cá nhân chỉ có một nhà ở, đất ở duy
nhất tại Việt Nam.
3. Thu nhập từ giá trị quyền sử dụng đất của cá nhân được Nhà nước giao đất.
4. Thu nhập của hộ gia đình, cá nhân trực tiếp sản xuất sản phẩm cây trồng,
rừng trồng, chăn nuôi, thủy sản nuôi trồng, đánh bắt chưa qua chế biến thành các
sản phẩm khác hoặc chỉ qua sơ chế thông thường; sản xuất muối; thu nhập từ lợi
tức cổ phần của thành viên hợp tác xã, liên hiệp hợp tác xã nông nghiệp, cá nhân
là nông dân ký kết hợp đồng với doanh nghiệp tham gia “Cánh đồng lớn”, trồng
rừng sản xuất, nuôi trồng thủy sản.
5. Thu nhập từ chuyển đổi đất nông nghiệp của hộ gia đình, cá nhân được
Nhà nước giao để sản xuất.
6. Thu nhập từ lãi trái phiếu chính phủ, lãi trái phiếu chính quyền địa
phương, lãi tiền gửi tại tổ chức tín dụng, lãi từ hợp đồng bảo hiểm nhân thọ.
7. Thu nhập từ kiều hối.
8. Tiền lương làm việc ban đêm, làm thêm giờ, tiền lương, tiền công trả cho
những ngày không nghỉ phép theo quy định của pháp luật.
9. Tiền lương hưu do Quỹ bảo hiểm xã hội chi trả; thu nhập do quỹ bảo
hiểm hưu trí bổ sung, quỹ hưu trí tự nguyện chi trả.
10. Thu nhập từ học bổng, bao gồm:
a) Học bổng nhận được từ ngân sách nhà nước;
b) Học bổng nhận được từ tổ chức trong nước và ngoài nước theo chương
trình hỗ trợ khuyến học của tổ chức đó.
11. Thu nhập từ bồi thường hợp đồng bảo hiểm nhân thọ, phi nhân thọ, tiền
bồi thường tai nạn lao động, khoản bồi thường nhà nước và các khoản bồi thường
khác theo quy định của pháp luật.
12. Thu nhập nhận được từ các tổ chức và quỹ từ thiện được cơ quan nhà
nước có thẩm quyền cho phép thành lập hoặc công nhận, hoạt động vì mục đích
từ thiện, nhân đạo, không vì mục tiêu lợi nhuận.
13. Thu nhập nhận được từ nguồn viện trợ nước ngoài vì mục đích từ thiện,
nhân đạo dưới hình thức chính phủ và phi chính phủ được cơ quan nhà nước có
thẩm quyền phê duyệt.
14. Thu nhập từ tiền lương, tiền công của thuyền viên là người Việt Nam
làm việc cho các hãng tàu nước ngoài hoặc các hãng tàu Việt Nam vận tải quốc tế.
15. Thu nhập của cá nhân là chủ tàu, cá nhân có quyền sử dụng tàu và cá
nhân làm việc trên tàu từ hoạt động cung cấp hàng hóa, dịch vụ trực tiếp phục vụ
hoạt động khai thác, đánh bắt thủy sản xa bờ.
16. Thu nhập từ chuyển nhượng lần đầu kết quả giảm phát thải khí nhà kính
của cá nhân được công nhận kết quả giảm phát thải khí nhà kính, tín chỉ các-bon
của cá nhân được cấp tín chỉ các-bon; thu nhập từ tiền lãi trái phiếu xanh; thu nhập
từ chuyển nhượng lần đầu trái phiếu xanh sau khi phát hành.
17. Thu nhập từ tiền lương, tiền công từ thực hiện nhiệm vụ khoa học, công
nghệ và đổi mới sáng tạo.
18. Thu nhập từ quyền tác giả của nhiệm vụ khoa học, công nghệ và đổi
mới sáng tạo khi kết quả nhiệm vụ được thương mại hóa theo quy định của pháp
luật về khoa học, công nghệ và đổi mới sáng tạo, pháp luật về sở hữu trí tuệ.
19. Thu nhập của nhà đầu tư cá nhân, chuyên gia từ dự án khởi nghiệp sáng
tạo, sáng lập viên cho doanh nghiệp khởi nghiệp sáng tạo, nhà đầu tư cá nhân góp
vốn vào quỹ đầu tư mạo hiểm.
20. Thu nhập từ tiền lương, tiền công của chuyên gia nước ngoài làm việc
tại chương trình, dự án tài trợ bằng nguồn vốn ODA không hoàn lại, chương trình,
dự án phi chính phủ nước ngoài tại Việt Nam; cá nhân là người Việt Nam làm
việc tại cơ quan đại diện của tổ chức quốc tế thuộc Hệ thống Liên hợp quốc tại
Việt Nam; cá nhân tham gia lực lượng gìn giữ hòa bình của Liên hợp quốc.
21. Thu nhập sau khi đã nộp thuế thu nhập doanh nghiệp của cá nhân là chủ
doanh nghiệp tư nhân, cá nhân là chủ công ty trách nhiệm hữu hạn một thành viên.
22. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngI$md$,4,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu5$md$,$md$TNCN_109-2025$md$,$md$Điều 5. Các trường hợp miễn thuế, giảm thuế khác$md$,$md$Các trường hợp miễn thuế, giảm thuế khác
1. Người nộp thuế gặp khó khăn do thiên tai, dịch bệnh, hoả hoạn, tai nạn,
bệnh hiểm nghèo ảnh hưởng đến khả năng nộp thuế thì được giảm thuế tương ứng
với mức độ thiệt hại nhưng không vượt quá số thuế phải nộp.
2. Miễn thuế thu nhập cá nhân trong thời hạn 05 năm đối với thu nhập từ
tiền lương, tiền công của cá nhân là nhân lực công nghiệp công nghệ số chất lượng
cao thuộc các trường hợp sau:
a) Thu nhập từ dự án hoạt động công nghiệp công nghệ số trong khu công
nghệ số tập trung;
b) Thu nhập từ dự án nghiên cứu và phát triển, sản xuất sản phẩm công
nghệ số trọng điểm, chip bán dẫn, hệ thống trí tuệ nhân tạo;
c) Thu nhập từ các hoạt động đào tạo nhân lực công nghiệp công nghệ số.
3. Miễn thuế thu nhập cá nhân trong thời hạn 05 năm đối với thu nhập từ
tiền lương, tiền công của cá nhân là nhân lực công nghệ cao thực hiện hoạt động
nghiên cứu và phát triển công nghệ cao hoặc công nghệ chiến lược thuộc Danh
mục công nghệ cao được ưu tiên đầu tư phát triển hoặc Danh mục công nghệ
chiến lược, Danh mục sản phẩm công nghệ chiến lược theo quy định của pháp
luật về công nghệ cao.
4. Miễn thuế thu nhập cá nhân đối với chuyển nhượng chứng chỉ quỹ mở
thành lập theo quy định của pháp luật về chứng khoán được nắm giữ từ 02 năm
trở lên kể từ ngày mua.
5. Giảm 50% thuế thu nhập cá nhân đối với lợi tức của nhà đầu tư cá nhân
được chia từ quỹ đầu tư chứng khoán, quỹ đầu tư bất động sản thành lập theo quy
định của Luật Chứng khoán trong thời hạn do Chính phủ quy định.
6. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngI$md$,5,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu6$md$,$md$TNCN_109-2025$md$,$md$Điều 6. Quản lý thuế đối với thuế thu nhập cá nhân$md$,$md$Quản lý thuế đối với thuế thu nhập cá nhân
Căn cứ quy định của Luật này, Chính phủ quy định về kỳ tính thuế theo
năm đối với thu nhập từ kinh doanh, thu nhập từ tiền lương, tiền công của cá
nhân cư trú; kỳ tính thuế theo từng lần phát sinh đối với các khoản thu nhập
khác của cá nhân cư trú và cá nhân không cư trú; thời điểm xác định thu nhập
tính thuế; quyết toán thuế; hoàn thuế đối với trường hợp cá nhân có số thuế đã
nộp lớn hơn số thuế phải nộp hoặc chưa đến mức phải nộp; trách nhiệm khấu
trừ, khai thay, nộp thay cho người nộp thuế phù hợp với quy định của Luật
Quản lý thuế.
CĂN CỨ TÍNH THUẾ ĐỐI VỚI CÁ NHÂN CƯ TRÚ$md$,$md$TNCN_109-2025_ChươngI$md$,6,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu7$md$,$md$TNCN_109-2025$md$,$md$Điều 7. Thuế thu nhập cá nhân đối với thu nhập từ kinh doanh$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ kinh doanh
1. Cá nhân cư trú có hoạt động sản xuất, kinh doanh có mức doanh thu năm
từ 500 triệu đồng trở xuống không phải nộp thuế thu nhập cá nhân. Chính phủ trình
Ủy ban Thường vụ Quốc hội điều chỉnh mức doanh thu không phải nộp thuế thu
nhập cá nhân phù hợp với tình hình kinh tế - xã hội trong từng thời kỳ.
2. Thuế thu nhập cá nhân đối với thu nhập từ kinh doanh của cá nhân cư
trú có doanh thu năm trên mức quy định tại khoản 1 Điều này được xác định bằng
thu nhập tính thuế nhân (x) với thuế suất. Trong đó:
a) Thu nhập tính thuế được xác định bằng doanh thu của hàng hóa, dịch
vụ bán ra trừ (-) đi chi phí liên quan đến hoạt động sản xuất, kinh doanh trong
kỳ tính thuế;
b) Cá nhân kinh doanh có doanh thu năm trên mức quy định tại khoản 1
Điều này đến 03 tỷ đồng: thuế suất 15%;
c) Cá nhân kinh doanh có doanh thu năm trên 03 tỷ đồng đến 50 tỷ đồng:
thuế suất 17%;
d) Cá nhân kinh doanh có doanh thu năm trên 50 tỷ đồng: thuế suất 20%.
Thu nhập từ cho thuê bất động sản quy định tại khoản 4 Điều này không áp
dụng cách tính thuế quy định tại khoản này.
3. Cá nhân kinh doanh có doanh thu năm trên mức quy định tại khoản 1
Điều này đến 03 tỷ đồng được lựa chọn nộp thuế theo quy định tại điểm a và điểm
b khoản 2 Điều này hoặc nộp thuế theo thuế suất nhân (x) với doanh thu tính thuế.
Doanh thu tính thuế và thuế suất được xác định như sau:
a) Doanh thu tính thuế được xác định bằng phần doanh thu vượt trên mức
quy định tại khoản 1 Điều này;
b) Phân phối, cung cấp hàng hoá: thuế suất 0,5%;
c) Dịch vụ, xây dựng không bao thầu nguyên vật liệu: thuế suất 2%. Riêng
hoạt động cho thuê tài sản, đại lý bảo hiểm, đại lý xổ số, đại lý bán hàng đa cấp:
thuế suất 5%;
d) Sản xuất, vận tải, dịch vụ có gắn với hàng hoá, xây dựng có bao thầu
nguyên vật liệu: thuế suất 1,5%;
đ) Hoạt động cung cấp sản phẩm và dịch vụ nội dung thông tin số về giải
trí, trò chơi điện tử, phim số, ảnh số, nhạc số, quảng cáo số: thuế suất 5%;
e) Hoạt động kinh doanh khác: thuế suất 1%.
4. Cá nhân cho thuê bất động sản, trừ hoạt động kinh doanh lưu trú, nộp
thuế thu nhập cá nhân được xác định bằng phần doanh thu vượt trên mức quy định
tại khoản 1 Điều này nhân (x) với thuế suất 5%.
5. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngII$md$,7,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu8$md$,$md$TNCN_109-2025$md$,$md$Điều 8. Thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công
1. Thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công của cá
nhân cư trú được xác định bằng thu nhập tính thuế quy định tại khoản 2 Điều này,
không phân biệt nơi trả thu nhập, nhân (x) với thuế suất tại Biểu thuế lũy tiến từng
phần quy định tại Điều 9 của Luật này.
2. Thu nhập tính thuế đối với thu nhập từ tiền lương, tiền công là tổng thu
nhập chịu thuế quy định tại khoản 2 Điều 3 của Luật này mà người nộp thuế nhận
được trong kỳ tính thuế, trừ (-) đi các khoản đóng góp bảo hiểm xã hội, bảo hiểm
y tế, bảo hiểm thất nghiệp, bảo hiểm trách nhiệm nghề nghiệp đối với một số
ngành, nghề phải tham gia bảo hiểm bắt buộc, khoản đóng góp tham gia bảo hiểm
hưu trí bổ sung theo quy định của Luật Bảo hiểm xã hội, mua bảo hiểm hưu trí tự
nguyện, bảo hiểm nhân thọ không vượt quá mức do Chính phủ quy định và các
khoản giảm trừ quy định tại Điều 10 và Điều 11 của Luật này.
3. Thời điểm xác định thu nhập tính thuế từ tiền lương, tiền công là thời
điểm tổ chức, cá nhân trả thu nhập cho người nộp thuế hoặc thời điểm người nộp
thuế nhận được thu nhập.$md$,$md$TNCN_109-2025_ChươngII$md$,8,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu9$md$,$md$TNCN_109-2025$md$,$md$Điều 9. Biểu thuế luỹ tiến từng phần$md$,$md$Biểu thuế luỹ tiến từng phần
1. Biểu thuế luỹ tiến từng phần áp dụng đối với thu nhập tính thuế quy định
tại khoản 2 Điều 8 của Luật này.
2. Biểu thuế luỹ tiến từng phần được quy định như sau:
Bậc
thuế
Phần thu nhập tính
thuế/năm
(triệu đồng)
Đến 120
Trên 120 đến 360
Trên 360 đến 720
Trên 720 đến 1.200
Trên 1.200
Phần thu nhập tính
thuế/tháng
(triệu đồng)
Đến 10
Trên 10 đến 30
Trên 30 đến 60
Trên 60 đến 100
Trên 100
Thuế suất
(%)$md$,$md$TNCN_109-2025_ChươngII$md$,9,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu10$md$,$md$TNCN_109-2025$md$,$md$Điều 10. Giảm trừ gia cảnh$md$,$md$Giảm trừ gia cảnh
1. Giảm trừ gia cảnh là số tiền được trừ vào thu nhập chịu thuế trước khi
tính thuế đối với thu nhập từ tiền lương, tiền công của người nộp thuế là cá nhân
cư trú. Giảm trừ gia cảnh gồm:
a) Mức giảm trừ đối với người nộp thuế là 15,5 triệu đồng/tháng (186 triệu
đồng/năm);
b) Mức giảm trừ đối với mỗi người phụ thuộc là 6,2 triệu đồng/tháng.
2. Căn cứ biến động của giá cả, thu nhập, Chính phủ trình Ủy ban Thường
vụ Quốc hội quy định mức giảm trừ gia cảnh quy định tại khoản 1 Điều này phù
hợp với tình hình kinh tế - xã hội trong từng thời kỳ.
3. Việc xác định mức giảm trừ gia cảnh đối với người phụ thuộc thực hiện
theo nguyên tắc mỗi người phụ thuộc chỉ được tính giảm trừ một lần vào một
người nộp thuế.
4. Người phụ thuộc là người mà người nộp thuế có trách nhiệm nuôi dưỡng,
bao gồm:
a) Con chưa thành niên; con là người mất năng lực hành vi dân sự, người
khuyết tật, không có khả năng lao động;
b) Các cá nhân không có thu nhập hoặc có thu nhập không vượt quá mức do
Bộ trưởng Bộ Tài chính quy định, bao gồm con thành niên đang học đại học, cao
đẳng, trung học chuyên nghiệp hoặc học nghề; vợ hoặc chồng không có khả năng
lao động; bố, mẹ đã hết tuổi lao động hoặc không có khả năng lao động; những người
khác không nơi nương tựa mà người nộp thuế phải trực tiếp nuôi dưỡng.$md$,$md$TNCN_109-2025_ChươngII$md$,10,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu11$md$,$md$TNCN_109-2025$md$,$md$Điều 11. Giảm trừ đối với các khoản đóng góp từ thiện, nhân đạo và$md$,$md$Giảm trừ đối với các khoản đóng góp từ thiện, nhân đạo và
các khoản giảm trừ khác
Cá nhân cư trú được giảm trừ vào thu nhập chịu thuế trước khi tính thuế
đối với thu nhập từ tiền lương, tiền công các khoản sau đây:
1. Khoản đóng góp từ thiện, nhân đạo, bao gồm:
a) Khoản đóng góp vào tổ chức, cơ sở chăm sóc, nuôi dưỡng trẻ em có hoàn
cảnh đặc biệt khó khăn, người khuyết tật, người già không nơi nương tựa;
b) Khoản đóng góp vào quỹ từ thiện, quỹ nhân đạo, quỹ khuyến học;
c) Khoản đóng góp vào các tổ chức có chức năng huy động tài trợ được
thành lập và hoạt động theo quy định của pháp luật.
Tổ chức, cơ sở và các quỹ quy định tại khoản này phải được cơ quan nhà
nước có thẩm quyền cho phép thành lập hoặc công nhận, hoạt động vì mục đích
từ thiện, nhân đạo, khuyến học, không vì mục tiêu lợi nhuận.
2. Khoản chi cho y tế, giáo dục - đào tạo của người nộp thuế, người phụ
thuộc của người nộp thuế được giảm trừ vào thu nhập trước khi tính thuế theo
mức do Chính phủ quy định.
3. Các khoản chi quy định tại Điều này phải đáp ứng các điều kiện về hóa đơn,
chứng từ theo quy định của pháp luật và không được chi trả từ các nguồn khác.
4. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngII$md$,11,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu12$md$,$md$TNCN_109-2025$md$,$md$Điều 12. Thuế thu nhập cá nhân đối với thu nhập từ đầu tư vốn$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ đầu tư vốn
1. Thuế đối với thu nhập từ đầu tư vốn của cá nhân cư trú được xác định
bằng thu nhập tính thuế nhân (x) với thuế suất 5%.
2. Thu nhập tính thuế từ đầu tư vốn là tổng số các khoản thu nhập chịu thuế
từ đầu tư vốn quy định tại khoản 3 Điều 3 của Luật này mà người nộp thuế nhận
được theo từng lần phát sinh.
3. Thời điểm xác định thu nhập tính thuế từ đầu tư vốn là thời điểm tổ chức,
cá nhân trả thu nhập cho người nộp thuế hoặc thời điểm người nộp thuế nhận được
thu nhập.
4. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngII$md$,12,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu13$md$,$md$TNCN_109-2025$md$,$md$Điều 13. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng vốn$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng vốn
1. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng vốn của cá
nhân cư trú được xác định bằng thu nhập tính thuế nhân (x) với thuế suất 20%
theo từng lần chuyển nhượng. Trong đó, thu nhập tính thuế từ chuyển nhượng vốn
được xác định bằng giá chuyển nhượng trừ (-) đi giá mua và các khoản chi phí
hợp lý liên quan đến việc tạo ra thu nhập từ chuyển nhượng vốn.
Trường hợp không xác định giá mua và các chi phí liên quan đến việc
chuyển nhượng vốn thì thuế thu nhập cá nhân được xác định bằng giá chuyển
nhượng nhân (x) với thuế suất 2%.
2. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng chứng khoán
được xác định bằng giá chuyển nhượng nhân (x) với thuế suất 0,1% theo từng lần
chuyển nhượng.
3. Thời điểm xác định thu nhập tính thuế từ chuyển nhượng vốn là thời
điểm giao dịch hoàn thành theo quy định của pháp luật.
4. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngII$md$,13,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu14$md$,$md$TNCN_109-2025$md$,$md$Điều 14. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng
bất động sản
1. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng bất động sản của
cá nhân cư trú được xác định bằng giá chuyển nhượng nhân (x) với thuế suất 2%.
2. Thời điểm xác định thu nhập tính thuế từ chuyển nhượng bất động sản là
thời điểm hợp đồng chuyển nhượng có hiệu lực theo quy định của pháp luật hoặc
thời điểm đăng ký quyền sử dụng, quyền sở hữu bất động sản.
3. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngII$md$,14,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu15$md$,$md$TNCN_109-2025$md$,$md$Điều 15. Thuế thu nhập cá nhân đối với thu nhập từ trúng thưởng$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ trúng thưởng
1. Thuế thu nhập cá nhân đối với thu nhập từ trúng thưởng của cá nhân cư
trú được xác định bằng thu nhập tính thuế nhân (x) với thuế suất 10%.
2. Thu nhập tính thuế từ trúng thưởng là phần giá trị giải thưởng vượt trên
20 triệu đồng mà người nộp thuế nhận được theo từng lần trúng thưởng.
3. Thời điểm xác định thu nhập tính thuế từ trúng thưởng là thời điểm tổ
chức, cá nhân trả thu nhập cho người nộp thuế.$md$,$md$TNCN_109-2025_ChươngII$md$,15,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu16$md$,$md$TNCN_109-2025$md$,$md$Điều 16. Thuế thu nhập cá nhân đối với thu nhập từ tiền bản quyền$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ tiền bản quyền
1. Thuế thu nhập cá nhân đối với thu nhập từ tiền bản quyền của cá nhân
cư trú được tính bằng thu nhập tính thuế nhân (x) với thuế suất 5%.
2. Thu nhập tính thuế từ tiền bản quyền là phần thu nhập vượt trên 20 triệu
đồng mà người nộp thuế nhận được khi chuyển giao, chuyển quyền sử dụng các
đối tượng của quyền sở hữu trí tuệ, chuyển giao công nghệ theo từng hợp đồng.
3. Thời điểm xác định thu nhập tính thuế từ tiền bản quyền là thời điểm tổ
chức, cá nhân trả thu nhập cho người nộp thuế.$md$,$md$TNCN_109-2025_ChươngII$md$,16,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu17$md$,$md$TNCN_109-2025$md$,$md$Điều 17. Thuế thu nhập cá nhân đối với thu nhập từ nhượng quyền$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ nhượng quyền
thương mại
1. Thuế thu nhập cá nhân đối với thu nhập từ nhượng quyền thương mại
của cá nhân cư trú được tính bằng thu nhập tính thuế nhân (x) với thuế suất 5%.
2. Thu nhập tính thuế từ nhượng quyền thương mại là phần thu nhập vượt
trên 20 triệu đồng mà người nộp thuế nhận được theo từng hợp đồng nhượng
quyền thương mại.
3. Thời điểm xác định thu nhập tính thuế từ nhượng quyền thương mại là
thời điểm tổ chức, cá nhân trả thu nhập cho người nộp thuế.$md$,$md$TNCN_109-2025_ChươngII$md$,17,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu18$md$,$md$TNCN_109-2025$md$,$md$Điều 18. Thuế thu nhập cá nhân đối với thu nhập từ nhận thừa kế, quà$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ nhận thừa kế, quà
tặng
1. Thuế thu nhập cá nhân đối với thu nhập từ nhận thừa kế, quà tặng của cá
nhân cư trú được xác định bằng thu nhập tính thuế nhân (x) với thuế suất 10%.
2. Thu nhập tính thuế từ nhận thừa kế, quà tặng là phần giá trị tài sản thừa
kế, quà tặng vượt trên 20 triệu đồng mà người nộp thuế nhận được theo từng lần
phát sinh.
3. Thời điểm xác định thu nhập tính thuế được quy định như sau:
a) Đối với thu nhập từ nhận thừa kế là thời điểm người nộp thuế nhận được
thừa kế;
b) Đối với thu nhập từ nhận quà tặng là thời điểm tổ chức, cá nhân tặng cho
người nộp thuế hoặc thời điểm người nộp thuế nhận được thu nhập.
4. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngII$md$,18,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu19$md$,$md$TNCN_109-2025$md$,$md$Điều 19. Thuế thu nhập cá nhân đối với thu nhập khác$md$,$md$Thuế thu nhập cá nhân đối với thu nhập khác
1. Thuế thu nhập cá nhân đối với thu nhập khác của cá nhân cư trú quy định
tại các điểm a, b và c khoản 10 Điều 3 của Luật này được xác định bằng thu nhập
tính thuế nhân (x) với thuế suất 5%. Trong đó, thu nhập tính thuế là phần thu nhập
vượt trên 20 triệu đồng mà người nộp thuế nhận được theo từng lần phát sinh.
2. Thuế thu nhập cá nhân đối với thu nhập khác của cá nhân cư trú quy định
tại điểm d và điểm đ khoản 10 Điều 3 của Luật này được xác định bằng giá chuyển
nhượng nhân (x) với thuế suất 0,1%.
3. Thời điểm xác định thu nhập tính thuế là thời điểm tổ chức, cá nhân chi trả
thu nhập cho người nộp thuế hoặc thời điểm người nộp thuế nhận được thu nhập.
4. Chính phủ quy định chi tiết Điều này.
CĂN CỨ TÍNH THUẾ ĐỐI VỚI CÁ NHÂN KHÔNG CƯ TRÚ$md$,$md$TNCN_109-2025_ChươngII$md$,19,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu20$md$,$md$TNCN_109-2025$md$,$md$Điều 20. Thuế thu nhập cá nhân đối với thu nhập từ kinh doanh$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ kinh doanh
1. Thuế thu nhập cá nhân đối với thu nhập từ kinh doanh của cá nhân không
cư trú được xác định bằng doanh thu từ hoạt động kinh doanh quy định tại khoản
2 Điều này nhân (x) với thuế suất quy định tại khoản 3 Điều này.
2. Doanh thu là toàn bộ tiền bán hàng, tiền gia công, tiền cung ứng dịch vụ
kể cả trợ giá, phụ thu, phụ trội mà cá nhân được hưởng, không phân biệt đã thu
được tiền hay chưa thu được tiền, bao gồm cả chi phí do bên mua hàng hoá, dịch
vụ trả thay cho cá nhân không cư trú mà không được hoàn trả.
Trường hợp thoả thuận hợp đồng không bao gồm thuế thu nhập cá nhân thì
doanh thu tính thuế phải quy đổi là toàn bộ số tiền mà cá nhân không cư trú nhận
được dưới bất kỳ hình thức nào từ việc cung cấp hàng hoá, dịch vụ tại Việt Nam
không phụ thuộc vào địa điểm tiến hành các hoạt động kinh doanh.
3. Thuế suất:
a) Phân phối, cung cấp hàng hoá: 1%;
b) Dịch vụ, xây dựng không bao thầu nguyên vật liệu: 5%;
c) Sản xuất, vận tải, dịch vụ có gắn với hàng hoá, xây dựng có bao thầu
nguyên vật liệu: 2%;
d) Hoạt động cung cấp sản phẩm và dịch vụ nội dung thông tin số về giải
trí, trò chơi điện tử, phim số, ảnh số, nhạc số, quảng cáo: 5%;
đ) Hoạt động kinh doanh khác: 2%.$md$,$md$TNCN_109-2025_ChươngIII$md$,20,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu21$md$,$md$TNCN_109-2025$md$,$md$Điều 21. Thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công
Thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công của cá nhân
không cư trú được xác định bằng tổng số tiền lương, tiền công mà cá nhân không
cư trú nhận được do thực hiện công việc tại Việt Nam nhân (x) với thuế suất 20%,
không phân biệt nơi trả thu nhập.$md$,$md$TNCN_109-2025_ChươngIII$md$,21,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu22$md$,$md$TNCN_109-2025$md$,$md$Điều 22. Thuế thu nhập cá nhân đối với thu nhập từ đầu tư vốn$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ đầu tư vốn
Thuế thu nhập cá nhân đối với thu nhập từ đầu tư vốn của cá nhân không
cư trú được xác định bằng tổng số thu nhập mà cá nhân không cư trú nhận được
từ việc đầu tư vốn vào tổ chức, cá nhân tại Việt Nam nhân (x) với thuế suất 5%.$md$,$md$TNCN_109-2025_ChươngIII$md$,22,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu23$md$,$md$TNCN_109-2025$md$,$md$Điều 23. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng vốn$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng vốn
1. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng vốn của cá
nhân không cư trú được xác định bằng thu nhập tính thuế nhân (x) với thuế suất
20% theo từng lần phát sinh, không phân biệt việc chuyển nhượng được thực hiện
tại Việt Nam hay tại nước ngoài. Trong đó, thu nhập tính thuế từ chuyển nhượng
vốn được xác định bằng giá chuyển nhượng trừ (-) đi giá mua và các khoản chi
phí hợp lý liên quan đến việc tạo ra thu nhập từ chuyển nhượng phần vốn tại tổ
chức, cá nhân Việt Nam.
Trường hợp không xác định được giá mua và các chi phí liên quan đến việc
chuyển nhượng vốn thì thuế thu nhập cá nhân được xác định bằng giá chuyển
nhượng phần vốn tại tổ chức, cá nhân Việt Nam nhân (x) với thuế suất 2%.
2. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng chứng khoán
của cá nhân không cư trú được xác định bằng giá chuyển nhượng nhân (x) với
thuế suất 0,1%.
3. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngIII$md$,23,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu24$md$,$md$TNCN_109-2025$md$,$md$Điều 24. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng
bất động sản
1. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng bất động sản
của cá nhân không cư trú được xác định bằng giá chuyển nhượng nhân (x) với
thuế suất 2%.
2. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngIII$md$,24,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu25$md$,$md$TNCN_109-2025$md$,$md$Điều 25. Thuế thu nhập cá nhân đối với thu nhập từ tiền bản quyền,$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ tiền bản quyền,
nhượng quyền thương mại
1. Thuế thu nhập cá nhân đối với thu nhập từ tiền bản quyền của cá nhân
không cư trú được xác định bằng phần thu nhập vượt trên 20 triệu đồng theo từng
hợp đồng chuyển giao, chuyển quyền sử dụng các đối tượng của quyền sở hữu trí
tuệ, chuyển giao công nghệ tại Việt Nam nhân (x) với thuế suất 5%.
2. Thuế thu nhập cá nhân đối với thu nhập từ nhượng quyền thương mại
của cá nhân không cư trú được xác định bằng phần thu nhập vượt trên 20 triệu
đồng theo từng hợp đồng nhượng quyền thương mại tại Việt Nam nhân (x) với
thuế suất 5%.$md$,$md$TNCN_109-2025_ChươngIII$md$,25,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu26$md$,$md$TNCN_109-2025$md$,$md$Điều 26. Thuế thu nhập cá nhân đối với thu nhập từ trúng thưởng,$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ trúng thưởng,
nhận thừa kế, quà tặng
Thuế thu nhập cá nhân đối với thu nhập từ trúng thưởng, nhận thừa kế, quà
tặng của cá nhân không cư trú được xác định bằng phần giá trị vượt trên 20 triệu
đồng theo từng lần trúng thưởng, nhận thừa kế, quà tặng tại Việt Nam nhân (x)
với thuế suất 10%.$md$,$md$TNCN_109-2025_ChươngIII$md$,26,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu27$md$,$md$TNCN_109-2025$md$,$md$Điều 27. Thuế thu nhập cá nhân đối với thu nhập khác$md$,$md$Thuế thu nhập cá nhân đối với thu nhập khác
1. Thuế thu nhập cá nhân đối với thu nhập khác của cá nhân không cư trú
quy định tại các điểm a, b và c khoản 10 Điều 3 của Luật này được xác định
bằng thu nhập tính thuế nhân (x) với thuế suất 5%. Thu nhập tính thuế là phần
thu nhập vượt trên 20 triệu đồng mà người nộp thuế nhận được theo từng lần
phát sinh.
2. Thuế thu nhập cá nhân đối với thu nhập khác của cá nhân không cư trú
quy định tại điểm d và điểm đ khoản 10 Điều 3 của Luật này được xác định bằng
giá chuyển nhượng nhân (x) với thuế suất 0,1%.
3. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngIII$md$,27,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu28$md$,$md$TNCN_109-2025$md$,$md$Điều 28. Thời điểm xác định thu nhập tính thuế$md$,$md$Thời điểm xác định thu nhập tính thuế
1. Thời điểm xác định thu nhập tính thuế đối với thu nhập quy định tại Điều
20 của Luật này là thời điểm cá nhân không cư trú nhận được thu nhập hoặc thời
điểm xuất hoá đơn bán hàng hoá, cung cấp dịch vụ.
2. Thời điểm xác định thu nhập tính thuế đối với thu nhập quy định tại các
điều 21, 22, 25, 26 và 27 của Luật này là thời điểm tổ chức, cá nhân tại Việt Nam
trả thu nhập cho cá nhân không cư trú hoặc thời điểm cá nhân không cư trú nhận
được thu nhập.
3. Thời điểm xác định thu nhập tính thuế đối với thu nhập quy định tại Điều
23 của Luật này là thời điểm giao dịch hoàn thành theo quy định của pháp luật.
4. Thời điểm xác định thu nhập tính thuế đối với thu nhập quy định tại Điều
24 của Luật này là thời điểm hợp đồng chuyển nhượng có hiệu lực theo quy định
của pháp luật hoặc thời điểm đăng ký quyền sử dụng, quyền sở hữu bất động sản.
5. Chính phủ quy định chi tiết Điều này.
ĐIỀU KHOẢN THI HÀNH$md$,$md$TNCN_109-2025_ChươngIII$md$,28,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu29$md$,$md$TNCN_109-2025$md$,$md$Điều 29. Hiệu lực thi hành$md$,$md$Hiệu lực thi hành
1. Luật này có hiệu lực thi hành từ ngày 01 tháng 7 năm 2026, trừ trường
hợp quy định tại khoản 2 Điều này.
2. Các quy định liên quan đến thu nhập từ kinh doanh, từ tiền lương, tiền
công của cá nhân cư trú áp dụng từ kỳ tính thuế năm 2026.
3. Luật Thuế thu nhập cá nhân số 04/2007/QH12 đã được sửa đổi, bổ sung
một số điều theo Luật số 26/2012/QH13, Luật số 71/2014/QH13, Luật số
31/2024/QH15, Luật số 43/2024/QH15, Luật số 48/2024/QH15, Luật số
56/2025/QH15, Luật số 71/2025/QH15 và Luật số 93/2025/QH15 hết hiệu lực kể từ
ngày Luật này có hiệu lực thi hành; riêng các quy định liên quan đến thu nhập từ
kinh doanh, từ tiền lương, tiền công của cá nhân cư trú hết hiệu lực thi hành từ kỳ
tính thuế năm 2026.
4. Trường hợp có quy định khác nhau về ưu đãi thuế giữa Luật này với
Luật Thủ đô, nghị quyết của Quốc hội và giải pháp quy định tại điểm h khoản 8
Điều 10 của Luật Tổ chức Chính phủ thì áp dụng theo quy định của Luật Thủ đô,
nghị quyết của Quốc hội và giải pháp quy định tại điểm h khoản 8 Điều 10 của
Luật Tổ chức Chính phủ. Trường hợp quy định tại Luật này ưu đãi hơn thì người
nộp thuế được lựa chọn áp dụng mức ưu đãi có lợi nhất.
Luật này được Quốc hội nước Cộng hòa xã hội chủ nghĩa Việt Nam khóa XV,
Kỳ họp thứ 10 thông qua ngày 10 tháng 12 năm 2025.
CHỦ TỊCH QUỐC HỘI
Trần Thanh Mẫn$md$,$md$TNCN_109-2025_ChươngIV$md$,29,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu1$md$,$md$GTGT_48-2024$md$,$md$Điều 1. Phạm vi điều chỉnh$md$,$md$Phạm vi điều chỉnh
Luật này quy định về đối tượng chịu thuế, đối tượng không chịu thuế, người
nộp thuế, căn cứ và phương pháp tính thuế, khấu trừ và hoàn thuế giá trị gia tăng.$md$,$md$GTGT_48-2024_ChươngI$md$,1,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu2$md$,$md$GTGT_48-2024$md$,$md$Điều 2. Thuế giá trị gia tăng$md$,$md$Thuế giá trị gia tăng
Thuế giá trị gia tăng là thuế tính trên giá trị tăng thêm của hàng hóa, dịch vụ
phát sinh trong quá trình từ sản xuất, lưu thông đến tiêu dùng.$md$,$md$GTGT_48-2024_ChươngI$md$,2,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu3$md$,$md$GTGT_48-2024$md$,$md$Điều 3. Đối tượng chịu thuế$md$,$md$Đối tượng chịu thuế
Hàng hóa, dịch vụ sử dụng cho sản xuất, kinh doanh và tiêu dùng ở Việt Nam
là đối tượng chịu thuế giá trị gia tăng, trừ các đối tượng quy định tại Điều 5 của
Luật này.$md$,$md$GTGT_48-2024_ChươngI$md$,3,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu4$md$,$md$GTGT_48-2024$md$,$md$Điều 4. Người nộp thuế$md$,$md$Người nộp thuế
1. Tổ chức, hộ, cá nhân sản xuất, kinh doanh hàng hóa, dịch vụ chịu thuế giá
trị gia tăng (sau đây gọi là cơ sở kinh doanh).
2. Tổ chức, cá nhân nhập khẩu hàng hóa chịu thuế giá trị gia tăng (sau đây gọi
là người nhập khẩu).
3. Tổ chức, cá nhân sản xuất, kinh doanh tại Việt Nam mua dịch vụ (kể cả
trường hợp mua dịch vụ gắn với hàng hóa) của tổ chức nước ngoài không có cơ sở
thường trú tại Việt Nam, cá nhân ở nước ngoài là đối tượng không cư trú tại
Việt Nam, trừ trường hợp quy định tại khoản 4 và khoản 5 Điều này; tổ chức sản
xuất, kinh doanh tại Việt Nam mua hàng hóa, dịch vụ để tiến hành hoạt động tìm
kiếm thăm dò, phát triển mỏ dầu khí và khai thác dầu khí của tổ chức nước ngoài
không có cơ sở thường trú tại Việt Nam, cá nhân ở nước ngoài là đối tượng không
cư trú tại Việt Nam.
4. Nhà cung cấp nước ngoài không có cơ sở thường trú tại Việt Nam có hoạt
động kinh doanh thương mại điện tử, kinh doanh dựa trên nền tảng số với tổ chức,
cá nhân tại Việt Nam (sau đây gọi là nhà cung cấp nước ngoài); tổ chức là nhà
quản lý nền tảng số nước ngoài thực hiện khấu trừ, nộp thay nghĩa vụ thuế phải
nộp của nhà cung cấp nước ngoài; tổ chức kinh doanh tại Việt Nam áp dụng
phương pháp tính thuế giá trị gia tăng là phương pháp khấu trừ thuế mua dịch vụ
của nhà cung cấp nước ngoài không có cơ sở thường trú tại Việt Nam thông qua
kênh thương mại điện tử hoặc các nền tảng số thực hiện khấu trừ, nộp thay nghĩa
vụ thuế phải nộp của nhà cung cấp nước ngoài.
5. Tổ chức là nhà quản lý sàn giao dịch thương mại điện tử, nhà quản lý nền
tảng số có chức năng thanh toán thực hiện khấu trừ, nộp thuế thay, kê khai số thuế
đã khấu trừ cho hộ kinh doanh, cá nhân kinh doanh trên sàn thương mại điện tử,
nền tảng số.
6. Chính phủ quy định chi tiết các khoản 1, 4 và 5 Điều này; quy định về người
nộp thuế trong trường hợp nhà cung cấp nước ngoài cung cấp dịch vụ cho người
mua là tổ chức kinh doanh tại Việt Nam áp dụng phương pháp khấu trừ thuế quy
định tại khoản 4 Điều này.$md$,$md$GTGT_48-2024_ChươngI$md$,4,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu5$md$,$md$GTGT_48-2024$md$,$md$Điều 5. Đối tượng không chịu thuế$md$,$md$Đối tượng không chịu thuế
1. Sản phẩm cây trồng, rừng trồng, chăn nuôi, thủy sản nuôi trồng, đánh bắt
chưa chế biến thành các sản phẩm khác hoặc chỉ qua sơ chế thông thường của tổ
chức, cá nhân tự sản xuất, đánh bắt bán ra và ở khâu nhập khẩu.
2. Sản phẩm giống vật nuôi theo quy định của pháp luật về chăn nuôi, vật liệu
nhân giống cây trồng theo quy định của pháp luật về trồng trọt.
3. Thức ăn chăn nuôi theo quy định của pháp luật về chăn nuôi; thức ăn thủy
sản theo quy định của pháp luật về thủy sản.
4. Sản phẩm muối được sản xuất từ nước biển, muối mỏ tự nhiên, muối tinh,
muối i-ốt mà thành phần chính là Na-tri-clo-rua (NaCl).
5. Nhà ở thuộc tài sản công do Nhà nước bán cho người đang thuê.
6. Tưới, tiêu nước; cày, bừa đất; nạo vét kênh, mương nội đồng phục vụ sản
xuất nông nghiệp; dịch vụ thu hoạch sản phẩm nông nghiệp.
7. Chuyển quyền sử dụng đất.
8. Bảo hiểm nhân thọ, bảo hiểm sức khỏe, bảo hiểm người học, các dịch vụ
bảo hiểm khác liên quan đến con người; bảo hiểm vật nuôi, bảo hiểm cây trồng,
các dịch vụ bảo hiểm nông nghiệp khác; bảo hiểm tàu, thuyền, trang thiết bị và
các dụng cụ cần thiết khác phục vụ trực tiếp đánh bắt thủy sản; tái bảo hiểm;
bảo hiểm các công trình, thiết bị dầu khí, tàu chứa dầu mang quốc tịch nước
ngoài do nhà thầu dầu khí hoặc nhà thầu phụ nước ngoài thuê để hoạt động tại
vùng biển Việt Nam, vùng biển chồng lấn mà Việt Nam và các quốc gia có bờ
biển tiếp liền hay đối diện đã thỏa thuận đặt dưới chế độ khai thác chung.
9. Các dịch vụ tài chính, ngân hàng, kinh doanh chứng khoán, thương mại
sau đây:
a) Dịch vụ cấp tín dụng theo quy định của pháp luật về các tổ chức tín dụng và
các khoản phí được nêu cụ thể tại Hợp đồng vay vốn của Chính phủ Việt Nam với
Bên cho vay nước ngoài;
b) Dịch vụ cho vay của người nộp thuế không phải là tổ chức tín dụng;
c) Kinh doanh chứng khoán bao gồm môi giới chứng khoán, tự doanh chứng
khoán, bảo lãnh phát hành chứng khoán, tư vấn đầu tư chứng khoán, quản lý quỹ
đầu tư chứng khoán, quản lý danh mục đầu tư chứng khoán theo quy định của pháp
luật về chứng khoán;
d) Chuyển nhượng vốn bao gồm chuyển nhượng một phần hoặc toàn bộ số vốn
đã đầu tư vào tổ chức kinh tế khác (không phân biệt có thành lập hay không thành
lập pháp nhân mới), chuyển nhượng chứng khoán, chuyển nhượng quyền góp vốn
và các hình thức chuyển nhượng vốn khác theo quy định của pháp luật, kể cả
trường hợp bán doanh nghiệp cho doanh nghiệp khác để sản xuất, kinh doanh và
doanh nghiệp mua kế thừa toàn bộ quyền và nghĩa vụ của doanh nghiệp bán theo
quy định của pháp luật. Chuyển nhượng vốn quy định tại điểm này không bao gồm
chuyển nhượng dự án đầu tư, bán tài sản;
đ) Bán nợ bao gồm bán khoản phải trả và khoản phải thu;
e) Kinh doanh ngoại tệ;
g) Sản phẩm phái sinh theo quy định của pháp luật về các tổ chức tín dụng,
pháp luật về chứng khoán và pháp luật về thương mại, bao gồm: hoán đổi lãi suất;
hợp đồng kỳ hạn; hợp đồng tương lai; hợp đồng quyền chọn mua, chọn bán và sản
phẩm phái sinh khác;
h) Bán tài sản bảo đảm của khoản nợ của tổ chức mà Nhà nước sở hữu 100%
vốn điều lệ do Chính phủ thành lập có chức năng mua, bán nợ để xử lý nợ xấu của
các tổ chức tín dụng Việt Nam.
10. Các dịch vụ y tế, dịch vụ thú y sau đây:
a) Dịch vụ y tế bao gồm: dịch vụ khám bệnh, chữa bệnh, phòng bệnh cho
người, dịch vụ sinh đẻ có kế hoạch, dịch vụ điều dưỡng sức khỏe, phục hồi chức
năng cho người bệnh; dịch vụ chăm sóc người cao tuổi, người khuyết tật; vận
chuyển người bệnh, dịch vụ cho thuê phòng bệnh, giường bệnh của các cơ sở y tế;
xét nghiệm, chiếu, chụp; máu và chế phẩm máu dùng cho người bệnh.
Dịch vụ chăm sóc người cao tuổi, người khuyết tật bao gồm cả chăm sóc về y
tế, dinh dưỡng và tổ chức các hoạt động văn hóa, thể thao, giải trí, vật lý trị liệu,
phục hồi chức năng cho người cao tuổi, người khuyết tật.
Trường hợp trong gói dịch vụ chữa bệnh theo quy định của Bộ Y tế bao gồm
cả sử dụng thuốc chữa bệnh thì khoản thu từ tiền thuốc chữa bệnh nằm trong gói
dịch vụ chữa bệnh cũng thuộc đối tượng không chịu thuế giá trị gia tăng;
b) Dịch vụ thú y bao gồm: dịch vụ khám bệnh, chữa bệnh, phòng bệnh cho
vật nuôi.
11. Dịch vụ tang lễ.
12. Hoạt động duy tu, sửa chữa, xây dựng bằng nguồn vốn đóng góp của
nhân dân, vốn viện trợ nhân đạo (chiếm từ 50% tổng số vốn sử dụng cho công
trình trở lên) đối với các di tích lịch sử - văn hóa, danh lam thắng cảnh, các
công trình văn hóa, nghệ thuật, công trình phục vụ công cộng, cơ sở hạ tầng và
nhà ở cho đối tượng chính sách xã hội.
13. Hoạt động dạy học, dạy nghề theo quy định của pháp luật về giáo dục, giáo
dục nghề nghiệp.
14. Phát sóng truyền thanh, truyền hình bằng nguồn vốn ngân sách nhà nước.
15. Xuất bản, nhập khẩu, phát hành báo, tạp chí, bản tin, đặc san, sách chính
trị, sách giáo khoa, giáo trình, sách văn bản pháp luật, sách khoa học - kỹ thuật,
sách phục vụ thông tin đối ngoại, sách in bằng chữ dân tộc thiểu số và tranh, ảnh,
áp phích tuyên truyền cổ động, kể cả dưới dạng băng hoặc đĩa ghi tiếng, ghi hình,
dữ liệu điện tử; tiền, in tiền.
16. Vận chuyển hành khách công cộng bằng xe buýt, tàu điện, phương tiện
thủy nội địa.
17. Máy móc, thiết bị, phụ tùng, vật tư thuộc loại trong nước chưa sản xuất
được cần nhập khẩu để sử dụng trực tiếp cho hoạt động nghiên cứu khoa học, phát
triển công nghệ; máy móc, thiết bị, phụ tùng thay thế, phương tiện vận tải chuyên
dùng và vật tư thuộc loại trong nước chưa sản xuất được cần nhập khẩu để tiến
hành hoạt động tìm kiếm thăm dò, phát triển mỏ dầu khí; máy bay, trực thăng, tàu
lượn, giàn khoan, tàu thuyền thuộc loại trong nước chưa sản xuất được cần nhập
khẩu để tạo tài sản cố định của doanh nghiệp hoặc thuê của nước ngoài để sử dụng
cho sản xuất, kinh doanh, cho thuê.
18. Sản phẩm quốc phòng, an ninh theo danh mục do Bộ trưởng Bộ Quốc phòng,
Bộ trưởng Bộ Công an ban hành; sản phẩm, dịch vụ nhập khẩu phục vụ công nghiệp
quốc phòng, an ninh theo danh mục do Thủ tướng Chính phủ ban hành.
19. Hàng hóa nhập khẩu trong trường hợp viện trợ nhân đạo, viện trợ không
hoàn lại. Hàng hóa, dịch vụ bán cho tổ chức, cá nhân nước ngoài, tổ chức quốc tế
để viện trợ nhân đạo, viện trợ không hoàn lại cho Việt Nam.
20. Hàng hóa chuyển khẩu, quá cảnh qua lãnh thổ Việt Nam; hàng tạm nhập
khẩu, tái xuất khẩu; hàng tạm xuất khẩu, tái nhập khẩu; nguyên liệu nhập khẩu để
sản xuất, gia công hàng hóa xuất khẩu theo hợp đồng sản xuất, gia công xuất khẩu
ký kết với bên nước ngoài; hàng hóa, dịch vụ được mua bán giữa nước ngoài với
các khu phi thuế quan và giữa các khu phi thuế quan với nhau.
Hàng hóa nhập khẩu từ nước ngoài của công ty cho thuê tài chính được vận
chuyển thẳng vào khu phi thuế quan để cho doanh nghiệp trong khu phi thuế quan
thuê tài chính.
21. Chuyển giao công nghệ theo quy định của Luật Chuyển giao công nghệ;
chuyển nhượng quyền sở hữu trí tuệ theo quy định của Luật Sở hữu trí tuệ; sản
phẩm phần mềm và dịch vụ phần mềm theo quy định của pháp luật.
22. Vàng dạng thỏi, miếng chưa được chế tác thành sản phẩm mỹ nghệ, đồ
trang sức hay sản phẩm khác ở khâu nhập khẩu.
23. Sản phẩm xuất khẩu là tài nguyên, khoáng sản khai thác chưa chế biến
thành sản phẩm khác và sản phẩm xuất khẩu là tài nguyên, khoáng sản khai thác đã
chế biến thành sản phẩm khác theo Danh mục do Chính phủ quy định phù hợp với
định hướng của nhà nước về không khuyến khích xuất khẩu, hạn chế xuất khẩu các
tài nguyên, khoáng sản thô.
24. Sản phẩm nhân tạo dùng để thay thế cho bộ phận cơ thể của người bệnh,
bao gồm cả sản phẩm là bộ phận cấy ghép lâu dài trong cơ thể người; nạng, xe lăn
và dụng cụ chuyên dùng khác cho người khuyết tật.
25. Hàng hóa, dịch vụ của hộ, cá nhân sản xuất, kinh doanh có mức doanh thu
hằng năm từ 200 triệu đồng trở xuống; tài sản của tổ chức, cá nhân không kinh
doanh, không phải là người nộp thuế giá trị gia tăng bán ra; hàng dự trữ quốc gia
do cơ quan dự trữ quốc gia bán ra; các khoản thu phí, lệ phí theo quy định của
pháp luật về phí và lệ phí.
26. Hàng hóa nhập khẩu trong trường hợp sau đây:
a) Quà tặng cho cơ quan nhà nước, tổ chức chính trị, tổ chức chính trị - xã hội,
tổ chức chính trị xã hội - nghề nghiệp, tổ chức xã hội, tổ chức xã hội - nghề
nghiệp, đơn vị vũ trang nhân dân trong định mức miễn thuế nhập khẩu theo quy
định của pháp luật về thuế xuất khẩu, thuế nhập khẩu;
b) Quà biếu, quà tặng trong định mức miễn thuế nhập khẩu theo quy định của
pháp luật về thuế xuất khẩu, thuế nhập khẩu của tổ chức, cá nhân nước ngoài cho
